# ==========================================================================
# PDF special-character handling
# ==========================================================================
# Ordinary English text remains text. Greek/math glyphs use PDF's Symbol encoding.
# This changes label encoding only, never data or statistical values.
pdf_math_label <- function(s) {
  if(is.na(s))return(NA_character_)
  s<-gsub("\u2212","-",s,fixed=TRUE)
  special<-c("\u03c1"="rho","\u0394"="Delta","\u03c4"="tau","\u03b2"="beta",
             "\u2264"="<=","\u2265"=">=","\u00b2"="sup2")
  chars<-strsplit(s,"",fixed=TRUE)[[1L]]
  if(!any(chars %in% names(special)))return(s)
  parts<-list();buffer<-""
  flush<-function(){if(nzchar(buffer)){parts[[length(parts)+1L]]<<-buffer;buffer<<-""}}
  for(ch in chars) {
    if(!ch %in% names(special)){buffer<-paste0(buffer,ch);next}
    flush();sym<-special[[ch]]
    parts[[length(parts)+1L]]<-switch(sym,
      sup2=quote(phantom(0)^2),"<="=quote(phantom(0)<=phantom(0)),
      ">="=quote(phantom(0)>=phantom(0)),as.name(sym))
  }
  flush();as.call(c(list(as.name("paste")),parts))
}
pdf_math_text <- function(g) {
  if(inherits(g,"text")&&is.character(g$label)){
    vals<-lapply(g$label,pdf_math_label)
    if(any(vapply(vals,is.language,logical(1))))g$label<-as.expression(vals)
    else g$label<-vapply(vals,identity,character(1))
  }
  if(!is.null(g$grobs))g$grobs<-lapply(g$grobs,pdf_math_text)
  if(!is.null(g$children))g$children<-do.call(grid::gList,lapply(g$children,pdf_math_text))
  g
}


