# Snapshot-specific identity correction. This is NOT a general annotation service.
# All source rows, annotation tables and final identities are fingerprint-gated.
identity_hash <- function(d) {
  stopifnot(is.data.frame(d),!anyDuplicated(names(d)))
  encode <- function(x) {x<-as.character(x);x[is.na(x)]<-'';
    x<-enc2utf8(x);paste0(nchar(x,type='bytes'),':',x)}
  header<-paste(encode(names(d)),collapse='|')
  lines<-if(nrow(d))do.call(paste,c(lapply(d,encode),sep='|'))else character()
  f<-tempfile();on.exit(unlink(f),add=TRUE)
  writeLines(c(header,lines),f,useBytes=TRUE)
  unname(tools::md5sum(f))
}
identity_lookup <- function(genes,aliases) {
  stopifnot(identical(names(genes),c('gene_id','symbol')),
    identical(names(aliases),c('gene_id','alias_symbol')),
    !anyNA(genes),!anyNA(aliases),!anyDuplicated(genes$gene_id))
  if(identity_hash(genes)!=IDENTITY_ANNOTATION_HASH[['genes']] ||
     identity_hash(aliases)!=IDENTITY_ANNOTATION_HASH[['aliases']])
    stop('Original org.Hs.eg.db annotation content differs; no reannotation or download attempted.')
  list(symbol=list2env(split(genes$gene_id,genes$symbol),hash=TRUE,parent=emptyenv()),
       alias=list2env(split(aliases$gene_id,aliases$alias_symbol),hash=TRUE,parent=emptyenv()),
       display=setNames(genes$symbol,genes$gene_id))
}
identity_lookup_installed <- function() {
  for(p in c('org.Hs.eg.db','AnnotationDbi','DBI'))
    if(!requireNamespace(p,quietly=TRUE))stop('Required original package missing: ',p)
  if(as.character(utils::packageVersion('org.Hs.eg.db'))!='3.21.0')
    stop('Expected original org.Hs.eg.db 3.21.0; no package installation attempted.')
  con<-AnnotationDbi::dbconn(org.Hs.eg.db::org.Hs.eg.db)
  genes<-DBI::dbGetQuery(con,paste('select g.gene_id,i.symbol from genes g',
    'join gene_info i using(_id) order by g.gene_id collate binary'))
  aliases<-DBI::dbGetQuery(con,paste('select g.gene_id,a.alias_symbol from genes g',
    'join alias a using(_id) order by g.gene_id collate binary,a.alias_symbol collate binary'))
  identity_lookup(genes,aliases)
}
identity_raw_ids <- function(x) {
  if(is.na(x)||!nzchar(x))return(character())
  z<-unique(trimws(strsplit(x,'\\s*///\\s*|\\s*;\\s*|\\s*,\\s*|\\s*\\|\\s*',perl=TRUE)[[1L]]))
  z<-z[!z%in%c('','---','NA','N/A')]
  if(!all(grepl('^[1-9][0-9]*$',z)))return(character())
  z
}
identity_base_one <- function(symbol,raw,eligible,lookup) {
  if(!isTRUE(eligible))return('')
  ids<-identity_raw_ids(raw)
  candidates<-unique(get0(symbol,envir=lookup$symbol,inherits=FALSE))
  if(!length(candidates))candidates<-unique(get0(symbol,envir=lookup$alias,inherits=FALSE))
  key<-''
  if(length(ids)==1L)key<-ids
  else if(length(ids)>1L){hit<-intersect(ids,candidates);if(length(hit)==1L)key<-hit}
  else if(length(candidates)==1L)key<-candidates
  if(nzchar(key))paste0('ENTREZ:',key)else ''
}
identity_apply <- function(d,lookup,table) {
  pin<-IDENTITY_TABLE_PINS[[table]]
  if(is.null(pin))stop('Unknown identity scope; never apply snapshot rules to other inputs: ',table)
  if(!all(pin$columns%in%names(d))||nrow(d)!=pin$rows||
     identity_hash(d[,pin$columns,drop=FALSE])!=pin$input_hash)
    stop('Original annotation rows/order/eligibility differ: ',table)
  key_col<-if('probe'%in%names(d))'probe'else 'source_symbol'
  eligible<-as.character(d$original_eligible)=='TRUE'
  raw<-if('raw_entrez'%in%names(d))d$raw_entrez else rep('',nrow(d))
  keys<-vapply(seq_len(nrow(d)),function(i)
    identity_base_one(d$source_symbol[i],raw[i],eligible[i],lookup),character(1))
  overrides<-IDENTITY_EXCEPTIONS[[table]]
  at<-match(names(overrides),d[[key_col]])
  if(anyNA(at)||anyDuplicated(at)||any(!eligible[at]))stop('Invalid identity exception application: ',table)
  keys[at]<-unname(overrides)
  result<-data.frame(key=as.character(d[[key_col]]),gene_id=keys,stringsAsFactors=FALSE)
  if(identity_hash(result)!=pin$output_hash)
    stop('Identity regression failed: ',table,'. No study statistics were run.')
  d$resolved_gene_id<-keys;d$proposed_gene_id<-keys
  d$action<-ifelse(nzchar(keys),'keep','exclude')
  d$method<-ifelse(eligible,'original_orgdb_plus_explicit_reviewed_rules','original_invalid_symbol_rule')
  d$method[at]<-'explicit_snapshot_identity_exception'
  d$review_status<-ifelse(d$action=='keep','reviewed_resolved','reviewed_excluded')
  d$evidence<-'Original platform + org.Hs.eg.db 3.21.0; explicit identity exceptions reviewed 2026-09-07; complete input and decision fingerprints verified'
  d$reason<-ifelse(d$action=='keep','Retain verified canonical identity','Exclude under the verified original eligibility or unresolved-identity decision')
  d
}
identity_display <- function(keys,lookup) {
  ids<-sub('^ENTREZ:','',keys)
  ans<-unname(lookup$display[ids]);ans[is.na(ans)]<-keys[is.na(ans)]
  at<-match(ids,names(IDENTITY_DISPLAY_EXCEPTIONS))
  ans[!is.na(at)]<-unname(IDENTITY_DISPLAY_EXCEPTIONS[at[!is.na(at)]])
  ans
}
identity_historical_features <- function(maps) {
  # CTAGE5 and MIA2 were separate frozen xCell model features. Never clone rows.
  rules<-list(GSE272769=c(CTAGE5='16783675',MIA2='16783662'),
    GSE95233=c(CTAGE5='1553944_at|204055_s_at|215930_s_at|235790_at',MIA2='221177_at'),
    GSE65682=c(CTAGE5='11731056_a_at|11731874_x_at|11755659_x_at',MIA2=''))
  rows<-list()
  for(cohort in names(rules))for(label in names(rules[[cohort]])) {
    m<-maps[[cohort]];if(is.null(m))stop('Missing original cohort map: ',cohort)
    candidate<-m$probe[m$source_symbol==label & m$original_eligible=='TRUE']
    expected<-rules[[cohort]][[label]]
    if(!identical(paste(candidate,collapse='|'),expected))
      stop('Original historical feature provenance changed: ',cohort,'/',label)
    if(length(candidate)) {
      ix<-match(candidate,m$probe)
      if(any(m$action[ix]!='keep')||any(m$resolved_gene_id[ix]!='ENTREZ:4253'))
        stop('Historical feature conflicts with corrected canonical identity')
    }
    rows[[length(rows)+1L]]<-data.frame(row_id=paste(cohort,label,sep='::'),cohort=cohort,
      source_symbol=label,candidate_probes=expected,action=if(nzchar(expected))'keep'else'exclude',
      approved_probes=expected,review_status=if(nzchar(expected))'reviewed_resolved'else'reviewed_excluded',
      evidence='Original labelled probe provenance; identity 4253; historical feature review 2026-09-07',
      reason=if(nzchar(expected))'Choose the maximum-variance original-labelled candidate; do not clone another model feature'else
        'No originally eligible MIA2-labelled probe; omit this model feature only',stringsAsFactors=FALSE)
  }
  do.call(rbind,rows)
}

