capture_original_caches <- function(out,env=.GlobalEnv) {
  # env is the restored PRE-AUDIT parent session. No package/update/download fallback.
  names_map<-c('001_GlobalEnv_.GO_clusterProfiler_Env.rds'='.GO_clusterProfiler_Env',
    '002_GlobalEnv_.GOTERM_Env.rds'='.GOTERM_Env',
    '003_GlobalEnv_.KEGG_clusterProfiler_Env.rds'='.KEGG_clusterProfiler_Env')
  missing<-unname(names_map)[!vapply(unname(names_map),exists,logical(1),envir=env,inherits=FALSE)]
  if(length(missing))stop('Original BULK cache missing: ',paste(missing,collapse=', '),
    '. This restored session cannot reproduce the pinned historical resource from available inputs. ',
    'No new resource pack, historical audit directory or online replacement was used.')
  if(dir.exists(out))stop('Refusing to overwrite an existing resource snapshot: ',out)
  objects<-list();receipt<-list()
  for(file in names(names_map)) {
    nm<-names_map[[file]]
    if(bindingIsActive(nm,env))stop('Active binding is not an inert original cache: ',nm)
    original<-get(nm,envir=env,inherits=FALSE)
    if(!is.environment(original)&&!is.list(original))stop('Invalid original cache class: ',nm)
    pins<-ORIGINAL_CACHE_PINS[ORIGINAL_CACHE_PINS$file==file,,drop=FALSE]
    if(!nrow(pins)||anyDuplicated(pins$binding))stop('Invalid in-script cache check metadata')
    z<-setNames(vector('list',nrow(pins)),pins$binding)
    for(i in seq_len(nrow(pins))) {
      key<-pins$binding[i]
      if(is.environment(original)) {
        if(!exists(key,original,inherits=FALSE)||bindingIsActive(key,original))
          stop('Original cache field missing/active: ',nm,'/',key)
        value<-get(key,original,inherits=FALSE)
      } else {
        if(!key%in%names(original))stop('Original cache field missing: ',nm,'/',key)
        value<-original[[key]]
      }
      if(pins$kind[i]=='data.frame'&&!is.data.frame(value))stop('Cache data class changed: ',key)
      if(pins$kind[i]=='character'&&!is.character(value))stop('Cache metadata class changed: ',key)
      actual<-local({
        f<-tempfile();on.exit(unlink(f))
        if(is.data.frame(value))write.table(value,f,sep='\t',quote=TRUE,row.names=FALSE,
          col.names=TRUE,na='NA',fileEncoding='UTF-8',eol='\n')
        else writeLines(enc2utf8(as.character(value)),f,useBytes=TRUE)
        unname(tools::md5sum(f))
      })
      if(!identical(actual,pins$md5[i]))stop('Historical cache content differs: ',nm,'/',key,
        '. No online refresh or substitute resource is allowed.')
      z[[key]]<-value
    }
    objects[[file]]<-z
    receipt[[file]]<-data.frame(file=file,parent_binding=nm,status='ORIGINAL_CACHE_CONTENT_VERIFIED',
      fields=nrow(pins),stringsAsFactors=FALSE)
  }
  # Only after ALL caches pass, write this run's input snapshots for the child process.
  stopifnot(dir.create(out,recursive=TRUE))
  for(file in names(objects))saveRDS(objects[[file]],file.path(out,file),version=3)
  do.call(rbind,receipt)
}

