write_font_match_report <- function(fonts,out,families) {
  # match_fonts() includes nested features/variations; write.csv() cannot encode lists.
  # Keep the full object in a run-generated RDS and scalar lookup fields in CSV.
  stopifnot(is.list(fonts),all(c('path','index')%in%names(fonts)),dir.exists(out),
    is.character(families),length(families)>0L,!anyNA(families),
    is.character(fonts$path),length(fonts$path)==length(families),
    length(fonts$index)==length(families),is.numeric(fonts$index),
    !anyNA(fonts$path),all(nzchar(fonts$path)),!anyNA(fonts$index),
    all(is.finite(fonts$index)),all(fonts$index>=0),
    all(fonts$index<=.Machine$integer.max),all(fonts$index==floor(fonts$index)))
  report<-data.frame(requested_family=families,path=fonts$path,
    index=as.integer(fonts$index),stringsAsFactors=FALSE)
  saveRDS(fonts,file.path(out,'svg_resolved_fonts.rds'),version=2)
  write.csv(report,file.path(out,'svg_resolved_fonts.csv'),row.names=FALSE)
  invisible(report)
}

original_object_fingerprint <- function(x) {
  # XDR serialization v2; normalize only the WRITER R version header, not data.
  b<-serialize(x,NULL,ascii=FALSE,version=2L,xdr=TRUE)
  stopifnot(length(b)>14L,identical(b[1:6],as.raw(c(88,10,0,0,0,2))))
  b[7:10]<-as.raw(rep(0L,4L))
  p<-tempfile();on.exit(unlink(p),add=TRUE);writeBin(b,p)
  unname(tools::md5sum(p))
}
xcell_parameter_fingerprint <- function(x) {
  # Hash scientific content, not R serialize()'s object-storage representation.
  # Values use exact big-endian binary doubles: no rounding or tolerance change.
  # Preserve list/vector order, types, dimensions, names and attribute values.
  # Attribute storage order and compact data-frame row-name storage are immaterial.
  p<-tempfile();con<-file(p,'wb')
  on.exit({try(close(con),silent=TRUE);unlink(p)},add=TRUE)
  size<-function(n) {
    if(length(n)!=1L||is.na(n)||n<0||n>.Machine$integer.max)stop('Invalid xCell field length')
    writeBin(as.integer(n),con,size=4L,endian='big')
  }
  string<-function(s) {
    if(is.na(s)){writeBin(as.integer(-1),con,size=4L,endian='big');return(invisible(NULL))}
    b<-charToRaw(enc2utf8(s));size(length(b));writeBin(b,con)
  }
  visit<-function(v) {
    type<-typeof(v)
    if(isS4(v)||!type%in%c('NULL','list','double','integer','logical','character','raw'))
      stop('Unsupported xCell parameter type: ',type)
    string(type);size(length(v))
    switch(type,
      list={for(i in seq_along(v))visit(v[[i]])},
      double=writeBin(as.double(v),con,size=8L,endian='big'),
      integer=writeBin(as.integer(v),con,size=4L,endian='big'),
      logical=writeBin(as.integer(v),con,size=4L,endian='big'),
      character={for(i in seq_along(v))string(v[[i]])},
      raw=writeBin(v,con))
    an<-sort(as.character(names(attributes(v))),method='radix');size(length(an))
    for(n in an){string(n);visit(attr(v,n,exact=TRUE))}
    invisible(NULL)
  }
  string('XCELL_PARAMETER_CONTENT_V1');visit(x);close(con)
  unname(tools::md5sum(p))
}
xcell_model_fingerprints <- function(z) {
  fields<-c('spill','spill.array','signatures','genes')
  if(!is.list(z)||!identical(names(z),fields))stop('xCell model field structure changed')
  c(vapply(z[fields[1:2]],xcell_parameter_fingerprint,character(1)),
    vapply(z[fields[3:4]],original_object_fingerprint,character(1)))
}
original_xcell_resource <- function() {
  for(p in c('xCell','GSEABase'))if(!requireNamespace(p,quietly=TRUE))
    stop('Required original package missing: ',p)
  if(as.character(utils::packageVersion('xCell'))!='1.1.0')
    stop('Original xCell 1.1.0 required; no package download attempted.')
  target<-new.env(parent=emptyenv())
  utils::data(list='xCell.data',package='xCell',envir=target)
  if(!exists('xCell.data',envir=target,inherits=FALSE))stop('Installed xCell model data missing')
  z<-get('xCell.data',envir=target,inherits=FALSE)
  fields<-c('spill','spill.array','signatures','genes')
  if(!all(fields%in%names(z)))stop('Installed xCell resource structure changed')
  z<-z[fields]
  if(length(z$genes)!=10808L||length(z$signatures)!=489L)
    stop('xCell dimensions differ: genes=',length(z$genes),'; signatures=',length(z$signatures))
  actual<-xcell_model_fingerprints(z)
  bad<-names(actual)[actual!=ORIGINAL_XCELL_COMPONENT_FINGERPRINTS[names(actual)]]
  if(length(bad))stop('xCell scientific model content differs; no substitute used: ',
    paste(paste0(bad,' expected=',ORIGINAL_XCELL_COMPONENT_FINGERPRINTS[bad],
      ' actual=',actual[bad]),collapse='; '))
  cat('PASS: installed original xCell genes, signatures and exact parameter content verified.\n')
  z
}

original_ora_inputs <- function(project,lookup,signature_map) {
 root<-file.path(project,'results_meta')
 read<-function(rel)read.csv(file.path(root,rel),stringsAsFactors=FALSE,check.names=FALSE)
 old<-readRDS(file.path(root,'03_discovery_figs/checkpoint_s3.rds'))
 s1<-readRDS(file.path(root,'01_data_prep/checkpoint_s1.rds'))
 updates<-read('03_discovery_figs/GO_KEGG_symbol_updates.csv')
 symbols<-s1$common_genes;at<-match(symbols,updates$original_symbol)
 symbols[!is.na(at)]<-updates$annotation_symbol[at[!is.na(at)]]
 # Reproduce original SYMBOL->ENTREZID mapping, not current canonical background.
 universe<-unique(unlist(lapply(symbols,function(s)get0(s,lookup$symbol,inherits=FALSE)),use.names=FALSE))
 stopifnot(length(universe)==16607L)
 rm(s1)
 signature_map<-signature_map[signature_map$action=='keep',,drop=FALSE]
 bridge<-setNames(sub('^ENTREZ:','',signature_map$resolved_gene_id),signature_map$source_symbol)
 e3<-read('08_Giannini_sensitivity/Table_Giannini_E3_full_32gene_comparison.csv')
 ext<-read('08_Giannini_sensitivity/Table_Giannini_E3_externally_evaluable_residual_mapping.csv')
 stopifnot(nrow(e3)==32L,setequal(e3$signature_gene,names(bridge)))
 membership<-data.frame(gene_id=unname(bridge[e3$signature_gene]),
   source_symbol=e3$signature_gene,canonical_symbol=e3$canonical_gene,
   legacy_direction=e3$discovery_direction,in_e3=e3$reported_in_Giannini_E3,
   legacy_external_residual=unname(bridge[e3$signature_gene])%in%as.character(ext$ENTREZID),
   stringsAsFactors=FALSE)
 stopifnot(!anyNA(membership),sum(membership$in_e3)==15L)
 query<-list(up=membership$gene_id[membership$legacy_direction=='Up'],
   down=membership$gene_id[membership$legacy_direction=='Down'],
   residual_up=membership$gene_id[membership$legacy_direction=='Up'&!membership$in_e3],
   external_residual_up=membership$gene_id[membership$legacy_direction=='Up'&!membership$in_e3&membership$legacy_external_residual])
 stopifnot(identical(as.integer(lengths(query)),c(29L,3L,16L,14L)))
 queries<-do.call(rbind,lapply(names(query),function(k)data.frame(set_id=k,gene_id=query[[k]])))
 base_columns<-c('ID','Description','GeneRatio','BgRatio','RichFactor','FoldEnrichment',
   'zScore','pvalue','p.adjust','qvalue','geneID','Count')
 bridge<-c(bridge,setNames(unname(bridge[updates$original_symbol]),updates$annotation_symbol))
 normalize_members<-function(x) vapply(strsplit(as.character(x),'/',fixed=TRUE),function(v){
   symbolic<-!grepl('^[1-9][0-9]*$',v)
   v[symbolic]<-unname(bridge[v[symbolic]])
   if(anyNA(v)||any(!grepl('^[1-9][0-9]*$',v)))stop('Unresolved original ORA query identifier')
   paste(sort(unique(v)),collapse='/')
 },character(1))
 refs<-list();gs<-list();effective<-list();categories<-list();idx<-0L
 for(db in c('GO','KEGG'))for(k in names(query)) {
   idx<-idx+1L;primary<-k%in%c('up','down')
   if(primary) {
     obj<-old[[paste0('enrich_',k)]][[db]]
     d<-attr(obj,'result')
     g<-attr(obj,'geneSets')
     gs[[length(gs)+1L]]<-data.frame(database=db,set_id=k,
       term=rep(names(g),lengths(g)),gene_id=unlist(g,use.names=FALSE),stringsAsFactors=FALSE)
     u<-as.character(attr(obj,'universe'))
     if(k=='up')effective[[db]]<-data.frame(database=db,gene_id=u)
     else stopifnot(setequal(u,effective[[db]]$gene_id))
   } else {
     stem<-if(k=='residual_up')'Table_Giannini_E3_residual_'else 'Table_Giannini_E3_externally_evaluable_residual_'
     tail<-if(db=='GO')'GO_BP'else 'KEGG'
     suffix<-if(k=='residual_up')'_enrichment.csv'else '.csv'
     d<-read(paste0('08_Giannini_sensitivity/',stem,tail,suffix))
   }
   stopifnot(all(base_columns%in%names(d)))
   if(db=='KEGG')categories[[length(categories)+1L]]<-d[,c('ID','category','subcategory'),drop=FALSE]
   d<-d[,base_columns,drop=FALSE];d$geneID<-normalize_members(d$geneID)
   d$database<-db;d$set_id<-k;refs[[idx]]<-d
 }
 categories<-unique(do.call(rbind,categories))
 # The original exported category dictionary uses empty text for unavailable labels.
 for(col in c('category','subcategory'))categories[[col]][is.na(categories[[col]])]<-''
 stopifnot(!anyDuplicated(categories$ID),nrow(categories)==87L)
 reference<-do.call(rbind,refs)
 stopifnot(nrow(reference)==2100L)
 list(membership=membership,queries=queries,reference=reference,
   geneSets=do.call(rbind,gs),effective=do.call(rbind,effective),
   universe=data.frame(ENTREZID=universe),categories=categories)
}

# Compact expected checksums can be kept as R test constants instead of embedding
# previous scientific datasets. This is fingerprint validation, NOT the old
# pairwise rtol/atol comparison. A mismatch blocks adoption; never overwrite the
# expected fingerprint with this run's value. The numeric profile is explicit:
# 11 significant decimal digits plus exact sign, zero and decision-boundary bits.
# Exact file checks compiled from pre-existing, checksum-verified references, not this run.
# These two CSVs are byte-identical across platforms despite differing numeric-format fingerprints.
SCIENCE_EXACT_CSV_PINS <- c(
  "downstream/models/validation_only/DE_all_genes.csv" = "7e8bfeed01d1a22d827d26ab545177c1",
  "downstream/models/validation_only/old_new_all_old_rows_comparison.csv" = "3a9498f53087e4ae89c2a72f80777533"
)

write_original_csv_exact <- function(d,path) {
  # Preserve binary-double precision from ORIGINAL RData/RDS when staging CSV.
  # This changes only new intermediate reference serialization, not statistics.
  stopifnot(is.data.frame(d),!any(vapply(d,is.list,logical(1))))
  z<-d
  for(n in names(z))if(is.double(z[[n]])) {
    x<-z[[n]];s<-trimws(formatC(x,digits=17,format='g',decimal.mark='.'))
    s[is.na(x)&!is.nan(x)]<-NA_character_;z[[n]]<-s
  }
  write.csv(z,path,row.names=FALSE,na='',fileEncoding='UTF-8')
  invisible(path)
}
scientific_result_matches <- function(actual,expected,raw_expected=NA_character_,raw_actual=NA_character_) {
  identical(actual,expected)||
    (length(raw_expected)==1L&&length(raw_actual)==1L&&!is.na(raw_expected)&&!is.na(raw_actual)&&
     nzchar(raw_expected)&&identical(raw_actual,raw_expected))
}

scientific_fingerprint <- function(x) {
  file<-tempfile();con<-base::file(file,'wb')
  on.exit({try(close(con),silent=TRUE);unlink(file)},add=TRUE)
  put<-function(tag,values=character()) {
    values<-enc2utf8(as.character(values));missing<-is.na(values)
    values[missing]<-''
    encoded<-paste0(ifelse(missing,'NA','T'),nchar(values,type='bytes'),':',values)
    writeLines(c(paste0(tag,'#',length(encoded)),encoded),con,useBytes=TRUE)
  }
  numbers<-function(v,name) {
    tokens<-rep('NA',length(v));tokens[is.nan(v)]<-'NaN'
    tokens[is.infinite(v)&v>0]<-'+Inf';tokens[is.infinite(v)&v<0]<-'-Inf'
    ok<-is.finite(v);a<-v[ok];a[a==0]<-0
    # Discrete analysis parameters and counts must not be rounded.
    discrete<-name%in%c('Count','size','effective_size','n_candidate_probes','iteration',
      'pool_size','signature_total','evaluable','random_sets','exceedances','seed','draw_indices')
    decimal<-if(discrete)formatC(a,digits=17,format='g',decimal.mark='.') else
      formatC(a,digits=10,format='e',decimal.mark='.')
    bits<-paste0('s',sign(a),'z',as.integer(a==0))
    for(cut in c(.001,.01,.05,.1,.2,.3,.5,.7,1))
      bits<-paste0(bits,as.integer(a<cut),as.integer(a<=cut),
        as.integer(abs(a)>cut),as.integer(abs(a)>=cut))
    tokens[ok]<-paste0(decimal,'/',bits)
    tokens
  }
  walk<-function(z,name='') {
    if(is.null(z)){put('NULL');return(invisible(NULL))}
    if(is.factor(z))z<-as.character(z)
    if(isS4(z)||is.environment(z)||is.function(z)||is.language(z)||is.pairlist(z))
      stop('Fingerprint requires an explicit scientific projection, not code, S4 or environments: ',name)
    put('NAMES',names(z));put('DIM',dim(z))
    dn<-dimnames(z);put('DIMNAMES_COUNT',length(dn))
    if(length(dn))for(i in seq_along(dn))put(paste0('AXIS',i),dn[[i]])
    if(is.data.frame(z)) {
      put('DATAFRAME',c(nrow(z),ncol(z)))
      for(n in names(z))walk(z[[n]],n)
    }else if(is.list(z)) {
      put('LIST',length(z))
      for(i in seq_along(z))walk(z[[i]],if(is.null(names(z)))as.character(i)else names(z)[i])
    }else if(is.numeric(z))put('NUMERIC',numbers(as.vector(z),name))
    else if(is.character(z))put('CHARACTER',as.vector(z))
    else if(is.logical(z))put('LOGICAL',as.vector(z))
    else stop('Unsupported scientific fingerprint type: ',typeof(z))
    invisible(NULL)
  }
  put('PROFILE','ordered-science-v1-11sig-exact-decisions');walk(x)
  close(con);unname(tools::md5sum(file))
}
scientific_csv_object <- function(d,numeric_columns) {
  if(!is.data.frame(d)||anyDuplicated(names(d))||!all(numeric_columns%in%names(d)))
    stop('Scientific CSV schema differs')
  for(n in numeric_columns) {
    original<-d[[n]];value<-suppressWarnings(as.numeric(original))
    if(any(is.na(value)&!is.na(original)&!as.character(original)%in%c('','NA','NaN')))
      stop('Malformed scientific numeric column: ',n)
    d[[n]]<-value
  }
  d
}

