make_analysis_engine <- function() {

# ==========================================================================
# Main analysis orchestration and helpers
# ==========================================================================
# Consolidated no-plot main adapter v2026-09-07.1.
bulk_run_main <- function(ctx) {
  required <- c("project", "bundle_dir", "out_dir")
  stopifnot(is.list(ctx), all(required %in% names(ctx)))
  for (field in required) {
    value <- ctx[[field]]
    stopifnot(is.character(value), length(value) == 1L, !is.na(value), nzchar(value),
      grepl("^(/|[A-Za-z]:[/\\\\])", value), dir.exists(value))
  }
  project <- normalizePath(ctx$project, mustWork = TRUE)
  bundle <- normalizePath(file.path(ctx$bundle_dir, "main"), mustWork = TRUE)
  out <- file.path(normalizePath(ctx$out_dir, mustWork = TRUE), "main")
  stopifnot(!file.exists(out))
  stopifnot(dir.create(out))
  # Helpers live only in this function invocation; never source the old CLI entry or 05.R.
  

# ==========================================================================
# Gene identity, DE, Meta, random reference, GSEA and xCell helpers
# ==========================================================================
# BULK bulk reanalysis v2026-09-06.1. Functions only; no analysis on sourcing.
# Do not source the historical scripts. No downloads, package installs or updates.
assert <- function(ok, message) {
  if (!isTRUE(ok)) stop(message, call. = FALSE)
}
write_csv <- function(x, path) {
  assert(!file.exists(path), paste("Refusing to overwrite:", path))
  utils::write.csv(x, path, row.names = FALSE, na = "", fileEncoding = "UTF-8")
}
save_new <- function(x, path) {
  assert(!file.exists(path), paste("Refusing to overwrite:", path))
  saveRDS(x, path, version = 3)
}
read_csv <- function(path) utils::read.csv(path, check.names = FALSE,
  stringsAsFactors = FALSE, colClasses = "character", na.strings = NULL)
md5 <- function(path) unname(tools::md5sum(path))
check_manifest <- function(manifest, root) {
  p <- file.path(root, manifest$path)
  assert(all(file.exists(p)), paste("Missing frozen inputs:",
    paste(p[!file.exists(p)], collapse = "\n")))
  actual <- unname(vapply(p, md5, character(1)))
  assert(identical(tolower(actual), tolower(manifest$md5)),
    paste("Frozen input checksum mismatch:",
      paste(p[tolower(actual) != tolower(manifest$md5)], collapse = "\n")))
  data.frame(path = p, bytes = file.info(p)$size, md5 = actual)
}
invalid_symbol <- function(x) is.na(x) | !nzchar(x) |
  x %in% c("---", "NA", "N/A") | nchar(x) > 30L
split_nonempty <- function(x, sep = "\\|") {
  if (is.na(x) || !nzchar(x)) return(character())
  z <- trimws(unlist(strsplit(x, sep, perl = TRUE), use.names = FALSE))
  unique(z[!is.na(z) & nzchar(z) & !z %in% c("---", "NA", "N/A")])
}
# Parsing stage only: actual decisions are applied after exact original-input checks.
propose_identity <- function(symbol,entrez_text,h,resource=FALSE) {
  data.frame(proposed_gene_id='',action='pending',resolved_gene_id='',method='awaiting_pinned_rules',
    symbol_candidates='',entrez_candidates=entrez_text,reason='No identity decision before complete snapshot validation',stringsAsFactors=FALSE)
}
platform_map <- function(tab, platform, probe_ids, h) {
  assert("ID" %in% names(tab), paste(platform, "lacks ID"))
  assert(!anyDuplicated(tab$ID), paste(platform, "duplicated probe annotations"))
  getcol <- function(n) { assert(n %in% names(tab), paste(platform, "lacks", n));
    as.character(tab[[n]]) }
  if (platform == "GPL17692") {
    assignment <- getcol("gene_assignment")
    blocks <- strsplit(assignment, " /// ", fixed = TRUE)
    first <- vapply(blocks, function(z) if (length(z)) z[1L] else "", character(1))
    parts <- strsplit(first, " // ", fixed = TRUE)
    symbol <- vapply(parts, function(z) if (length(z) >= 2L) trimws(z[2L]) else "", character(1))
    entrez <- vapply(parts, function(z) if (length(z) >= 5L) trimws(z[length(z)]) else "", character(1))
    # Original workflow used the first gene_assignment block. Keep that target
    # rule, but retain the complete assignment string in the evidence table.
  } else {
    assignment <- getcol("Gene Symbol")
    parse_sep <- if (platform == "GPL570") " /// " else
      "\\s*///\\s*|\\s*;\\s*|\\s*,\\s*|\\s*\\|\\s*"
    symbol <- vapply(strsplit(assignment, parse_sep, perl = TRUE), function(z) {
      z <- trimws(z)
      if (platform == "GPL13667") z <- z[!invalid_symbol(z)]
      if (length(z)) z[1L] else ""
    }, character(1))
    entrez <- getcol(if (platform == "GPL570") "ENTREZ_GENE_ID" else "Entrez Gene")
  }
  at <- match(probe_ids, tab$ID)
  symbol <- symbol[at]; symbol[is.na(symbol)] <- ""
  entrez <- entrez[at]; entrez[is.na(entrez)] <- ""
  prop <- do.call(rbind, lapply(seq_along(probe_ids), function(i) {
    if (invalid_symbol(symbol[i])) return(data.frame(proposed_gene_id = "",
      action = "exclude", resolved_gene_id = "", method = "original_invalid_symbol_rule",
      symbol_candidates = "", entrez_candidates = entrez[i],
      reason = "Original probe eligibility rule; not an HGNC-unmapped exclusion"))
    propose_identity(symbol[i], entrez[i], h)
  }))
  data.frame(row_id = paste(platform, probe_ids, sep = "::"), scope = platform,
    probe = probe_ids, source_symbol = symbol, raw_assignment = assignment[at],
    raw_entrez = entrez, prop, check.names = FALSE, stringsAsFactors = FALSE)
}
resource_map <- function(symbols,scope,h) {
  symbols<-sort(unique(as.character(symbols)))
  data.frame(row_id=paste(scope,symbols,sep='::'),scope=scope,source_symbol=symbols,
    original_eligible='TRUE',stringsAsFactors=FALSE)
}
collapse_probes <- function(expr, map, key_column, keep) {
  assert(!anyDuplicated(rownames(expr)), "Duplicated expression probe IDs")
  at <- match(rownames(expr), map$probe)
  assert(!anyNA(at), "Probe evidence must cover every expression row")
  map <- map[at, , drop = FALSE]
  ix <- which(keep[at])
  assert(length(ix) > 0L, "No eligible probes")
  keys <- as.character(map[[key_column]][ix])
  assert(all(!is.na(keys) & nzchar(keys)), "Empty included gene key")
  groups <- split(ix, keys)
  variances <- apply(expr, 1L, stats::var, na.rm = TRUE)
  chosen <- vapply(groups, function(z) {
    v <- variances[z]
    if (all(is.na(v))) z[1L] else z[which.max(v)]
  }, integer(1))
  mat <- expr[chosen, , drop = FALSE]; rownames(mat) <- names(groups)
  assert(all(is.finite(mat)), "Selected gene expression contains non-finite values")
  list(matrix = mat, selection = data.frame(gene_id = names(groups),
    selected_probe = rownames(expr)[chosen], source_symbol = map$source_symbol[chosen],
    variance = variances[chosen], n_candidate_probes = lengths(groups),
    candidate_probes = vapply(groups, function(z) paste(rownames(expr)[z], collapse = "|"), character(1))))
}
check_samples <- function(expr, group, old_expr, old_group, label) {
  assert(identical(colnames(expr), colnames(old_expr)), paste(label, "sample IDs/order changed"))
  assert(identical(unname(as.character(group)), unname(as.character(old_group))),
    paste(label, "outcome labels changed"))
  assert(length(group) == ncol(expr) && !anyNA(group), paste(label, "invalid outcomes"))
}
reconstruct_inputs <- function(project, h) {
  root <- file.path(project, "results_meta")
  s1 <- readRDS(file.path(root, "01_data_prep/checkpoint_s1.rds"))
  s4 <- readRDS(file.path(root, "04_GSE65682/checkpoint_s4.rds"))
  extmeta <- readRDS(file.path(root, "08_priority1_revision/04_GSE65682/checkpoint_step2_metadata.rds"))
  read_gse <- function(id) {
    g <- GEOquery::getGEO(filename = file.path(project, "data", paste0(id, "_series_matrix.txt.gz")),
      getGPL = FALSE, AnnotGPL = FALSE)
    assert(methods::is(g, "ExpressionSet"), paste(id, "did not yield one ExpressionSet"))
    assert(identical(colnames(Biobase::exprs(g)), rownames(Biobase::pData(g))), paste(id, "metadata order"))
    g
  }
  a <- read_gse("GSE272769"); b <- read_gse("GSE95233"); c <- read_gse("GSE65682")
  pa <- Biobase::pData(a); pb <- Biobase::pData(b); pc <- Biobase::pData(c)
  assert("mort30:ch1" %in% names(pa), "GSE272769 metadata schema changed")
  assert(all(c("time point:ch1", "survival:ch1") %in% names(pb)), "GSE95233 metadata schema changed")
  assert(all(c("mortality_event_28days:ch1", "endotype_class:ch1", "endotype_cohort:ch1") %in% names(pc)),
    "GSE65682 metadata schema changed")
  outcome <- function(x, ns, s) {
    x <- trimws(as.character(x))
    assert(all(x %in% c(ns, s)), "Unexpected outcome labels")
    factor(ifelse(x == ns, "NonSurvivor", "Survivor"), levels = c("Survivor", "NonSurvivor"))
  }
  ga <- outcome(pa[["mort30:ch1"]], "Yes", "No")
  kb <- which(pb[["time point:ch1"]] == "D01" &
    trimws(as.character(pb[["survival:ch1"]])) %in% c("Non Survivor", "Survivor"))
  gb <- outcome(pb[["survival:ch1"]][kb], "Non Survivor", "Survivor")
  mortality <- trimws(as.character(pc[["mortality_event_28days:ch1"]]))
  mars <- trimws(as.character(pc[["endotype_class:ch1"]]))
  cohort <- tolower(trimws(as.character(pc[["endotype_cohort:ch1"]])))
  kc <- which(mortality %in% c("0", "1") & mars %in% paste0("Mars", 1:4))
  assert(all(cohort[kc] %in% c("discovery", "validation")), "Eligible external sample lacks cohort")
  gc <- outcome(mortality[kc], "1", "0")
  batch <- factor(cohort[kc], levels = c("discovery", "validation"))
  ex <- list(GSE272769 = Biobase::exprs(a), GSE95233 = Biobase::exprs(b)[, kb, drop = FALSE],
    GSE65682 = Biobase::exprs(c)[, kc, drop = FALSE])
  gr <- list(GSE272769 = ga, GSE95233 = gb, GSE65682 = gc)
  old <- list(GSE272769 = s1$gmat_272769, GSE95233 = s1$gmat_95233, GSE65682 = s4$gmat_val)
  oldgr <- list(GSE272769 = s1$group_272769, GSE95233 = s1$group_95233, GSE65682 = s4$group_val)
  for (nm in names(ex)) {
    check_samples(ex[[nm]], gr[[nm]], old[[nm]], oldgr[[nm]], nm)
    finite <- ex[[nm]][is.finite(ex[[nm]])]
    assert(length(finite) > 0L && max(finite) < 30 && min(finite) > -2,
      paste(nm, "not expected processed log2 scale; no automatic transformation"))
    names(gr[[nm]]) <- colnames(ex[[nm]])
  }
  assert(identical(tolower(as.character(extmeta$cohort_val)), as.character(batch)), "External cohort changed")
  assert(identical(extmeta$sample_ids, colnames(ex$GSE65682)), "External metadata checkpoint order changed")
  names(batch) <- colnames(ex$GSE65682)
  gpls <- c(GSE272769 = "GPL17692", GSE95233 = "GPL570", GSE65682 = "GPL13667")
  maps <- list(); legacy <- list(); legacy_qc <- list()
  for (nm in names(ex)) {
    tab <- GEOquery::Table(GEOquery::getGEO(filename = file.path(project, "data", paste0(gpls[[nm]], ".soft.gz")),
      GSEMatrix = FALSE))
    maps[[nm]] <- platform_map(tab, gpls[[nm]], rownames(ex[[nm]]), h)
    legacy[[nm]] <- collapse_probes(ex[[nm]], maps[[nm]], "source_symbol", !invalid_symbol(maps[[nm]]$source_symbol))
  }
  old_common <- intersect(rownames(legacy$GSE272769$matrix), rownames(legacy$GSE95233$matrix))
  for (nm in names(ex)) {
    recon <- legacy[[nm]]$matrix
    if (nm != "GSE65682") recon <- recon[old_common, , drop = FALSE]
    equal <- isTRUE(all.equal(recon, old[[nm]], tolerance = 0, check.attributes = TRUE))
    legacy_qc[[nm]] <- data.frame(cohort = nm, old_rows = nrow(old[[nm]]),
      reconstructed_rows = nrow(recon), samples = ncol(recon), exact_old_matrix_reconstructed = equal)
  }
  list(expr = ex, groups = gr, batch = batch, maps = maps, legacy = legacy,
    old = old, legacy_qc = do.call(rbind, legacy_qc), raw_common = old_common)
}
run_de <- function(mat, outcome, batch = NULL) {
  assert(identical(names(outcome), colnames(mat)), "DE sample/outcome alignment")
  outcome <- factor(as.character(outcome), levels = c("Survivor", "NonSurvivor"))
  assert(all(table(outcome) >= 2L), "Insufficient outcome counts")
  if (is.null(batch)) design <- stats::model.matrix(~ 0 + outcome) else {
    assert(length(batch) == ncol(mat) && !anyNA(batch), "Invalid cohort covariate")
    assert(all(table(batch, outcome) > 0), "Empty cohort-by-outcome cell")
    design <- stats::model.matrix(~ 0 + outcome + batch)
  }
  assert(qr(design)$rank == ncol(design), "Rank-deficient DE design")
  contrast <- limma::makeContrasts(outcomeNonSurvivor - outcomeSurvivor, levels = design)
  fit <- limma::eBayes(limma::contrasts.fit(limma::lmFit(mat, design), contrast), trend = TRUE)
  res <- limma::topTable(fit, coef = 1L, number = Inf, sort.by = "none")
  assert(all(is.finite(as.matrix(res[, c("logFC", "t", "P.Value", "adj.P.Val")]))), "Non-finite DE statistics")
  res$gene_id <- rownames(res)
  list(result = res, design = design, contrast = contrast, fit = fit)
}
run_meta <- function(a, b) {
  cols <- c("gene_id", "logFC", "AveExpr", "t", "P.Value", "adj.P.Val")
  m <- merge(a[, cols], b[, cols], by = "gene_id", suffixes = c("_272769", "_95233"))
  assert(nrow(m) == nrow(a) && nrow(m) == nrow(b), "Discovery DE universes differ")
  m$se_272769 <- pmax(abs(m$logFC_272769 / m$t_272769), 1e-8)
  m$se_95233 <- pmax(abs(m$logFC_95233 / m$t_95233), 1e-8)
  m$direction <- ifelse(m$logFC_272769 > .5 & m$logFC_95233 > .5, "Up",
    ifelse(m$logFC_272769 < -.5 & m$logFC_95233 < -.5, "Down", "Other"))
  m$sign_agree <- sign(m$logFC_272769) == sign(m$logFC_95233)
  m$individual_support_272769 <- abs(m$logFC_272769) > .5 & m$P.Value_272769 < .05
  m$individual_support_95233 <- abs(m$logFC_95233) > .5 & m$P.Value_95233 < .05
  m$fisher_stat <- -2 * (log(pmax(m$P.Value_272769, .Machine$double.xmin)) +
    log(pmax(m$P.Value_95233, .Machine$double.xmin)))
  m$fisher_pval <- stats::pchisq(m$fisher_stat, df = 4, lower.tail = FALSE)
  m$fisher_fdr <- stats::p.adjust(m$fisher_pval, "BH")
  re <- lapply(seq_len(nrow(m)), function(i) {
    if (i %% 1000L == 0L) cat("REML genes:", i, "/", nrow(m), "\n")
    warnings <- character()
    r <- tryCatch(withCallingHandlers(metafor::rma(
      yi = c(m$logFC_272769[i], m$logFC_95233[i]),
      sei = c(m$se_272769[i], m$se_95233[i]), method = "REML"),
      warning = function(w) { warnings <<- c(warnings, conditionMessage(w)); invokeRestart("muffleWarning") }),
      error = function(e) e)
    if (inherits(r, "error")) return(data.frame(converged = FALSE, re_estimate = NA_real_,
      re_se = NA_real_, re_p = NA_real_, tau2 = NA_real_, I2 = NA_real_,
      re_message = conditionMessage(r)))
    data.frame(converged = TRUE, re_estimate = as.numeric(r$b), re_se = r$se,
      re_p = r$pval, tau2 = r$tau2, I2 = r$I2, re_message = paste(warnings, collapse = " | "))
  })
  m <- cbind(m, do.call(rbind, re)); m$re_fdr <- stats::p.adjust(m$re_p, "BH")
  m$selected <- m$direction %in% c("Up", "Down") & m$fisher_fdr < .05
  m$mean_abs_logFC <- (abs(m$logFC_272769) + abs(m$logFC_95233)) / 2
  s <- m[m$selected, , drop = FALSE]
  s <- s[order(s$fisher_fdr, -s$mean_abs_logFC), , drop = FALSE]
  list(all = m, selected = s)
}
pc1_variance <- function(x) {
  p <- stats::prcomp(t(x), center = TRUE, scale. = TRUE)
  # Preserve the original summary.prcomp rounding for the original statistic.
  # Also retain the unrounded value; never pretend these are the same precision.
  c(original_statistic_pct = summary(p)$importance[2L, 1L] * 100,
    unrounded_pct = p$sdev[1L]^2 / sum(p$sdev^2) * 100)
}
run_pc1 <- function(mat, common, signature, label, out, n = 10000L) {
  sig <- signature[signature %in% rownames(mat)]
  if (length(sig) < 3L) {
    write_csv(data.frame(signature = label, status = "not_estimable", evaluable = length(sig)),
      file.path(out, paste0(label, "_not_estimable.csv")))
    return(NULL)
  }
  variance <- apply(mat, 1, stats::var)
  assert(all(is.finite(variance[sig]) & variance[sig] > 0), "Invalid signature variance")
  eligible <- names(variance)[is.finite(variance) & variance > 0]
  pools <- list(common = setdiff(intersect(common, eligible), sig), full = setdiff(eligible, sig))
  observed <- pc1_variance(mat[sig, , drop = FALSE])
  ans <- list(); seeds <- c(common = 2024L, full = 2025L)
  for (nm in names(pools)) {
    # Preserve legacy pool order where identities survive; append new identities.
    # Renaming alone should not arbitrarily reorder all random draws.
    pool <- pools[[nm]]
    assert(length(pool) >= length(sig), "Random pool smaller than signature")
    set.seed(seeds[[nm]])
    values <- matrix(NA_real_, nrow = n, ncol = 2L)
    draws <- matrix(NA_integer_, nrow = n, ncol = length(sig))
    for (i in seq_len(n)) {
      ids <- sample.int(length(pool), length(sig), replace = FALSE)
      draws[i, ] <- ids
      values[i, ] <- pc1_variance(mat[pool[ids], , drop = FALSE])
      if (i %% 1000L == 0L) cat("Figure 3D:", label, nm, i, "/", n, "\n")
    }
    colnames(values) <- names(observed)
    save_new(list(pool = pool, draw_indices = draws, values = values, observed = observed,
      signature = sig, seed = seeds[[nm]], RNGkind = RNGkind()),
      file.path(out, paste0(label, "_", nm, "_draws.rds")))
    write_csv(data.frame(iteration = seq_len(n), values), file.path(out, paste0(label, "_", nm, "_distribution.csv")))
    k <- sum(values[, 1L] >= observed[1L])
    ans[[nm]] <- data.frame(signature = label, pool = nm, pool_size = length(pool),
      signature_total = length(signature), evaluable = length(sig), random_sets = n,
      observed_PC1_variance_pct = unname(observed[1L]), observed_unrounded_pct = unname(observed[2L]),
      random_mean_PC1_variance_pct = mean(values[, 1L]), random_SD_PC1_variance_pct = sd(values[, 1L]),
      random_median_PC1_variance_pct = median(values[, 1L]), exceedances = k,
      adjusted_upper_tail_proportion = (k + 1) / (n + 1))
  }
  do.call(rbind, ans)
}
run_hallmark <- function(de, pathways, seed) {
  rank <- setNames(de$t, de$gene_id)
  rank <- sort(rank, decreasing = TRUE)
  assert(!anyDuplicated(names(rank)) && all(is.finite(rank)), "Invalid GSEA ranks")
  sizes <- vapply(pathways, function(g) length(intersect(g, names(rank))), integer(1))
  assert(length(sizes) == 50L && all(sizes >= 10L & sizes <= 500L), "Not all 50 Hallmarks eligible")
  set.seed(seed)
  res <- as.data.frame(fgsea::fgseaMultilevel(pathways = pathways, stats = rank,
    minSize = 10L, maxSize = 500L, eps = 0, nPermSimple = 10000L, nproc = 1L))
  assert(nrow(res) == 50L && all(is.finite(as.matrix(res[, c("NES", "pval", "padj")]))),
    "Incomplete/non-finite Hallmark result")
  assert(all(res$size == sizes[res$pathway]), "GSEA effective gene-set sizes differ")
  res$leadingEdge <- vapply(res$leadingEdge, paste, character(1), collapse = ";")
  list(result = res, ranks = rank, effective_sizes = sizes)
}
run_xcell <- function(prepared, group, reference) {
  expr <- prepared$input_linear
  assert(identical(colnames(expr), names(group)), "xCell input sample order differs")
  assert(nrow(expr) >= 5000L && all(is.finite(expr)) && !anyDuplicated(rownames(expr)), "Invalid prepared xCell input")
  scores <- xCell::xCellAnalysis(expr = expr, signatures = reference$signatures,
    genes = reference$genes, spill = reference$spill.array, rnaseq = FALSE,
    parallel.sz = 1L, parallel.type = "SOCK", file.name = NULL, save.raw = FALSE,
    alpha = .5, scale = TRUE, cell.types.use = NULL)
  scores <- as.matrix(scores)
  assert(identical(colnames(scores), names(group)), "xCell output sample order differs")
  assert(nrow(scores) == 67L && all(is.finite(scores)), "Expected 67 finite xCell outputs")
  stats <- do.call(rbind, lapply(rownames(scores), function(ct) {
    ns <- scores[ct, group == "NonSurvivor"]; ss <- scores[ct, group == "Survivor"]
    # All-zero/equal outputs can give NaN from wilcox.test. Report, do not set P=1.
    p <- suppressWarnings(stats::wilcox.test(ns, ss, exact = FALSE)$p.value)
    data.frame(cell_type = ct, mean_NS = mean(ns), mean_S = mean(ss),
      delta = mean(ns) - mean(ss), pval = p,
      status = if (is.finite(p)) "estimated" else "non_estimable_constant_or_tied")
  }))
  # Same p.adjust call as the original; retain and report any non-estimable P.
  stats$fdr <- stats::p.adjust(stats$pval, method = "BH")
  list(scores = scores, statistics = stats,
    input_map = prepared$input_map, input_linear = expr, coverage = prepared$coverage)
}
compare_numeric <- function(old, new, key, metrics) {
  assert(!anyDuplicated(old[[key]]) && !anyDuplicated(new[[key]]), "Comparison keys not unique")
  metrics <- intersect(metrics, intersect(names(old), names(new)))
  o <- old[, c(key, metrics), drop = FALSE]; n <- new[, c(key, metrics), drop = FALSE]
  o$present_old <- TRUE; n$present_new <- TRUE
  d <- merge(o, n, by = key, all = TRUE, suffixes = c("_old", "_new"))
  for (m in metrics) d[[paste0(m, "_change")]] <- as.numeric(d[[paste0(m, "_new")]]) - as.numeric(d[[paste0(m, "_old")]])
  d
}

# Incorporated into core.R by the local build; not a server entry point.
build_xcell_input <- function(mat, raw, map, selection, dictionary, feature_review,
                             cohort, reference_genes, min_genes = 5000L) {
  assert(identical(colnames(mat), colnames(raw)), "xCell raw/canonical sample order differs")
  assert(!anyDuplicated(rownames(mat)) && !anyDuplicated(rownames(raw)) &&
    !anyDuplicated(map$probe) && !anyDuplicated(selection$gene_id), "Duplicated xCell source keys")
  assert(!anyDuplicated(dictionary$source_symbol) && setequal(dictionary$source_symbol, reference_genes),
    "xCell frozen feature inventory differs")
  f <- feature_review[feature_review$cohort == cohort, , drop = FALSE]
  assert(!anyDuplicated(f$source_symbol) && all(f$source_symbol %in% reference_genes), "Invalid historical feature rows")
  assert(all(f$action %in% c("keep", "exclude")) &&
    all(f$review_status %in% c("reviewed_resolved", "reviewed_unresolved", "reviewed_excluded")) &&
    all(nzchar(f$evidence)) && all(nzchar(f$reason)), "Historical feature review incomplete")
  d <- dictionary[dictionary$action == "keep", , drop = FALSE]
  duplicated_ids <- duplicated(d$resolved_gene_id) | duplicated(d$resolved_gene_id, fromLast = TRUE)
  assert(all(d$source_symbol[duplicated_ids] %in% f$source_symbol),
    "Historical identity collisions require explicit feature/probe provenance")
  coverage <- data.frame(source_symbol = dictionary$source_symbol, status = "resource_excluded",
    gene_id = dictionary$resolved_gene_id, selected_probe = "", stringsAsFactors = FALSE)
  chosen <- character(); labels <- character(); keys <- character(); modes <- character()
  for (i in seq_len(nrow(d))) {
    label <- d$source_symbol[i]; key <- d$resolved_gene_id[i]
    ci <- match(label, coverage$source_symbol); fi <- match(label, f$source_symbol)
    coverage$status[ci] <- "outside_canonical_analysis_scope"
    if (!key %in% rownames(mat)) next
    if (!is.na(fi)) {
      if (f$action[fi] == "exclude") { coverage$status[ci] <- f$review_status[fi]; next }
      assert(f$review_status[fi] == "reviewed_resolved", "Unresolved historical feature cannot be kept")
      p <- split_nonempty(f$approved_probes[fi])
      assert(length(p) > 0L && all(p %in% split_nonempty(f$candidate_probes[fi])) &&
        all(p %in% rownames(raw)), "Historical feature probe missing or outside reviewed candidates")
      mi <- match(p, map$probe)
      assert(!anyNA(mi) && all(map$action[mi] == "keep") && all(map$original_eligible[mi] == "TRUE") &&
        all(map$resolved_gene_id[mi] == key), "Historical probe disagrees with approved canonical identity/eligibility")
      ix <- which(rownames(raw) %in% p)
      v <- apply(raw[ix, , drop = FALSE], 1L, stats::var, na.rm = TRUE)
      assert(any(is.finite(v)), "No finite historical candidate variance")
      probe <- rownames(raw)[ix[which.max(v)]]; mode <- "reviewed_historical_feature"
    } else {
      si <- match(key, selection$gene_id)
      assert(!is.na(si), "Missing canonical probe provenance")
      probe <- selection$selected_probe[si]; mode <- "canonical_gene_bridge"
      mi <- match(probe, map$probe)
      assert(!is.na(mi) && map$action[mi] == "keep" && map$original_eligible[mi] == "TRUE" &&
        map$resolved_gene_id[mi] == key && probe %in% rownames(raw), "Invalid canonical xCell probe provenance")
      assert(identical(unname(raw[probe, ]), unname(mat[key, ])), "Canonical xCell expression/probe mismatch")
    }
    chosen <- c(chosen, probe); labels <- c(labels, label); keys <- c(keys, key); modes <- c(modes, mode)
    coverage$status[ci] <- "included"; coverage$selected_probe[ci] <- probe
  }
  assert(!anyDuplicated(chosen), "One source probe cannot be cloned into multiple xCell features")
  expr <- raw[chosen, , drop = FALSE]; rownames(expr) <- labels
  linear <- pmax(2^expr - 1, 0)
  assert(nrow(expr) >= min_genes && all(is.finite(expr)) && all(is.finite(linear)), "Insufficient/invalid xCell input")
  list(input_log2 = expr, input_linear = linear,
    input_map = data.frame(source_symbol = labels, resolved_gene_id = keys,
      selected_probe = chosen, mapping_mode = modes), coverage = coverage)
}


