      xc <- list(); xc_comparisons <- list()
      for (nm in names(mats)) {
        set.seed(c(GSE272769 = 5201L, GSE95233 = 5202L, GSE65682 = 5203L)[[nm]])
        xc[[nm]] <- run_xcell(xc_inputs[[nm]], input$groups[[nm]], reference)
        write_csv(xc[[nm]]$statistics, file.path(dirs[["xcell"]], paste0(nm, "_statistics.csv")))
        write_csv(xc[[nm]]$input_map, file.path(dirs[["xcell"]], paste0(nm, "_model_dictionary_bridge.csv")))
        save_new(xc[[nm]], file.path(dirs[["xcell"]], paste0(nm, "_full_result.rds")))
        oldxc <- utils::read.csv(file.path(oldroot, "05_triple_cohort", paste0("xCell_", nm, ".csv")))
        comp <- compare_numeric(oldxc, xc[[nm]]$statistics, "cell_type", c("mean_NS", "mean_S", "delta", "pval", "fdr"))
        comp$cohort <- nm; comp$direction_changed <- sign(comp$delta_old) != sign(comp$delta_new)
        comp$FDR_005_changed <- (comp$fdr_old < .05) != (comp$fdr_new < .05)
        xc_comparisons[[nm]] <- comp
      }
      write_csv(do.call(rbind, xc_comparisons), file.path(dirs[["compare"]], "xCell_all201_old_vs_new.csv"))
      save_new(xc, file.path(out, "checkpoint_05_xCell.rds"))
      signature_changed <- !setequal(oldsig, newsig)
      # Observed differences determine later work; these are NOT automatic reruns.
      impact <- data.frame(component = c("Discovery DE / Meta / signature", "Figure 3D", "Hallmark / S5 / S10",
        "xCell / S5 / S11", "GO/KEGG and TF", "External signature/effect/PC1 outcomes", "E3 and MARS", "Single-cell"),
        action = c("New results and old-new tables generated", "Corrected pools; fixed/new signature distinguished",
          "All 150 pathway comparisons generated", "Array parameters; all 201 output comparisons generated",
          "Frozen; review changed signature AND background before deciding reruns",
          "Not rerun here beyond DE prerequisite and Figure 3D; inspect gene/probe changes",
          "Frozen; inspect changed identities/signature/external DE before deciding reruns",
          "Untouched; assess only if bulk-derived gene sets used there change"),
        new_signature_differs = signature_changed)
      write_csv(impact, file.path(dirs[["compare"]], "downstream_impact_checklist.csv"))
      writeLines(c("ANALYSIS_COMPLETED_PENDING_SCIENTIFIC_REVIEW",
        paste("Old signature size:", length(oldsig)), paste("New signature size:", length(newsig)),
        paste("Signature changed:", signature_changed),
        "Results are not evidence of unchanged conclusions until the comparison tables are reviewed.",
        "No manuscript, published figures, old scripts, old RData or single-cell files were edited."), file.path(out, "STATUS.txt"))
      cat("\nAnalysis completed; comparison review required.\n", out, "\n")
# END_VERBATIM_STATISTICS
    writeLines(capture.output(sessionInfo()), file.path(out, "sessionInfo_end.txt"))
    files <- list.files(out, recursive = TRUE, full.names = TRUE)
    files <- files[!dir.exists(files) & basename(files) != "run.log"]
    write_csv(data.frame(path = substring(files, nchar(out) + 2L), bytes = file.info(files)$size,
      md5 = vapply(files, md5, character(1))), file.path(out, "output_manifest.csv"))
  return(normalizePath(out, mustWork = TRUE))
}


