bulk_np_status <- function(completed, matched) {
  if(!isTRUE(completed)) "STOPPED_NOT_VALIDATED" else if(isTRUE(matched))
    "MATCHES_SCIENTIFIC_FINGERPRINTS" else "COMPLETED_BUT_DIFFERS_FROM_AUDITED"
}
bulk_np_manifest <- function(m,ctx) {
  stopifnot(nrow(m)>0L,all(c("scope","path","bytes","md5")%in%names(m)),!anyNA(m),
    !anyDuplicated(paste(m$scope,m$path)),all(m$scope%in%c("project","bundle")))
  roots<-c(project=ctx$project,bundle=ctx$bundle_dir);paths<-character(nrow(m))
  for(i in seq_len(nrow(m))) {
    rel<-m$path[i]
    if(!nzchar(rel)||grepl("^[\\\\/]|^[A-Za-z]:|\\\\",rel)||any(strsplit(rel,"/",fixed=TRUE)[[1L]]%in%c("",".","..")))stop("Unsafe input path")
    root<-normalizePath(roots[[m$scope[i]]],winslash="/",mustWork=TRUE)
    p<-normalizePath(file.path(root,rel),winslash="/",mustWork=TRUE)
    if(!startsWith(p,paste0(root,"/"))||dir.exists(p))stop("Input outside approved root")
    if(file.info(p)$size!=as.numeric(m$bytes[i])||unname(tools::md5sum(p))!=m$md5[i])stop("INPUT_FINGERPRINT_MISMATCH: ",rel)
    paths[i]<-p
  }
  data.frame(m,resolved_path=paths,stringsAsFactors=FALSE)
}
bulk_np_guards <- function(loaded=FALSE) {
  targets<-if(!loaded)list(base=c("url","socketConnection"),utils=c("download.file","download.packages","install.packages")) else list(
    KEGGREST=c("keggGet","keggLink","keggList","keggConv","keggInfo","keggFind"),
    httr=c("GET","POST","PUT","DELETE","PATCH","HEAD"),httr2="req_perform",
    curl=c("curl","curl_download","curl_fetch_memory","curl_fetch_disk","curl_fetch_stream"),
    grDevices=c("pdf","png","jpeg","tiff","bmp","svg","postscript","cairo_pdf","cairo_ps","dev.new","x11","quartz","windows","win.metafile"),
    graphics="plot.new",grid="grid.newpage")
  ans<-character()
  for(pkg in names(targets))if(pkg%in%loadedNamespaces())for(fn in targets[[pkg]])if(exists(fn,asNamespace(pkg),inherits=FALSE)) {
    trace(fn,tracer=quote(stop("BULK_OFFLINE_NOPLOT: network, installation or graphic output blocked",call.=FALSE)),print=FALSE,where=asNamespace(pkg))
    ans<-c(ans,paste(pkg,fn,sep="::"))
  }
  ans
}
