  runtime<-file.path(ctx$out_dir,"control","downstream_runtime")
  stopifnot(!file.exists(runtime),dir.create(runtime,recursive=TRUE))
  source_bundle<-file.path(ctx$bundle_dir,"downstream")
  stopifnot(file.copy(file.path(source_bundle,"frozen"),runtime,recursive=TRUE))
  manifest<-read.csv(file.path(source_bundle,"frozen/ora_input_manifest.csv"),stringsAsFactors=FALSE,colClasses=c(md5="character"))
  dynamic<-manifest$scope=="analysis"
  allow<-c("01_identity/discovery_common_universe.csv","02_DE_Meta/new_selected_signature.csv",
           "02_DE_Meta/GSE65682_DE.csv","approved_decisions/old_signature_decisions.csv")
  stopifnot(sum(dynamic)==4L,setequal(manifest$path[dynamic],allow))
  p<-file.path(main,manifest$path[dynamic]);stopifnot(all(file.exists(p)))
  # These are FRESH calculation outputs, not expected results. Only these four
  # runtime input pins change; every frozen source remains bundle-pinned.
  manifest$md5[dynamic]<-unname(tools::md5sum(p));manifest$bytes[dynamic]<-file.info(p)$size
  write.csv(manifest,file.path(runtime,"frozen/ora_input_manifest.csv"),row.names=FALSE)
  dc<-list(project=ctx$project,analysis_dir=main,probe_dir=file.path(ctx$bundle_dir,"frozen_ora"),
           bundle_dir=runtime,out_dir=out)
  dc
}
