# Frozen seven-model refresh. Source defines functions only; execution is worker-controlled.
bulk_models_check <- function(ok, message) {
  if (!isTRUE(ok)) stop(message, call. = FALSE)
}
bulk_models_read_csv <- function(path) {
  bulk_models_check(file.exists(path), paste('Missing model input:', path))
  utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
}
bulk_models_write_csv <- function(x, path) {
  bulk_models_check(!file.exists(path), paste('Refusing overwrite:', path))
  utils::write.csv(x, path, row.names = FALSE, na = '')
}
bulk_models_align <- function(mat, meta, groups, batch) {
  bulk_models_check(is.matrix(mat) && is.numeric(mat) && all(is.finite(mat)), 'Expression must be finite numeric matrix')
  ids <- colnames(mat)
  bulk_models_check(length(ids) == ncol(mat) && !anyNA(ids) && !anyDuplicated(ids) && all(nzchar(ids)), 'Invalid matrix sample IDs')
  bulk_models_check(length(rownames(mat)) == nrow(mat) && !anyDuplicated(rownames(mat)) && all(grepl('^ENTREZ:[0-9]+$', rownames(mat))), 'Invalid canonical matrix gene IDs')
  bulk_models_check(all(c('sample','outcome','cohort','mars') %in% names(meta)), 'Missing metadata fields')
  bulk_models_check(!anyNA(meta$sample) && !anyDuplicated(meta$sample) && setequal(ids,meta$sample), 'Metadata sample identity mismatch')
  meta <- meta[match(ids,meta$sample), , drop=FALSE]
  bulk_models_check(identical(names(groups),ids), 'Outcome vector names/order mismatch')
  bulk_models_check(identical(as.character(groups),as.character(meta$outcome)), 'Outcome value mismatch')
  bulk_models_check(length(batch)==length(ids) && identical(tolower(as.character(meta$cohort)),as.character(batch)), 'Cohort value/order mismatch')
  if (!is.null(names(batch))) bulk_models_check(identical(names(batch),ids), 'Batch names/order mismatch')
  bulk_models_check(all(meta$outcome %in% c('Survivor','NonSurvivor')) && all(meta$cohort %in% c('Discovery','Validation')) && all(meta$mars %in% paste0('Mars',1:4)), 'Unexpected clinical labels')
  rownames(meta) <- ids
  meta
}
bulk_models_plan <- function(meta) {
  files <- c('GSE65682_DE_combined_unadjusted.csv','GSE65682_DE_discovery_cohort.csv','GSE65682_DE_validation_cohort.csv',paste0('GSE65682_Mars',1:4,'_cohort_adjusted_DE_all_genes.csv'))
  ix <- c(list(seq_len(nrow(meta)),which(meta$cohort=='Discovery'),which(meta$cohort=='Validation')),lapply(paste0('Mars',1:4),function(m)which(meta$mars==m)))
  setNames(lapply(seq_along(ix),function(i)list(index=ix[[i]],adjusted=i>3L,oldfile=files[i])),c('combined_unadjusted','discovery_only','validation_only',paste0('Mars',1:4)))
}
bulk_models_design <- function(meta, adjusted) {
  outcome <- factor(meta$outcome,levels=c('Survivor','NonSurvivor'))
  bulk_models_check(!anyNA(outcome) && all(table(outcome)>=2L),'Insufficient outcome groups')
  if (adjusted) {
    ge <- outcome; ce <- factor(meta$cohort,levels=c('Discovery','Validation'))
    bulk_models_check(!anyNA(ce) && all(table(ce,ge)>0L),'Empty cohort-outcome cell; singleton cells are permitted')
    design <- stats::model.matrix(~0+ge+ce)
  } else design <- stats::model.matrix(~0+outcome)
  rownames(design) <- meta$sample
  bulk_models_check(qr(design)$rank==ncol(design) && nrow(design)>ncol(design),'Rank-deficient model')
  design
}
bulk_models_compare <- function(old, new, links, selected_probes=NULL) {
  bulk_models_check(!anyDuplicated(old$gene) && !anyDuplicated(links$old_symbol) && !anyDuplicated(new$gene_id),'Nonunique identity keys')
  gid <- as.character(links$gene_id[match(old$gene,links$old_symbol)])
  valid <- !is.na(gid) & nzchar(gid)
  ni <- match(gid,new$gene_id)
  out <- data.frame(old_symbol=old$gene,old_probe=links$old_probe[match(old$gene,links$old_symbol)],gene_id=gid,comparison_status=ifelse(!valid,'unresolved_old_identity',ifelse(is.na(ni),'absent_corrected_identity','compared_identity')),stringsAsFactors=FALSE)
  multiplicity <- table(gid[valid])
  out$old_identity_multiplicity <- as.integer(multiplicity[match(gid,names(multiplicity))])
  out$new_selected_probe <- NA_character_
  out$representative_changed <- NA
  if (!is.null(selected_probes)) {
    bulk_models_check(!anyDuplicated(selected_probes$gene_id),'Nonunique new probe identity')
    out$new_selected_probe <- selected_probes$selected_probe[match(gid,selected_probes$gene_id)]
    comparable <- valid & !is.na(out$new_selected_probe) & !is.na(out$old_probe)
    out$representative_changed[comparable] <- out$old_probe[comparable]!=out$new_selected_probe[comparable]
  }
  for (field in intersect(c('logFC','AveExpr','t','P.Value','adj.P.Val','B'),intersect(names(old),names(new)))) {
    out[[paste0(field,'_old')]] <- old[[field]]
    out[[paste0(field,'_new')]] <- new[[field]][ni]
    out[[paste0(field,'_delta')]] <- out[[paste0(field,'_new')]]-old[[field]]
  }
  out
}
bulk_models_invariants <- function(old, new, old_symbols, gene_ids, tol=1e-10) {
  bulk_models_check(length(old_symbols)==length(gene_ids) && !anyDuplicated(old_symbols) && !anyDuplicated(gene_ids),'Invalid fixed signature map')
  oi <- match(old_symbols,old$gene);ni <- match(gene_ids,new$gene_id)
  bulk_models_check(!anyNA(oi) && !anyNA(ni),'Fixed signature row missing')
  delta <- new$logFC[ni]-old$logFC[oi]
  qc <- data.frame(old_symbol=old_symbols,gene_id=gene_ids,logFC_old=old$logFC[oi],logFC_new=new$logFC[ni],delta=delta,passed=is.finite(delta)&abs(delta)<=tol)
  bulk_models_check(all(qc$passed),'Fixed signature logFC invariant failed')
  list(passed=TRUE,rows=qc,max_absolute_delta=max(abs(delta)))
}
bulk_models_load <- function(ctx) {
  olddir <- file.path(ctx$project,'results_meta','08_priority1_revision','04_GSE65682')
  id <- readRDS(file.path(ctx$analysis_dir,'checkpoint_01_identity.rds'))
  om <- readRDS(file.path(olddir,'checkpoint_step2_metadata.rds'))
  oe <- readRDS(file.path(olddir,'checkpoint_step3_expression.rds'))
  mat <- id$matrices$GSE65682
  bulk_models_check(identical(dim(mat),c(11353L,479L)), 'Expected audited 11353 x 479 matrix')
  meta <- data.frame(sample=as.character(om$sample_ids),outcome=as.character(om$group_val),cohort=as.character(om$cohort_val),mars=as.character(om$endo_val),stringsAsFactors=FALSE)
  meta <- bulk_models_align(mat,meta,id$groups$GSE65682,id$batch)
  bulk_models_check(identical(meta$sample,as.character(om$sample_ids)),'Original sample order changed')
  map <- bulk_models_read_csv(file.path(ctx$analysis_dir,'approved_decisions','old_signature_decisions.csv'))
  selected <- bulk_models_read_csv(file.path(ctx$analysis_dir,'02_DE_Meta','new_selected_signature.csv'))
  links <- bulk_models_read_csv(file.path(ctx$analysis_dir,'01_identity','GSE65682_old_row_identity.csv'))
  probes <- bulk_models_read_csv(file.path(ctx$analysis_dir,'01_identity','GSE65682_selected_probes.csv'))
  bulk_models_check(nrow(map)==32L && all(map$action=='keep') && !anyDuplicated(map$source_symbol) && !anyDuplicated(map$resolved_gene_id) && all(grepl('^ENTREZ:[0-9]+$',map$resolved_gene_id)), 'Invalid frozen32 identity map')
  bulk_models_check(nrow(selected)==32L && !anyDuplicated(selected$gene_id) && setequal(selected$gene_id,map$resolved_gene_id),'New selected signature differs from frozen32')
  bulk_models_check(nrow(probes)==nrow(mat) && !anyDuplicated(probes$gene_id) && !anyDuplicated(probes$selected_probe) && setequal(probes$gene_id,rownames(mat)), 'Global representative probe identity mismatch')
  bulk_models_check(!anyDuplicated(links$old_symbol) && nrow(links)==11518L && setequal(links$old_symbol,rownames(oe$gmat_val)), 'Old row identity ledger mismatch')
  old_symbols <- as.character(oe$signature_adjusted)
  gene_ids <- map$resolved_gene_id[match(old_symbols,map$source_symbol)]
  bulk_models_check(length(old_symbols)==30L && !anyNA(gene_ids) && !anyDuplicated(gene_ids) && setequal(intersect(map$resolved_gene_id,rownames(mat)),gene_ids),'Fixed30 external coverage changed')
  bulk_models_check(identical(unname(as.character(links$gene_id[match(old_symbols,links$old_symbol)])),unname(as.character(gene_ids))), 'Fixed30 conflicts with approved old row ledger')
  bulk_models_check(identical(colnames(oe$gmat_val),colnames(mat)),'Old expression sample order mismatch')
  old30 <- oe$gmat_val[old_symbols,,drop=FALSE]; new30 <- mat[gene_ids,,drop=FALSE]
  bulk_models_check(all(is.finite(old30)) && identical(unname(old30),unname(new30)),'Fixed30 expression differs from original; stop before fits')
  plan <- bulk_models_plan(meta)
  expected <- cbind(n=c(479,263,216,132,176,118,53),S=c(365,194,171,87,138,97,43),NS=c(114,69,45,45,38,21,10),rank=c(2,2,2,3,3,3,3))
  oldtables <- list(); qcs <- list()
  for(i in seq_along(plan)) {
    p <- plan[[i]]; m <- meta[p$index,,drop=FALSE]; d <- bulk_models_design(m,p$adjusted)
    observed <- c(nrow(m),sum(m$outcome=='Survivor'),sum(m$outcome=='NonSurvivor'),qr(d)$rank)
    bulk_models_check(identical(as.numeric(observed),as.numeric(expected[i,])),paste('Original model population mismatch:',names(plan)[i]))
    tab <- bulk_models_read_csv(file.path(olddir,p$oldfile))
    fields <- c('logFC','AveExpr','t','P.Value','adj.P.Val','B')
    bulk_models_check(all(c('gene',fields)%in%names(tab)) && nrow(tab)==11518L && !anyDuplicated(tab$gene) && setequal(tab$gene,links$old_symbol),'Old full DE table identity mismatch')
    bulk_models_check(all(vapply(tab[fields],function(x)is.numeric(x)&&all(is.finite(x)),logical(1))),'Old DE statistics invalid')
    bulk_models_check(max(abs(stats::p.adjust(tab$P.Value,'BH')-tab$adj.P.Val))<1e-12,'Old full-background BH mismatch')
    bulk_models_check(all(old_symbols %in% tab$gene),'Old signature missing from DE table')
    oldtables[[names(plan)[i]]] <- tab
    qcs[[i]] <- data.frame(model=names(plan)[i],samples=observed[1],survivors=observed[2],non_survivors=observed[3],design_rank=observed[4],residual_df=observed[1]-observed[4],background_genes=nrow(mat),fixed_signature_genes=30L,expression_identical=TRUE)
  }
  long <- bulk_models_read_csv(file.path(olddir,'GSE65682_per_MARS_signature_statistics.csv'))
  bulk_models_check(nrow(long)==120L && !anyDuplicated(paste(long$MARS,long$gene)), 'Invalid old MARS120 table')
  for(m in paste0('Mars',1:4)) bulk_models_check(setequal(long$gene[long$MARS==m],old_symbols),'Old MARS fixed signature mismatch')
  main <- bulk_models_read_csv(file.path(ctx$analysis_dir,'02_DE_Meta','GSE65682_DE.csv'))
  bulk_models_check(!anyDuplicated(main$gene_id) && setequal(main$gene_id,rownames(mat)),'Completed main adjusted DE identity mismatch')
  list(mat=mat,meta=meta,plan=plan,oldtables=oldtables,old_symbols=old_symbols,gene_ids=gene_ids,map=map,selected=selected,links=links,probes=probes,long=long,main=main,qc=do.call(rbind,qcs))
}
bulk_validate_models_inputs <- function(ctx) {
  x <- bulk_models_load(ctx)
  list(status='PASS_INPUTS_NO_FITTING',summary=x$qc,fixed30_mapping=data.frame(old_symbol=x$old_symbols,gene_id=x$gene_ids),fixed30_expression_identical=TRUE,new_fits_executed=0L)
}
bulk_run_models <- function(ctx) {
  bulk_models_check(requireNamespace('limma',quietly=TRUE) && as.character(utils::packageVersion('limma'))=='3.64.3','Frozen limma 3.64.3 required; do not install or upgrade')
  x <- bulk_models_load(ctx)
  out <- file.path(ctx$out_dir,'models')
  bulk_models_check(!file.exists(out),'Models output directory already exists')
  bulk_models_check(dir.create(out,recursive=FALSE),'Cannot create models output directory')
  bulk_models_write_csv(x$qc,file.path(out,'input_model_QC.csv'))
  bulk_models_write_csv(data.frame(old_symbol=x$old_symbols,gene_id=x$gene_ids),file.path(out,'fixed30_identity_map.csv'))
  signatures <- list(); invariants <- list(); summaries <- list(); results <- list()
  for (name in names(x$plan)) {
    p <- x$plan[[name]]; md <- x$meta[p$index,,drop=FALSE]
    y <- x$mat[,p$index,drop=FALSE]; design <- bulk_models_design(md,p$adjusted)
    bulk_models_check(identical(colnames(y),rownames(design)),'Fit sample alignment failed')
    contrast <- matrix(c(-1,1,if(p$adjusted)0),ncol=1L,dimnames=list(colnames(design),'NonSurvivor_minus_Survivor'))
    fit0 <- limma::lmFit(y,design)
    fitc <- limma::contrasts.fit(fit0,contrast)
    # Preserve original trend=TRUE and default robust=FALSE; no subgroup probe selection.
    fit <- limma::eBayes(fitc,trend=TRUE)
    de <- limma::topTable(fit,coef=1L,number=Inf,sort.by='none',adjust.method='BH')
    de$gene_id <- rownames(de); rownames(de) <- NULL
    bulk_models_check(identical(de$gene_id,rownames(y)) && nrow(de)==11353L,'DE row order/background changed')
    bulk_models_check(all(vapply(de[c('logFC','AveExpr','t','P.Value','adj.P.Val','B')],function(v)all(is.finite(v)),logical(1))),'Nonfinite new DE result')
    bulk_models_check(max(abs(stats::p.adjust(de$P.Value,'BH')-de$adj.P.Val))<1e-12,'New BH scope mismatch')
    d <- file.path(out,name); bulk_models_check(dir.create(d),'Cannot create model result directory')
    bulk_models_write_csv(de,file.path(d,'DE_all_genes.csv'))
    bulk_models_write_csv(md,file.path(d,'samples_metadata.csv'))
    bulk_models_write_csv(data.frame(sample=rownames(design),design,check.names=FALSE),file.path(d,'design.csv'))
    bulk_models_write_csv(data.frame(coefficient=rownames(contrast),contrast,check.names=FALSE),file.path(d,'contrast.csv'))
    saveRDS(list(fit_lm=fit0,fit_contrast=fitc,fit_ebayes=fit,design=design,contrast=contrast,samples=md,gene_ids=rownames(y),trend=TRUE,robust=FALSE,limma_version='3.64.3'),file.path(d,'limma_complete_fit.rds'),version=3)
    cmp <- bulk_models_compare(x$oldtables[[name]],de,x$links,x$probes)
    bulk_models_write_csv(cmp,file.path(d,'old_new_all_old_rows_comparison.csv'))
    bulk_models_write_csv(de[!de$gene_id %in% cmp$gene_id[cmp$comparison_status=='compared_identity'],,drop=FALSE],file.path(d,'new_rows_without_comparable_old_identity.csv'))
    inv <- tryCatch(bulk_models_invariants(x$oldtables[[name]],de,x$old_symbols,x$gene_ids),error=function(e) {
      bulk_models_write_csv(cmp[cmp$old_symbol %in% x$old_symbols,,drop=FALSE],file.path(d,'FAILED_fixed30_invariant.csv'))
      stop(conditionMessage(e),call.=FALSE)
    })
    inv$rows$model <- name; invariants[[name]] <- inv$rows
    sig <- de[match(x$gene_ids,de$gene_id),,drop=FALSE]
    sig$old_symbol <- x$old_symbols
    sig$symbol <- x$selected$symbol[match(sig$gene_id,x$selected$gene_id)]
    sig$discovery_direction <- x$selected$direction[match(sig$gene_id,x$selected$gene_id)]
    sig$model <- name
    bulk_models_write_csv(sig,file.path(d,'fixed30_DE.csv'))
    signatures[[name]] <- sig; results[[name]] <- de
    summaries[[name]] <- data.frame(model=name,genes=nrow(de),samples=ncol(y),survivors=sum(md$outcome=='Survivor'),non_survivors=sum(md$outcome=='NonSurvivor'),rank=qr(design)$rank,residual_df=nrow(design)-qr(design)$rank,fixed30_logFC_max_abs_delta=inv$max_absolute_delta,compared_old_rows=sum(cmp$comparison_status=='compared_identity'),unresolved_old_rows=sum(cmp$comparison_status=='unresolved_old_identity'),absent_old_identities=sum(cmp$comparison_status=='absent_corrected_identity'),FDR_lt_005=sum(de$adj.P.Val<.05))
  }
  long <- x$long
  long$gene_id <- x$map$resolved_gene_id[match(long$gene,x$map$source_symbol)]
  for (m in paste0('Mars',1:4)) {
    ii <- which(long$MARS==m); tt <- results[[m]]; jj <- match(long$gene_id[ii],tt$gene_id)
    for (field in c('logFC','AveExpr','t','B')) long[[field]][ii] <- tt[[field]][jj]
    long$P[ii] <- tt$P.Value[jj]; long$FDR[ii] <- tt$adj.P.Val[jj]
  }
  long$MARS_direction <- ifelse(long$logFC>0,'Up',ifelse(long$logFC<0,'Down','Zero'))
  long$directionally_concordant <- long$MARS_direction==long$discovery_direction
  bulk_models_write_csv(long,file.path(out,'GSE65682_per_MARS_signature_statistics_refreshed.csv'))
  main <- x$main[match(x$gene_ids,x$main$gene_id),,drop=FALSE]
  main$old_symbol <- x$old_symbols;main$model <- 'combined_cohort_adjusted_REUSED'
  bulk_models_write_csv(main,file.path(out,'existing_main_adjusted_fixed30_reused.csv'))
  bulk_models_write_csv(do.call(rbind,signatures),file.path(out,'seven_models_fixed30.csv'))
  invariant_qc <- do.call(rbind,invariants); summary <- do.call(rbind,summaries)
  bulk_models_write_csv(invariant_qc,file.path(out,'fixed30_logFC_invariant_QC.csv'))
  bulk_models_write_csv(summary,file.path(out,'seven_models_summary.csv'))
  list(status='SEVEN_MODELS_COMPLETED_PENDING_REVIEW',summary=summary,invariant_qc=invariant_qc,output_dir=out,models_executed=7L,background_genes=11353L,main_adjusted_reused=TRUE)
}



