bulk_ora_assert <- function(ok, message) {
  if (!isTRUE(ok)) stop(message, call. = FALSE)
}
bulk_ora_normalize_ids <- function(x, label = "gene IDs") {
  x <- as.character(x)
  bulk_ora_assert(!anyNA(x) && all(grepl("^(ENTREZ:)?[1-9][0-9]*$", x)), paste(label, "malformed IDs"))
  x <- sub("^ENTREZ:", "", x)
  bulk_ora_assert(!anyDuplicated(x), paste(label, "duplicate IDs"))
  x
}
bulk_ora_maps <- function(t2g, t2n, label) {
  bulk_ora_assert(is.data.frame(t2g) && all(c("term","gene") %in% names(t2g)), paste(label,"invalid TERM2GENE"))
  bulk_ora_assert(is.data.frame(t2n) && all(c("term","name") %in% names(t2n)), paste(label,"invalid TERM2NAME"))
  t2g <- data.frame(term=as.character(t2g$term),gene=as.character(t2g$gene),stringsAsFactors=FALSE)
  t2n <- data.frame(term=as.character(t2n$term),name=as.character(t2n$name),stringsAsFactors=FALSE)
  bulk_ora_assert(nrow(t2g)>0L && !anyNA(t2g) && all(nzchar(t2g$term)) && all(grepl("^[1-9][0-9]*$",t2g$gene)),paste(label,"malformed resource"))
  bulk_ora_assert(!anyDuplicated(t2g),paste(label,"duplicate resource edges"))
  bulk_ora_assert(!anyNA(t2n) && all(nzchar(t2n$name)) && !anyDuplicated(t2n$term),paste(label,"duplicate or missing resource names"))
  bulk_ora_assert(all(t2g$term %in% t2n$term),paste(label,"resource term missing name"))
  list(label=label,TERM2GENE=t2g,TERM2NAME=t2n,sets=split(t2g$gene,t2g$term),genes=unique(t2g$gene),names=setNames(t2n$name,t2n$term))
}
bulk_ora_empty <- function() {
  data.frame(ID=character(),Description=character(),GeneRatio=character(),BgRatio=character(),RichFactor=numeric(),FoldEnrichment=numeric(),zScore=numeric(),pvalue=numeric(),p.adjust=numeric(),qvalue=numeric(),geneID=character(),Count=integer(),stringsAsFactors=FALSE)
}
bulk_ora_math <- function(query, universe, maps, min_size=10L, max_size=500L) {
  query <- bulk_ora_normalize_ids(query,"query"); universe <- bulk_ora_normalize_ids(universe,"universe")
  bulk_ora_assert(all(query %in% universe),"query IDs outside submitted universe")
  effective <- intersect(maps$genes,universe); mapped <- intersect(query,maps$genes)
  status <- if(!length(query)) "EMPTY_QUERY" else if(!length(mapped)) "NO_ANNOTATED_QUERY" else "OK"
  terms <- unique(maps$TERM2GENE$term[maps$TERM2GENE$gene %in% query])
  gs <- lapply(maps$sets[terms],intersect,effective)
  eligible <- lengths(gs)>=min_size & lengths(gs)<=max_size
  selected <- gs[eligible]; result <- bulk_ora_empty()
  if(length(selected) && length(mapped)) {
    hits <- lapply(selected,intersect,query); k <- lengths(hits); M <- lengths(selected); N <- length(effective); n <- length(mapped)
    mu <- M*n/N; variance <- mu*(N-n)*(N-M)/N/(N-1)
    p <- stats::phyper(k-1L,M,N-M,n,lower.tail=FALSE); adj <- stats::p.adjust(p,"BH")
    pi0 <- min(1,sum(p>=.05)/(length(p)*.95))
    q <- if(pi0<=0) rep(NA_real_,length(p)) else pmin(1,adj*pi0)
    result <- data.frame(ID=names(selected),Description=unname(maps$names[names(selected)]),GeneRatio=paste0(k,"/",n),BgRatio=paste0(M,"/",N),RichFactor=k/M,FoldEnrichment=k/M*N/n,zScore=(k-mu)/sqrt(variance),pvalue=p,p.adjust=adj,qvalue=q,geneID=vapply(hits,function(v)paste(sort(v),collapse="/"),character(1)),Count=as.integer(k),stringsAsFactors=FALSE)
    result <- result[order(result$pvalue,result$ID),,drop=FALSE]; rownames(result)<-NULL
  } else if(status=="OK") status <- "NO_ELIGIBLE_TERMS"
  coverage <- data.frame(query_n=length(query),mapped_query_n=length(mapped),submitted_universe_n=length(universe),effective_universe_n=length(effective),query_hit_terms=length(gs),tested_terms=nrow(result),status=status,stringsAsFactors=FALSE)
  list(result=result,geneSets=gs,effective_universe=effective,coverage=coverage,unannotated_query=setdiff(query,maps$genes))
}
bulk_ora_member_string <- function(x) {
  vapply(strsplit(as.character(x),"/",fixed=TRUE),function(z)paste(sort(unique(z[nzchar(z)])),collapse="/"),character(1))
}
bulk_ora_compare_result <- function(actual, expected, label, rtol=1e-9, atol=1e-12) {
  cols <- names(bulk_ora_empty())
  bulk_ora_assert(all(cols %in% names(actual)) && all(cols %in% names(expected)),paste(label,"missing result columns"))
  bulk_ora_assert(!anyDuplicated(actual$ID) && !anyDuplicated(expected$ID) && setequal(actual$ID,expected$ID),paste(label,"tested ID set differs"))
  actual <- actual[match(expected$ID,actual$ID),,drop=FALSE]
  for(k in c("Description","GeneRatio","BgRatio")) bulk_ora_assert(identical(as.character(actual[[k]]),as.character(expected[[k]])),paste(label,k,"differs"))
  bulk_ora_assert(identical(bulk_ora_member_string(actual$geneID),bulk_ora_member_string(expected$geneID)),paste(label,"geneID members differ"))
  errors <- numeric()
  for(k in c("RichFactor","FoldEnrichment","zScore","pvalue","p.adjust","qvalue","Count")) {
    a <- as.numeric(actual[[k]]);b <- as.numeric(expected[[k]])
    ok <- (is.na(a)&is.na(b)) | (!is.na(a)&!is.na(b)&is.finite(a)&is.finite(b)&abs(a-b)<=atol+rtol*abs(b))
    bulk_ora_assert(all(ok),paste(label,k,"differs"));errors[k]<-if(length(a)&&any(is.finite(a-b)))max(abs(a-b),na.rm=TRUE) else 0
  }
  list(passed=TRUE,rows=nrow(expected),max_abs_error=errors)
}
