bulk_ora_select_queries <- function(signature, membership, external_ids) {
  bulk_ora_assert(all(c("gene_id","direction") %in% names(signature)),"signature columns missing")
  bulk_ora_assert(all(c("gene_id","in_e3") %in% names(membership)),"membership columns missing")
  ids <- bulk_ora_normalize_ids(signature$gene_id,"signature")
  mids <- bulk_ora_normalize_ids(membership$gene_id,"membership")
  e3 <- as.logical(membership$in_e3)
  bulk_ora_assert(!anyNA(e3) && setequal(ids,mids),"signature/E3 membership incomplete or changed")
  bulk_ora_assert(!anyNA(signature$direction) && all(signature$direction %in% c("Up","Down")),"invalid signature direction")
  e3ids <- mids[e3]; external_ids <- bulk_ora_normalize_ids(external_ids,"external availability")
  up <- ids[signature$direction=="Up"];down<-ids[signature$direction=="Down"]
  residual<-setdiff(up,e3ids)
  list(up=up,down=down,residual_up=residual,external_residual_up=intersect(residual,external_ids))
}
bulk_ora_check_receipt <- function(receipt, fingerprint) {
  bulk_ora_assert(is.list(receipt) && isTRUE(receipt$passed) && identical(as.integer(receipt$total_rows),2100L) && identical(as.integer(receipt$analyses),8L),"ORA legacy regression must pass all 2100 rows and eight analyses")
  bulk_ora_assert(identical(receipt$fingerprint,fingerprint),"ORA legacy fingerprint changed; repeat all legacy validation in a fresh output")
  TRUE
}
bulk_ora_inputs <- function(ctx) {
  needed<-c("project","analysis_dir","probe_dir","out_dir","bundle_dir")
  bulk_ora_assert(is.list(ctx)&&all(needed %in% names(ctx)),"ORA ctx requires five absolute paths")
  for(k in needed) bulk_ora_assert(length(ctx[[k]])==1L && is.character(ctx[[k]]) && grepl("^(/|[A-Za-z]:[/\\\\])",ctx[[k]]),paste("ORA ctx path not absolute:",k))
  f<-file.path(ctx$bundle_dir,"frozen/ora_input_manifest.csv");bulk_ora_assert(file.exists(f),"ORA input manifest missing")
  m<-bulk_ora_read_csv(f);bulk_ora_assert(all(c("scope","path","bytes","md5") %in% names(m))&&!anyDuplicated(paste(m$scope,m$path)),"Invalid ORA input manifest")
  bulk_ora_assert(all(m$scope %in% c("bundle","probe","analysis")),"Invalid ORA input scope")
  roots<-c(bundle=ctx$bundle_dir,probe=ctx$probe_dir,analysis=ctx$analysis_dir)
  paths<-character(nrow(m))
  for(j in seq_len(nrow(m))) {
    rel<-m$path[j];bulk_ora_assert(!grepl("(^[/\\\\]|^[A-Za-z]:|(^|[/\\\\])\\.\\.([/\\\\]|$))",rel),"Unsafe ORA manifest path")
    paths[j]<-file.path(roots[[m$scope[j]]],rel)
    bulk_ora_assert(file.exists(paths[j]),paste("Missing frozen ORA input:",paths[j]))
    bulk_ora_assert(unname(tools::md5sum(paths[j]))==m$md5[j] && file.info(paths[j])$size==as.numeric(m$bytes[j]),paste("ORA fingerprint mismatch:",m$scope[j],rel))
  }
  module<-getOption("bulk.plain.self");bulk_ora_assert(file.exists(module),"Current plain script missing")
  fingerprint<-c(input_manifest=unname(tools::md5sum(f)),module=unname(tools::md5sum(module)),setNames(m$md5,paste(m$scope,m$path,sep="/")),ctx_bundle=normalizePath(ctx$bundle_dir,winslash="/"),ctx_probe=normalizePath(ctx$probe_dir,winslash="/"),ctx_analysis=normalizePath(ctx$analysis_dir,winslash="/"))
  list(manifest=m,fingerprint=fingerprint)
}
bulk_ora_load_maps <- function(ctx) {
