  bulk_ora_assert(all(c("ENTREZID","GOALL","ONTOLOGYALL") %in% names(go$goAnno))&&all(go$goAnno$ONTOLOGYALL=="BP"),"GO resource is not propagated GOALL BP")
  bulk_ora_assert(all(c("go_id","Term") %in% names(nm)),"GOTERM name columns missing")
  gn<-unique(data.frame(term=as.character(nm$go_id),name=as.character(nm$Term),stringsAsFactors=FALSE))
