  bulk_ora_assert(nrow(gm$TERM2GENE)==1284869L&&length(gm$genes)==18805L&&length(gm$sets)==15197L,"Full GO resource counts differ")
  bulk_ora_assert(identical(kg$organism,"hsa")&&identical(kg[["_type_"]],"KEGG"),"Frozen KEGG metadata differs")
  km<-bulk_ora_maps(data.frame(term=kg$KEGGPATHID2EXTID[[1]],gene=kg$KEGGPATHID2EXTID[[2]]),data.frame(term=kg$KEGGPATHID2NAME[[1]],name=kg$KEGGPATHID2NAME[[2]]),"KEGG")
  bulk_ora_assert(nrow(km$TERM2GENE)==39562L&&length(km$genes)==9419L&&length(km$sets)==372L&&nrow(km$TERM2NAME)==372L,"Full KEGG resource counts differ")
  bulk_ora_assert(all(grepl("^hsa[0-9]{5}$",names(km$sets))),"KEGG namespace differs")
  list(GO=gm,KEGG=km)
