bulk_ora_check_library <- function(ctx) {
  versions<-c(clusterProfiler="4.16.0",DOSE="4.2.0",qvalue="2.40.0")
  for(p in names(versions)) {
    bulk_ora_assert(requireNamespace(p,quietly=TRUE),paste("Required offline package missing:",p))
    bulk_ora_assert(as.character(utils::packageVersion(p))==versions[[p]],paste("Pinned ORA package version differs:",p))
  }
  bulk_ora_assert(identical(getOption("enrichment_force_universe",FALSE),FALSE),"enrichment_force_universe must be FALSE")
  pins<-read.csv(file.path(ctx$probe_dir,"ora_function_fingerprints.csv"),stringsAsFactors=FALSE)
  stopifnot(nrow(pins)==7L,!anyDuplicated(paste(pins$package,pins$function_name)))
  for(i in seq_len(nrow(pins))){
    actual<-get(pins$function_name[i],envir=asNamespace(pins$package[i]),inherits=FALSE)
    tmp<-tempfile()
    tryCatch({
      writeLines(c(paste(deparse(formals(actual)),collapse=""),paste(deparse(body(actual)),collapse="")),tmp,useBytes=TRUE)
      bulk_ora_assert(identical(unname(tools::md5sum(tmp)),pins$md5[i]),paste("Installed ORA function changed:",pins$package[i],pins$function_name[i]))
    },finally=unlink(tmp))
  }
  invisible(TRUE)
}
