  ids<-bulk_ora_normalize_ids(approved$resolved_gene_id,"approved old signature")
  bulk_ora_assert(identical(ids[match(mb$source_symbol,approved$source_symbol)],as.character(mb$gene_id)),"Frozen signature identity bridge differs from approvals")
  bulk_ora_assert(all(mb$legacy_external_residual %in% c("True","False","TRUE","FALSE")),"Missing legacy external availability")
