bulk_ora_fit <- function(query,universe,maps,p_cut,q_cut) {
  math<-bulk_ora_math(query,universe,maps)
  warnings<-character();obj<-NULL
  if(math$coverage$status=="OK") {
    obj<-withCallingHandlers(clusterProfiler::enricher(gene=as.character(query),universe=as.character(universe),pAdjustMethod="BH",pvalueCutoff=p_cut,qvalueCutoff=q_cut,minGSSize=10L,maxGSSize=500L,TERM2GENE=maps$TERM2GENE,TERM2NAME=maps$TERM2NAME),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")})
    bulk_ora_assert(!is.null(obj),"enricher returned NULL despite eligible annotated terms")
    actual<-obj@result
    bulk_ora_compare_result(actual,math$result,paste(maps$label,"enricher vs independent counts/math"))
    bulk_ora_assert(setequal(obj@universe,math$effective_universe),"enricher effective universe differs")
    bulk_ora_assert(setequal(names(obj@geneSets),names(math$geneSets))&&all(vapply(names(math$geneSets),function(k)setequal(obj@geneSets[[k]],math$geneSets[[k]]),logical(1))),"enricher geneSets differ")
  } else actual<-math$result
  list(object=obj,result=actual,math=math,warnings=unique(warnings),pvalueCutoff=p_cut,qvalueCutoff=q_cut)
}
bulk_ora_filter_result <- function(z,p_cut,q_cut) {
  if(!nrow(z))return(z)
  keep<-!is.na(z$pvalue)&!is.na(z$p.adjust)&z$pvalue<=p_cut&z$p.adjust<=p_cut
  if(!anyNA(z$qvalue))keep<-keep&z$qvalue<=q_cut
  z[keep,,drop=FALSE]
}
bulk_ora_add_categories <- function(z,categories,database) {
  if(database=="KEGG") {
    at<-match(z$ID,categories$ID);z$category<-categories$category[at];z$subcategory<-categories$subcategory[at]
    z$category_source<-ifelse(is.na(at),"NOT_IN_VERIFIED_LEGACY_MAP","verified_original_result_terms")
  }
  z
}
bulk_ora_write_fit <- function(fit,dir,database,set_id,categories) {
  prefix<-paste(database,set_id,sep="_")
  full<-bulk_ora_add_categories(fit$result,categories,database)
  filtered<-bulk_ora_filter_result(full,fit$pvalueCutoff,fit$qvalueCutoff)
  bh<-full[!is.na(full$p.adjust)&full$p.adjust<.05,,drop=FALSE]
  bulk_ora_write_csv(full,file.path(dir,paste0(prefix,"_all_tested.csv")))
  bulk_ora_write_csv(filtered,file.path(dir,paste0(prefix,"_filtered.csv")))
  bulk_ora_write_csv(bh,file.path(dir,paste0(prefix,"_BH_lt_005.csv")))
  bulk_ora_write_csv(data.frame(gene_id=fit$math$unannotated_query),file.path(dir,paste0(prefix,"_unannotated_query.csv")))
  bulk_ora_save(fit,file.path(dir,paste0(prefix,"_full_result.rds")))
  data.frame(database=database,set_id=set_id,fit$math$coverage,filtered_terms=nrow(filtered),BH_lt_005=nrow(bh),category_missing=if(database=="KEGG")sum(is.na(full$category)) else NA_integer_,warnings=paste(fit$warnings,collapse=" | "),stringsAsFactors=FALSE)
}
bulk_validate_legacy_ora <- function(ctx) {
  inputs<-bulk_ora_inputs(ctx);bulk_ora_check_library(ctx)
  tables<-bulk_ora_frozen_tables(ctx);queries<-bulk_ora_check_queries(ctx,tables);maps<-bulk_ora_load_maps(ctx)
  universe<-bulk_ora_normalize_ids(tables$universe$ENTREZID,"old submitted universe")
  bulk_ora_assert(length(universe)==16607L&&nrow(tables$reference)==2100L,"Frozen legacy reference sizes differ")
  dir<-bulk_ora_dir(file.path(ctx$out_dir,"01_ORA","legacy"));qc<-list();checks<-list();index<-0L
  for(db in names(maps)) {
    expected_universe<-tables$effective$gene_id[tables$effective$database==db]
    bulk_ora_assert(setequal(intersect(universe,maps[[db]]$genes),expected_universe),paste(db,"legacy effective universe differs"))
    for(set_id in names(queries)) {
      index<-index+1L;primary<-set_id %in% c("up","down")
      fit<-bulk_ora_fit(queries[[set_id]],universe,maps[[db]],if(primary).05 else 1,if(primary).05 else 1)
      ref<-tables$reference[tables$reference$database==db&tables$reference$set_id==set_id,,drop=FALSE]
      ch<-bulk_ora_compare_result(fit$result,ref,paste("official legacy",db,set_id))
      if(primary) {
        oldgs<-tables$geneSets[tables$geneSets$database==db&tables$geneSets$set_id==set_id,,drop=FALSE];oldgs<-split(oldgs$gene_id,oldgs$term)
        bulk_ora_assert(setequal(names(oldgs),names(fit$math$geneSets))&&all(vapply(names(oldgs),function(k)setequal(oldgs[[k]],fit$math$geneSets[[k]]),logical(1))),paste(db,set_id,"legacy saved geneSets differ"))
      }
      qc[[index]]<-bulk_ora_write_fit(fit,dir,db,set_id,tables$categories)
      checks[[index]]<-data.frame(database=db,set_id=set_id,rows=ch$rows,passed=ch$passed,max_P=ch$max_abs_error[["pvalue"]],max_BH=ch$max_abs_error[["p.adjust"]],max_q=ch$max_abs_error[["qvalue"]])
    }
  }
  check<-do.call(rbind,checks);bulk_ora_assert(nrow(check)==8L&&sum(check$rows)==2100L&&all(check$passed),"Not all 2100 legacy ORA rows passed")
  bulk_ora_write_csv(check,file.path(dir,"legacy_regression_checks.csv"));bulk_ora_write_csv(do.call(rbind,qc),file.path(dir,"coverage_QC.csv"))
  bulk_ora_write_csv(inputs$manifest,file.path(dir,"frozen_inputs_verified.csv"))
  receipt<-list(passed=TRUE,total_rows=as.integer(sum(check$rows)),analyses=nrow(check),fingerprint=inputs$fingerprint,checks=check,version="2026-09-07.1")
  bulk_ora_save(receipt,file.path(dir,"REGRESSION_PASSED.rds"));receipt
}
bulk_ora_new_impl <- function(ctx,receipt) {
  inputs<-bulk_ora_inputs(ctx);bulk_ora_check_receipt(receipt,inputs$fingerprint);bulk_ora_check_library(ctx)
  tables<-bulk_ora_frozen_tables(ctx);legacy_queries<-bulk_ora_check_queries(ctx,tables);maps<-bulk_ora_load_maps(ctx)
  sig<-bulk_ora_read_csv(file.path(ctx$analysis_dir,"02_DE_Meta/new_selected_signature.csv"))
  ext<-bulk_ora_read_csv(file.path(ctx$analysis_dir,"02_DE_Meta/GSE65682_DE.csv"))
  bg<-bulk_ora_read_csv(file.path(ctx$analysis_dir,"01_identity/discovery_common_universe.csv"))
  universe<-bulk_ora_normalize_ids(bg$gene_id,"new canonical common universe")
  bulk_ora_assert(length(universe)==19136L,"Audited new common universe count differs")
  queries<-bulk_ora_select_queries(sig,tables$membership,ext$gene_id)
  bulk_ora_assert(identical(as.integer(lengths(queries)),c(29L,3L,16L,14L)),"New audited query membership changed; no forced-size substitutions are allowed")
  for(k in names(queries))bulk_ora_assert(setequal(queries[[k]],legacy_queries[[k]]),paste("Signature/E3 query changed beyond authorized snapshot:",k))
  dir<-bulk_ora_dir(file.path(ctx$out_dir,"01_ORA","new"));qc<-list();comparisons<-list();index<-0L
  bulk_ora_write_csv(data.frame(gene_id=universe),file.path(dir,"submitted_background_19136.csv"))
  bulk_ora_write_csv(do.call(rbind,lapply(names(queries),function(k)data.frame(set_id=k,gene_id=queries[[k]]))),file.path(dir,"derived_query_sets.csv"))
  for(db in names(maps)) {
    bulk_ora_write_csv(maps[[db]]$TERM2GENE,file.path(dir,paste0(db,"_frozen_full_TERM2GENE.csv")))
    bulk_ora_write_csv(maps[[db]]$TERM2NAME,file.path(dir,paste0(db,"_frozen_full_TERM2NAME.csv")))
    for(set_id in names(queries)) {
      index<-index+1L;primary<-set_id %in% c("up","down")
      fit<-bulk_ora_fit(queries[[set_id]],universe,maps[[db]],if(primary).05 else 1,if(primary).05 else 1)
      qc[[index]]<-bulk_ora_write_fit(fit,dir,db,set_id,tables$categories)
      old<-tables$reference[tables$reference$database==db&tables$reference$set_id==set_id,,drop=FALSE]
      comp<-merge(old[,names(bulk_ora_empty()),drop=FALSE],fit$result[,names(bulk_ora_empty()),drop=FALSE],by="ID",all=TRUE,suffixes=c("_old","_new"),sort=TRUE)
      comp$database<-db;comp$set_id<-set_id
      oldp<-as.numeric(comp$p.adjust_old);newp<-as.numeric(comp$p.adjust_new)
      comp$tested_status<-ifelse(is.na(comp$Description_old),"NEW_ONLY",ifelse(is.na(comp$Description_new),"OLD_ONLY","BOTH"))
      comp$FDR_crossed_005<-ifelse(comp$tested_status=="BOTH",(oldp<.05)!=(newp<.05),NA)
      comp$p_adjust_change<-newp-oldp
      bulk_ora_write_csv(comp,file.path(dir,paste0(db,"_",set_id,"_old_vs_new.csv")));comparisons[[index]]<-comp
    }
  }
  coverage<-do.call(rbind,qc);bulk_ora_write_csv(coverage,file.path(dir,"coverage_QC.csv"))
  combined<-do.call(rbind,comparisons);bulk_ora_write_csv(combined,file.path(dir,"all_8_ORA_old_vs_new.csv"))
  bulk_ora_write_csv(inputs$manifest,file.path(dir,"frozen_inputs_verified.csv"))
  result<-list(completed=TRUE,coverage=coverage,legacy_regression=receipt,comparison_rows=nrow(combined),new_background_n=length(universe),queries=queries,version="2026-09-07.1")
  bulk_ora_save(result,file.path(dir,"ORA_COMPLETED.rds"));result
}



