bulk_test_models <- function() {
  stopifnot(exists('bulk_models_align', mode='function'))
  failures <- function(expr) inherits(try(force(expr),silent=TRUE),'try-error')
  ids <- paste0('s',1:24)
  mat <- matrix(seq_len(72),nrow=3,dimnames=list(paste0('ENTREZ:',1:3),ids))
  meta <- data.frame(sample=ids,outcome=rep(c('Survivor','Survivor','NonSurvivor','Survivor','Survivor','NonSurvivor'),4),cohort=rep(c('Discovery','Discovery','Discovery','Validation','Validation','Validation'),4),mars=rep(paste0('Mars',1:4),each=6),stringsAsFactors=FALSE)
  groups <- setNames(meta$outcome,ids);batch <- tolower(meta$cohort)
  a <- bulk_models_align(mat,meta[24:1,],groups,batch)
  stopifnot(identical(a$sample,ids),failures(bulk_models_align(mat,meta[-1,],groups,batch)))
  bad <- meta;bad$sample[2]<-bad$sample[1];stopifnot(failures(bulk_models_align(mat,bad,groups,batch)))
  stopifnot(failures(bulk_models_align(mat,meta,groups[24:1],batch)))
  bad<-meta;bad$outcome[1]<-'NonSurvivor';stopifnot(failures(bulk_models_align(mat,bad,groups,batch)))
  plan<-bulk_models_plan(a);stopifnot(length(plan)==7L,identical(names(plan),c('combined_unadjusted','discovery_only','validation_only','Mars1','Mars2','Mars3','Mars4')))
  design<-bulk_models_design(a[plan$Mars4$index,],TRUE)
  stopifnot(ncol(design)==3L,qr(design)$rank==3L,all(table(a$cohort[plan$Mars4$index],a$outcome[plan$Mars4$index])>=1L))
  one_ns<-a[plan$Mars4$index,];one_ns<-one_ns[-3,];stopifnot(failures(bulk_models_design(one_ns,TRUE)))
  old<-data.frame(gene=c('oldA','ambig','aliasA'),logFC=c(.2,-.2,.4),t=1:3,P.Value=c(.1,.2,.3),adj.P.Val=c(.2,.3,.4),B=0)
  links<-data.frame(old_symbol=c('oldA','ambig','aliasA'),old_probe=c('p1','p2','p3'),gene_id=c('ENTREZ:1','','ENTREZ:1'))
  new<-data.frame(gene_id=c('ENTREZ:1','ENTREZ:3'),logFC=c(.25,.8),t=c(3,4),P.Value=c(.01,.02),adj.P.Val=c(.02,.02),B=c(1,2))
  cmp<-bulk_models_compare(old,new,links)
  stopifnot(all(cmp$old_identity_multiplicity[c(1,3)]==2L),is.na(cmp$old_identity_multiplicity[2]),all(is.na(cmp$representative_changed)))
  stopifnot(nrow(cmp)==3L,all(cmp$comparison_status[c(1,3)]=='compared_identity'),cmp$comparison_status[2]=='unresolved_old_identity',is.na(cmp$logFC_new[2]),cmp$logFC_new[1]==.25,cmp$logFC_new[3]==.25)
  probes <- data.frame(gene_id='ENTREZ:1',selected_probe='p1')
  cmp2 <- bulk_models_compare(old,new,links,probes)
  stopifnot(identical(cmp2$representative_changed,c(FALSE,NA,TRUE)))
  stopifnot(bulk_models_invariants(old[1,,drop=FALSE],new,'oldA','ENTREZ:1',tol=.1)$passed)
  stopifnot(failures(bulk_models_invariants(old[1,,drop=FALSE],new,'oldA','ENTREZ:1',tol=1e-10)))
  tmp<-tempfile();bulk_models_write_csv(new,tmp);stopifnot(file.exists(tmp),failures(bulk_models_write_csv(new,tmp)))
  unlink(tmp)
  'PASS model alignment, seven scope designs, nonempty singleton cells, canonical comparison, invariant failures, no overwrite'
}



