bulk_np_write_output_manifest <- function(out) {
  p<-list.files(out,recursive=TRUE,full.names=TRUE,all.files=TRUE);p<-p[!dir.exists(p)&basename(p)!="output_manifest.csv"]
  write.csv(data.frame(path=substring(p,nchar(out)+2L),bytes=file.info(p)$size,md5=unname(tools::md5sum(p))),
            file.path(out,"output_manifest.csv"),row.names=FALSE)
}
bulk_np_parallel <- function() BiocParallel::register(BiocParallel::SerialParam(),default=TRUE)
bulk_np_run <- function(ctx) {
  # The caller is an isolated --vanilla child, never the original restored R session.
  stopifnot(as.character(getRversion())=="4.5.1")
  if(nzchar(Sys.getenv("BULK_LIBS"))) .libPaths(strsplit(Sys.getenv("BULK_LIBS"),.Platform$path.sep,fixed=TRUE)[[1L]])
  ctx$project<-normalizePath(ctx$project,winslash="/",mustWork=TRUE)
  ctx$bundle_dir<-normalizePath(ctx$bundle_dir,winslash="/",mustWork=TRUE)
  if(is.null(ctx$out_dir))stop("Unified dispatcher must supply a fresh analysis output directory")
  stopifnot(!file.exists(ctx$out_dir),dir.create(ctx$out_dir));out<-ctx$out_dir
  log<-file(file.path(out,"run.log"),"wt");sink(log,split=TRUE);sink(log,type="message")
  closed<-FALSE;close_log<-function(){if(!closed){sink(type="message");sink();close(log);closed<<-TRUE}}
  on.exit(close_log(),add=TRUE);warnings<-character();completed<-FALSE;comparison<-NULL;err<-NULL
  tryCatch(withCallingHandlers({
    cat("BULK consolidated BULK reanalysis v2026-09-07.1 -- NO PLOTS\nOutput: ",out,"\n",sep="")
    writeLines("STARTED_NOT_VALIDATED",file.path(out,"STATUS.txt"))
    im<-read.csv(file.path(ctx$bundle_dir,"external_inputs_manifest.csv"),stringsAsFactors=FALSE)
    before<-bulk_np_manifest(im,ctx);write.csv(before,file.path(out,"original_inputs_checked_before.csv"),row.names=FALSE)
    guards<-bulk_np_guards(FALSE)
    Sys.setenv(http_proxy="http://127.0.0.1:9",https_proxy="http://127.0.0.1:9",HTTP_PROXY="http://127.0.0.1:9",HTTPS_PROXY="http://127.0.0.1:9",ALL_PROXY="http://127.0.0.1:9",all_proxy="http://127.0.0.1:9",NO_PROXY="",no_proxy="")
    lock<-read.csv(file.path(ctx$bundle_dir,"package_lock.csv"),stringsAsFactors=FALSE)
    for(i in seq_len(nrow(lock))) {
      pkg<-lock$package[i]
      if(!requireNamespace(pkg,quietly=TRUE)||as.character(utils::packageVersion(pkg))!=lock$version[i])stop("FROZEN_PACKAGE_MISMATCH: ",pkg)
    }
    guards<-c(guards,bulk_np_guards(TRUE));writeLines(guards,file.path(out,"offline_noplot_guards.txt"))
    options(enrichment_force_universe=FALSE,device=function(...)stop("BULK_NO_PLOTS"))
    bulk_np_parallel()
    writeLines(capture.output(sessionInfo()),file.path(out,"sessionInfo_start.txt"))
    writeLines(c(bulk_test_control(),bulk_test_main_adapter(),bulk_test_compare_audited()),file.path(out,"integration_unit_tests_passed.txt"))
    cat("[MAIN] Fresh original GEO reconstruction, frozen final adjudication, identity checks and all main statistics.\n")
    main<-bulk_run_main(ctx)
    stopifnot(identical(normalizePath(main,winslash="/"),normalizePath(file.path(out,"main"),winslash="/")))
    downstream<-bulk_np_downstream(ctx,main)
    cat("[COMPARE] Checking 215 ordered scientific fingerprints (11 significant digits; exact identities/decision boundaries). No old result dataset is read.\n")
    comparison<-bulk_compare_audited(ctx)
    stopifnot(is.list(comparison),is.logical(comparison$passed),length(comparison$passed)==1L,!is.na(comparison$passed))
    after<-bulk_np_manifest(im,ctx);stopifnot(identical(before,after))
    write.csv(after,file.path(out,"original_inputs_checked_after.csv"),row.names=FALSE)
    graphics_files<-list.files(out,recursive=TRUE,pattern="[.](pdf|png|jpg|jpeg|tiff|bmp|svg|ps)$",ignore.case=TRUE)
    stopifnot(length(graphics_files)==0L)
    saveRDS(comparison,file.path(out,"final_comparison.rds"));completed<-TRUE
  },warning=function(w){warnings<<-c(warnings,conditionMessage(w))}),error=function(e){err<<-conditionMessage(e);writeLines(err,file.path(out,"ERROR.txt"))})
  status<-bulk_np_status(completed,if(is.null(comparison))FALSE else comparison$passed)
  writeLines(unique(warnings),file.path(out,"warnings.txt"))
  writeLines(capture.output(sessionInfo()),file.path(out,"sessionInfo_end.txt"))
  writeLines(status,file.path(out,"STATUS.txt"))
  cat("\n============================================================\nFINAL_STATUS: ",status,"\n",sep="")
  if(status=="MATCHES_SCIENTIFIC_FINGERPRINTS")cat("PASS: All 215 scientific output checks passed (ordered fingerprints or pinned exact-reference CSV bytes); identities and decision boundaries preserved. No tolerance was relaxed.\n")
  else if(status=="COMPLETED_BUT_DIFFERS_FROM_AUDITED")cat("NOT A MATCH: Analyses completed, but at least one checked result differs. Do not adopt this run.\n")
  else cat("STOPPED: ",err,"\nThis run has NOT reproduced the audited results.\n",sep="")
  if(!is.null(comparison$summary))print(comparison$summary)
  if(!is.null(comparison) && !isTRUE(comparison$passed)) {
    if(!is.null(comparison$files))print(utils::head(comparison$files[!comparison$files$passed,,drop=FALSE],10L))
    if(!is.null(comparison$differences) && nrow(comparison$differences))print(utils::head(comparison$differences,10L))
  }
  cat("Warnings recorded: ",length(unique(warnings)),"\nOutput: ",out,
      "\nNo figures were requested. Original parent R objects and historical outputs were not overwritten.\n============================================================\n",sep="")
  close_log();bulk_np_write_output_manifest(out)
  if(!completed)stop("FINAL_STATUS: STOPPED_NOT_VALIDATED; see the console reason above",call.=FALSE)
  invisible(status)
}


# ==========================================================================
# Numerical reproducibility comparison
# ==========================================================================
# Read-only scientific comparison. References are NEVER analysis inputs.
# IDs, order, direction and decision boundaries are exact; no byte-equality claim.
bulk_audit_number_equal <- function(a,b,policy="numeric",rtol=1e-8,atol=1e-10) {
  if(length(a)!=length(b)) return(FALSE)
  ans <- rep(FALSE,length(a)); both_na <- is.na(a)&is.na(b)&(is.nan(a)==is.nan(b))
  ans[both_na] <- TRUE
  finite <- is.finite(a)&is.finite(b)
  ans[!finite & !is.na(a)&!is.na(b)] <- a[!finite & !is.na(a)&!is.na(b)]==b[!finite & !is.na(a)&!is.na(b)]
  x<-a[finite];y<-b[finite]
  if(policy=="exact") z<-x==y else if(policy=="probability") {
    # No absolute tolerance for P/FDR/q, including subnormal or zero values.
    z <- abs(x-y)<=rtol*pmax(abs(x),abs(y)) & (x==0)==(y==0)
    for(cut in c(.001,.01,.05,.1)) z<-z & ((x<cut)==(y<cut)) & ((x<=cut)==(y<=cut))
  } else {
    z<-abs(x-y)<=atol+rtol*pmax(abs(x),abs(y))
    if(policy %in% c("signed","effect")) z<-z & sign(x)==sign(y)
    if(policy=="effect") for(cut in c(.1,.2,.3,.5,.7,1)) z<-z & ((abs(x)>cut)==(abs(y)>cut)) & ((abs(x)>=cut)==(abs(y)>=cut))
  }
  ans[finite]<-z;ans
}
bulk_audit_policy <- function(name) {
  if(name %in% c("Count","size","effective_size","n_candidate_probes","iteration","pool_size","signature_total","evaluable","random_sets","exceedances","seed","draw_indices")) return("exact")
  if(grepl("(^pvalue|^pval|^padj|^p\\.adjust|^p\\.value|^F\\.p\\.value|^qvalue|^fdr|^P\\.Value|^adj\\.P\\.Val|^P$|^FDR$|fisher_pval|fisher_fdr|^re_p($|_)|^re_fdr($|_)|adjusted_upper_tail_proportion)",name)) return("probability")
  if(grepl("logFC",name)) return("effect")
  if(name %in% c("t","ES","NES","delta","re_estimate","coefficients") || grepl("^t_",name)) return("signed")
  "numeric"
}
bulk_audit_table <- function(actual,reference,key,policies) {
  differences<-data.frame(column=character(),n_bad=integer(),rows=character(),reason=character(),stringsAsFactors=FALSE)
  add<-function(col,n,rows,reason) differences[nrow(differences)+1L,]<<-list(col,n,paste(head(rows,20L),collapse=";"),reason)
  if(!identical(names(actual),names(reference))) add("<schema>",1L,"","column names/order")
  if(nrow(actual)!=nrow(reference)) add("<rows>",abs(nrow(actual)-nrow(reference)),"","row count")
  keys<-if(length(key)==1L && nzchar(key)) strsplit(key,"|",fixed=TRUE)[[1]] else character()
  for(z in list(actual=actual,reference=reference)) {
    if(length(keys) && all(keys %in% names(z))) {
      dup<-duplicated(z[,keys,drop=FALSE]);if(any(dup)) add("<key>",sum(dup),which(dup),"duplicate key")
    } else if(length(keys)) add("<key>",1L,"","missing key column")
  }
  if(nrow(actual)==nrow(reference)) for(nm in intersect(names(actual),names(reference))) {
    a<-actual[[nm]];b<-reference[[nm]];policy<-unname(policies[nm]);if(is.na(policy)) stop("Missing comparison policy: ",nm)
    if(policy=="exact") same<-(is.na(a)&is.na(b)) | (!is.na(a)&!is.na(b)&as.character(a)==as.character(b)) else {
      aa<-suppressWarnings(as.numeric(a));bb<-suppressWarnings(as.numeric(b))
      bad_a<-is.na(aa)&!is.na(a)&!as.character(a)%in%c("NA","NaN","")
      bad_b<-is.na(bb)&!is.na(b)&!as.character(b)%in%c("NA","NaN","")
      same<-bulk_audit_number_equal(aa,bb,policy)&!bad_a&!bad_b
    }
    bad<-which(!same | is.na(same));if(length(bad)) add(nm,length(bad),bad,paste("semantic",policy,"mismatch"))
  }
  list(passed=!nrow(differences),differences=differences)
}
bulk_audit_project <- function(z,kind) {
  if(kind=="rds") return(z)
  if(kind=="xcell") return(z[c("scores","statistics","input_map","coverage")])
  if(kind=="identity") return(list(axes=lapply(z$matrices,dimnames),groups=z$groups,batch=z$batch,common=z$common,three=z$three,selections=z$selections,old_row_links=z$old_row_links))
  if(kind=="checkpoint_xcell") return(lapply(z,function(v) v[c("scores","statistics","input_map","coverage")]))
  if(kind=="checkpoint_de") return(list(DE=lapply(z$DE,function(v)v[c("result","design","contrast")]),meta=z$meta))
  if(kind=="de_fit") return(z[c("result","design","contrast")])
  if(kind=="model_fit") return(c(z[c("design","contrast","samples","gene_ids","trend","robust","limma_version")],list(moderated=unclass(z$fit_ebayes)[c("coefficients","stdev.unscaled","sigma","df.residual","cov.coefficients","df.prior","s2.prior","var.prior","proportion","s2.post","t","df.total","p.value","lods","F","F.p.value")])) )
  if(kind=="ora") return(list(result=z$result,math=z$math,query=methods::slot(z$object,"gene"),universe=methods::slot(z$object,"universe"),geneSets=methods::slot(z$object,"geneSets")))
  stop("Unknown RDS projection: ",kind)
}
bulk_audit_object <- function(a,b,path="object") {
  errors<-character()
  walk<-function(x,y,p) {
    fail<-function(s) errors<<-c(errors,paste(p,s))
    if(!identical(is.null(x),is.null(y))) {fail("NULL mismatch");return()};if(is.null(x))return()
    if(is.factor(x))x<-as.character(x);if(is.factor(y))y<-as.character(y)
    if(!identical(dim(x),dim(y))||!identical(dimnames(x),dimnames(y))||!identical(names(x),names(y))) {fail("dimensions/names/order mismatch");return()}
    if(is.data.frame(x)&&is.data.frame(y)) {
      pol<-vapply(names(y),function(n) if(is.numeric(y[[n]]))bulk_audit_policy(n) else "exact",character(1))
      ans<-bulk_audit_table(x,y,"",pol);if(!ans$passed)fail(paste(ans$differences$column,collapse=","));return()
    }
    if(is.list(x)&&is.list(y)) {if(length(x)!=length(y)){fail("list length");return()};for(i in seq_along(y))walk(x[[i]],y[[i]],paste0(p,"/",if(is.null(names(y)))i else names(y)[i]));return()}
    if(is.numeric(x)&&is.numeric(y)) {
      nm<-tail(strsplit(p,"/",fixed=TRUE)[[1]],1)
      policy<-if(is.integer(y)||nm%in%c("draw_indices","seed"))"exact" else bulk_audit_policy(nm)
      if(length(x)!=length(y)||!all(bulk_audit_number_equal(as.vector(x),as.vector(y),policy)))fail(paste(policy,"values mismatch"))
    } else if(!identical(x,y)) fail("exact values/type mismatch")
  }
  walk(a,b,path);list(passed=!length(errors),errors=errors)
}
bulk_audit_read_csv <- function(f) read.csv(f,check.names=FALSE,colClasses="character",stringsAsFactors=FALSE,na.strings="NA")
bulk_compare_audited_impl <- function(ctx) {
  if(length(SCIENCE_EXPECTED)!=215L)stop('Expected 215 scientific fingerprint definitions')
  results<-lapply(SCIENCE_EXPECTED,function(s) {
    actual<-NA_character_;reason<-'';match_method<-'ORDERED_SCIENTIFIC_FINGERPRINT'
    ok<-tryCatch({
      path<-file.path(ctx$out_dir,s$component,s$source)
      if(!file.exists(path))stop('Missing scientific output')
      x<-if(s$kind=='csv')scientific_csv_object(bulk_audit_read_csv(path),s$numeric_columns)else
        bulk_audit_project(readRDS(path),s$kind)
      if(s$kind=='csv'&&nzchar(s$key)) {
        keys<-strsplit(s$key,'|',fixed=TRUE)[[1L]]
        if(!all(keys%in%names(x))||anyDuplicated(x[keys]))stop('Scientific key missing/duplicated')
      }
      actual<-scientific_fingerprint(x)
      raw_expected<-unname(SCIENCE_EXACT_CSV_PINS[paste(s$component,s$source,sep='/')])
      raw_actual<-if(!is.na(raw_expected))unname(tools::md5sum(path))else NA_character_
      if(!scientific_result_matches(actual,s$md5,raw_expected,raw_actual))
        stop('Ordered scientific fingerprint differs; exact-reference file check did not match')
      if(!identical(actual,s$md5))match_method<-'EXACT_REFERENCE_CSV_BYTES'
      TRUE
    },error=function(e){reason<<-conditionMessage(e);FALSE})
    data.frame(component=s$component,file=s$source,kind=s$kind,reference_rows=s$rows,
      expected_md5=s$md5,actual_md5=actual,passed=ok,reason=if(ok)'MATCH'else reason,validation_method=match_method)
  })
  files<-do.call(rbind,results)
  summary<-do.call(rbind,lapply(unique(files$component),function(co){
    d<-files[files$component==co,,drop=FALSE]
    data.frame(scope=co,files=nrow(d),csv_rows=sum(d$reference_rows,na.rm=TRUE),
      mismatched_files=sum(!d$passed),passed=all(d$passed))
  }))
  folder<-file.path(ctx$out_dir,'audited_comparison');dir.create(folder,recursive=TRUE,showWarnings=FALSE)
  write.csv(files,file.path(folder,'comparison_summary.csv'),row.names=FALSE)
  writeLines(c('METHOD=ordered-science-v1-11sig-exact-decisions',
    '215 projected scientific outputs; order, identities, sign, zero and decision-boundary bits are checked.',
    'Numeric fingerprint encoding uses 11 significant decimal digits.',
    'This is not the previous pairwise rtol/atol comparison; no old result datasets were read.',
    'Two validation-only CSVs also allow exact original-reference file MD5 equality; no numeric tolerance was relaxed.'),
    file.path(folder,'comparison_method.txt'))
  result<-list(passed=all(files$passed),summary=summary,files=files,
    differences=files[!files$passed,,drop=FALSE],method='ordered-science-v1-11sig-exact-decisions')
  saveRDS(result,file.path(folder,'comparison_result.rds'));result
}

bulk_compare_audited <- function(ctx) tryCatch(bulk_compare_audited_impl(ctx),error=function(e) {
  d<-data.frame(column="<comparison>",n_bad=1L,rows="",reason=conditionMessage(e),file="<manifest/reference>",component="audit",stringsAsFactors=FALSE)
  s<-data.frame(scope="audit",files=0L,csv_rows=0L,mismatched_files=1L,passed=FALSE)
  o<-file.path(ctx$out_dir,"audited_comparison");dir.create(o,recursive=TRUE,showWarnings=FALSE)
  try(write.csv(d,file.path(o,"comparison_differences.csv"),row.names=FALSE),silent=TRUE)
  list(passed=FALSE,summary=s,differences=d)
})


