bulk_test_control <- function() {
  stopifnot(exists("bulk_np_status",mode="function"),exists("bulk_np_manifest",mode="function"))
  stopifnot(bulk_np_status(TRUE,TRUE)=="MATCHES_SCIENTIFIC_FINGERPRINTS",
    bulk_np_status(TRUE,FALSE)=="COMPLETED_BUT_DIFFERS_FROM_AUDITED",
    bulk_np_status(FALSE,FALSE)=="STOPPED_NOT_VALIDATED")
  tmp<-tempfile();stopifnot(dir.create(tmp));writeLines("frozen",file.path(tmp,"x"))
  m<-data.frame(scope="project",path="x",bytes=file.info(file.path(tmp,"x"))$size,
      md5=unname(tools::md5sum(file.path(tmp,"x"))))
  ctx<-list(project=tmp,bundle_dir=tmp)
  stopifnot(nrow(bulk_np_manifest(m,ctx))==1L)
  stopifnot(exists("bulk_np_stage_downstream",mode="function"))
  bad<-m;bad$path<-"../x";stopifnot(inherits(try(bulk_np_manifest(bad,ctx),silent=TRUE),"try-error"))
  bad<-m;bad$md5<-paste(rep("0",32),collapse="");stopifnot(inherits(try(bulk_np_manifest(bad,ctx),silent=TRUE),"try-error"))
  stopifnot(inherits(try(bulk_np_manifest(rbind(m,m),ctx),silent=TRUE),"try-error"))
  stopifnot(nrow(bulk_np_manifest(m,ctx))==1L)
  b<-file.path(tmp,"bundle");run<-file.path(tmp,"run");main<-file.path(run,"main")
  stopifnot(dir.create(file.path(b,"downstream","frozen"),recursive=TRUE),dir.create(main,recursive=TRUE))
  writeLines("# immutable module",file.path(b,"downstream","ora.R"))
  writeLines("frozen reference",file.path(b,"downstream","frozen","ref.csv"))
  allow<-c("01_identity/discovery_common_universe.csv","02_DE_Meta/new_selected_signature.csv",
           "02_DE_Meta/GSE65682_DE.csv","approved_decisions/old_signature_decisions.csv")
  for(p in allow){dir.create(dirname(file.path(main,p)),recursive=TRUE,showWarnings=FALSE);writeLines(p,file.path(main,p))}
  source_m<-data.frame(scope=c(rep("analysis",4),"bundle"),path=c(allow,"frozen/ref.csv"),bytes=rep(1,5),md5=rep(paste(rep("0",32),collapse=""),5))
  mp<-file.path(b,"downstream/frozen/ora_input_manifest.csv");write.csv(source_m,mp,row.names=FALSE)
  old_hash<-unname(tools::md5sum(mp));dc<-bulk_np_stage_downstream(list(project=tmp,bundle_dir=b,out_dir=run),main)
  runtime_m<-read.csv(file.path(dc$bundle_dir,"frozen/ora_input_manifest.csv"),stringsAsFactors=FALSE,colClasses=c(md5="character"))
  stopifnot(unname(tools::md5sum(mp))==old_hash,
    identical(runtime_m$md5[1:4],unname(tools::md5sum(file.path(main,allow)))),
    isTRUE(all.equal(runtime_m[5,],source_m[5,],check.attributes=FALSE)),file.exists(file.path(dc$bundle_dir,"frozen/ref.csv")),
    dc$probe_dir==file.path(b,"frozen_ora"),dc$analysis_dir==main)
  c("three explicit console outcomes", "all input pins and path/duplicate/mutation gates", "test original input preserved",
    "runtime staging copies frozen references and changes only four fresh-output input pins")
}
bulk_test_main_adapter <- function() {
  n <- all.names(body(bulk_run_main),functions=TRUE)
  stopifnot(all(c("reconstruct_inputs","identity_apply","collapse_probes","run_de","run_meta","run_pc1","run_hallmark","run_xcell") %in% n), !"sys.source" %in% n)
