}
bulk_test_compare_audited <- function() {
  stopifnot(exists("bulk_audit_number_equal", mode="function"))
  stopifnot(identical(bulk_audit_policy("re_p_new"),"probability"),identical(bulk_audit_policy("re_fdr_new"),"probability"))
  ok <- function(x, label) if (!isTRUE(x)) stop(label, call.=FALSE)
  ok(bulk_audit_number_equal(1, 1+1e-12, "numeric"), "roundoff allowed")
  ok(!bulk_audit_number_equal(1e-40, 2e-40, "probability"), "tiny P must not vanish into absolute tolerance")
  ok(!bulk_audit_number_equal(0, 1e-300, "probability"), "zero P must stay zero")
  ok(!bulk_audit_number_equal(NA_real_, NaN, "numeric"),"NA must not hide NaN")
  ok(!bulk_audit_number_equal(.05-1e-12, .05+1e-12, "probability"), "GO FDR threshold must stay exact")
  ok(!bulk_audit_number_equal(-1e-13, 1e-13, "signed"), "effect direction must stay exact")
  for(cut in c(.1,.2,.3,.5,.7,1)) ok(!bulk_audit_number_equal(cut-1e-12,cut+1e-12,"effect"),paste("effect decision",cut))
  d <- data.frame(gene_id=c("ENTREZ:1","ENTREZ:2"), pvalue=c("1e-40",".1"), score=c("1","2"), check.names=FALSE)
  policies <- c(gene_id="exact",pvalue="probability",score="numeric")
  ok(bulk_audit_table(d,d,"gene_id",policies)$passed,"selfcompare")
  bad <- d; bad$gene_id[1] <- "ENTREZ:999"
  ok(!bulk_audit_table(bad,d,"gene_id",policies)$passed,"signature identity mutation")
  bad <- d; bad$gene_id[2] <- bad$gene_id[1]
  ok(!bulk_audit_table(bad,d,"gene_id",policies)$passed,"duplicate key")
  bad <- d; bad$score[1] <- "1.01"
  ok(!bulk_audit_table(bad,d,"gene_id",policies)$passed,"one score mutation")
  bad <- d; bad$pvalue[1] <- "2e-40"
  ok(!bulk_audit_table(bad,d,"gene_id",policies)$passed,"table tiny P mutation")
  p<-tempfile();dir.create(p);on.exit(unlink(p,recursive=TRUE),add=TRUE)
  ans<-bulk_compare_audited(list(out_dir=p))
  ok(!ans$passed && nrow(ans$differences)==215L,"all missing result files fail closed")
  ok(scientific_fingerprint(c(.05,1e-100))!=scientific_fingerprint(c(.05-1e-15,1e-100)),"fingerprint threshold exact")
  c("numeric roundoff", "tiny P", "zero P", "NA/NaN", "GO threshold", "six effect thresholds", "RE probability suffixes", "direction", "selfcompare", "signature identity", "duplicate key", "one score", "table tiny P", "all 215 missing outputs rejected", "fingerprint threshold exact")
}


 environment()
}

make_plotting_engine <- function() {

# ==========================================================================
# Plotting: helpers
# ==========================================================================
strict_match <- function(keys, d, key) {
  if (!key %in% names(d) || anyNA(d[[key]]) || anyDuplicated(d[[key]]) || anyNA(keys)) stop("Invalid or duplicated identity key: ",key)
  i <- match(keys,d[[key]])
  if (anyNA(i)) stop("Unmatched identity: ",paste(head(keys[is.na(i)],10),collapse=", "))
  d[i,,drop=FALSE]
}
de_class <- function(fc, fdr) {
  if(length(fc)!=length(fdr) || any(!is.finite(fc)) || any(!is.finite(fdr)) || any(fdr<0|fdr>1)) stop("Invalid DE statistics")
  ifelse(fdr<.05 & fc>.5,"Up",ifelse(fdr<.05 & fc< -.5,"Down","Not significant"))
}
same_direction <- function(m) apply(m,1,function(x)all(is.finite(x)) && (all(x>0)||all(x<0)))
pca_coordinates <- function(mat, ids, groups) {
  if(is.null(rownames(mat))||is.null(colnames(mat))||anyDuplicated(ids)||anyDuplicated(rownames(mat))) stop("Invalid PCA IDs")
  if(!identical(names(groups),colnames(mat))) stop("PCA sample order mismatch")
  j <- match(ids,rownames(mat)); if(anyNA(j))stop("PCA features missing")
  x <- t(mat[j,,drop=FALSE])
  if(any(!is.finite(x)) || any(apply(x,2,sd)<=0)) stop("PCA nonfinite or zero variance feature; not silently discarded")
  p <- prcomp(x,center=TRUE,scale.=TRUE,rank.=2)
  # Deterministic orientation, independent of outcome: largest absolute loading positive.
  for(k in 1:2) if(p$rotation[which.max(abs(p$rotation[,k])),k]<0) p$x[,k] <- -p$x[,k]
  v <- p$sdev^2/sum(p$sdev^2)*100
  data.frame(sample=rownames(x),outcome=unname(groups),PC1=p$x[,1],PC2=p$x[,2],PC1_pct=v[1],PC2_pct=v[2],feature_count=ncol(x),row.names=NULL)
}
figure_status <- function(data_ok, files_ok, visual_ok=FALSE) {
  if(!isTRUE(data_ok)||!isTRUE(files_ok)) "STOPPED_NOT_COMPLETE" else if(!isTRUE(visual_ok)) "PLOTS_RENDERED_AWAITING_VISUAL_REVIEW" else "PLOTS_VISUALLY_REVIEWED"
}
read_table_checked <- function(path) {
  if(!file.exists(path)) stop("Missing input: ",path)
  read.csv(path,stringsAsFactors=FALSE,check.names=FALSE)
}
write_source <- function(d, out, name) {
  if(anyDuplicated(names(d))) stop("Duplicate source columns")
  write.csv(d,file.path(out,"source_data",paste0(name,"_source_data_v20260910_7.csv")),row.names=FALSE,na="")
  invisible(d)
}
wrap_label <- function(x,width=38) vapply(x,function(z)paste(strwrap(z,width=width),collapse="\n"),character(1))
p_text <- function(p) ifelse(p<.001,format(p,scientific=TRUE,digits=2),format(round(p,3),nsmall=3))


# ==========================================================================
# Plotting: data
# ==========================================================================
prepare_figure_data <- function(main, downstream, bundle, out, compute_pca=TRUE) {
  rd <- function(root,p) read_table_checked(file.path(root,p))
  fr <- function(p) rd(file.path(bundle,"frozen"),p)
  cohorts <- c("GSE272769","GSE95233","GSE65682")
  meta <- rd(main,"02_DE_Meta/Meta_all_genes.csv")
  ids <- fr("signature_identity.csv"); layout <- fr("signature_layout.csv")
  layout$gene_id <- strict_match(layout$gene,ids,"source_symbol")$resolved_gene_id
  sig <- strict_match(layout$gene_id,meta,"gene_id")
  stopifnot(all(sig$selected),setequal(sig$gene_id,subset(meta,selected)$gene_id))
  sig$gene <- layout$gene; sig$module <- layout$module
  heatmap <- sig
  heatmap$individual_cohort_support <- ifelse(sig$individual_support_272769 & sig$individual_support_95233,"Both cohorts",ifelse(sig$individual_support_272769,"GSE272769 only",ifelse(sig$individual_support_95233,"GSE95233 only","Neither cohort")))
  heatmap$I2_group <- as.character(cut(sig$I2,c(-Inf,25,50,75,Inf),right=FALSE,labels=c("<25%","25-50%","50-75%",">=75%")))
  heatmap$I2_group[is.na(heatmap$I2_group)] <- "Not estimable"
  de <- setNames(lapply(cohorts,function(c)rd(main,paste0("02_DE_Meta/",c,"_DE.csv"))),cohorts)
  external <- de$GSE65682
  extsig <- sig[sig$gene_id %in% external$gene_id,,drop=FALSE]
  ex <- strict_match(extsig$gene_id,external,"gene_id")
  extsig$external_logFC <- ex$logFC; extsig$external_P <- ex$P.Value; extsig$external_FDR <- ex$adj.P.Val
  extsig$direction_concordant <- sign(extsig$external_logFC)==sign(extsig$re_estimate)
  rlayout <- fr("residual_layout.csv")
  residual <- strict_match(rlayout$signature_gene,extsig,"gene")
  # Preserve manually arranged label coordinates, not old estimates or P values.
  residual$label_x <- rlayout$label_x; residual$label_y <- rlayout$label_y; residual$label_hjust <- rlayout$label_hjust
  ora <- list(); ora_all <- list()
  for(db in c("GO","KEGG")) for(q in c("up","down","residual_up","external_residual_up")){
    key <- paste(db,q,sep="_")
    ora_all[[key]] <- rd(downstream,paste0("01_ORA/new/",key,"_all_tested.csv"))
    ora[[key]] <- ora_all[[key]][ora_all[[key]]$p.adjust<.05,,drop=FALSE]
  }
  dumbbell <- fr("ora_term_layout.csv")[,c("ID","Term","Database","Term_display")]
  for(i in seq_len(nrow(dumbbell))){
    db <- if(startsWith(dumbbell$ID[i],"GO:"))"GO" else "KEGG"
    full <- strict_match(dumbbell$ID[i],ora_all[[paste0(db,"_up")]],"ID")
    res <- strict_match(dumbbell$ID[i],ora_all[[paste0(db,"_residual_up")]],"ID")
    dumbbell$Full_FDR[i] <- full$p.adjust; dumbbell$Residual_FDR[i] <- res$p.adjust
    dumbbell$Full_gene_count[i] <- full$Count; dumbbell$Residual_gene_count[i] <- res$Count
  }
  mars <- rd(downstream,"models/GSE65682_per_MARS_signature_statistics_refreshed.csv")
  mq <- rd(downstream,"models/input_model_QC.csv")
  mars_summary <- do.call(rbind,lapply(paste0("Mars",1:4),function(nm){
    d <- mars[mars$MARS==nm,,drop=FALSE]; q <- strict_match(nm,mq,"model")
    data.frame(MARS=nm,S=q$survivors,NS=q$non_survivors,agree=sum(d$directionally_concordant),total=nrow(d),pct=100*mean(d$directionally_concordant))
  }))
  ml <- fr("mars3_layout.csv")
  mars3 <- strict_match(ml$gene,mars[mars$MARS=="Mars3",],"gene")
  # Frozen order is legitimate because unchanged logFC is explicitly checked.
  stopifnot(max(abs(mars3$logFC-ml$logFC))<1e-10)
  mars3$display_group <- ml$display_group; mars3$display_order_left_to_right <- ml$display_order_left_to_right
  hm <- setNames(lapply(cohorts,function(c)rd(main,paste0("04_Hallmark/",c,"_all50.csv"))),cohorts)
  hallmark <- data.frame(pathway=sort(hm[[1]]$pathway))
  for(c in cohorts){ d <- strict_match(hallmark$pathway,hm[[c]],"pathway"); for(k in c("NES","padj","pval","size"))hallmark[[paste0(k,"_",c)]]<-d[[k]] }
  hallmark$mean_abs_NES <- rowMeans(abs(as.matrix(hallmark[paste0("NES_",cohorts)])))
  hallmark$all_same_dir <- same_direction(as.matrix(hallmark[paste0("NES_",cohorts)]))
  hallmark_top <- head(hallmark[order(-hallmark$mean_abs_NES,hallmark$pathway),],15)
  xc <- setNames(lapply(cohorts,function(c)rd(main,paste0("05_xCell/",c,"_statistics.csv"))),cohorts)
  xcell <- data.frame(cell_type=sort(xc[[1]]$cell_type))
  for(c in cohorts){d <- strict_match(xcell$cell_type,xc[[c]],"cell_type");for(k in c("delta","pval","fdr")) xcell[[paste0(k,"_",c)]]<-d[[k]]}
  xcell$mean_abs_delta <- rowMeans(abs(as.matrix(xcell[paste0("delta_",cohorts)])))
  xcell$all_same_dir <- same_direction(as.matrix(xcell[paste0("delta_",cohorts)]))
  selected <- c("CMP","GMP","HSC","Erythrocytes","iDC","CD4+ Tcm","CD4+ Tem","Th1 cells","NKT")
  xcell_selected <- strict_match(selected,xcell,"cell_type")
  random_summary <- rd(main,"03_Figure3D/Figure3D_summary.csv")
  random <- do.call(rbind,lapply(c("common","full"),function(p){d<-rd(main,paste0("03_Figure3D/old_fixed_",p,"_distribution.csv"));d$pool<-p;d}))
  unadjusted <- rd(downstream,"models/combined_unadjusted/DE_all_genes.csv")
  unadjusted$symbol <- strict_match(unadjusted$gene_id,external,"gene_id")$symbol
  pca <- list()
  if(compute_pca){
    x <- readRDS(file.path(main,"checkpoint_01_identity.rds"))
    meta_samples <- rd(downstream,"models/combined_unadjusted/samples_metadata.csv")
    stopifnot(identical(meta_samples$sample,colnames(x$matrices$GSE65682)))
    for(c in cohorts){
      cat("[PCA] ",c," corrected common-gene matrix\n",sep="")
      pca[[c]] <- pca_coordinates(x$matrices[[c]],if(c=="GSE65682")x$three else x$common,x$groups[[c]])
    }
    pca$GSE65682$MARS <- meta_samples$mars
    pca$GSE65682_signature <- pca_coordinates(x$matrices$GSE65682,extsig$gene_id,x$groups$GSE65682)
    pca$GSE65682_signature$MARS <- meta_samples$mars
    for(m in paste0("Mars",1:4)){
      i <- which(meta_samples$mars==m); cat("[PCA] ",m," corrected common-gene matrix\n",sep="")
      pca[[m]] <- pca_coordinates(x$matrices$GSE65682[,i,drop=FALSE],x$three,x$groups$GSE65682[i])
    }
  }
  z <- list(meta=meta,sig=sig,layout=layout,heatmap=heatmap,de=de,external=external,extsig=extsig,residual=residual,
    ora=ora,ora_all=ora_all,dumbbell=dumbbell,mars=mars,mars_summary=mars_summary,mars3=mars3,
    hallmark=hallmark,hallmark_top=hallmark_top,xcell=xcell,xcell_selected=xcell_selected,
    random=random,random_summary=random_summary,unadjusted=unadjusted,pca=pca,
    e3=fr("e3_composition.csv"),roc=fr("roc_coordinates_unchanged.csv"),roc_summary=fr("roc_summary_unchanged.csv"),
    tf=list(up=fr("tf_chea_up_unchanged.csv"),down=fr("tf_chea_down_unchanged.csv"),encode=fr("tf_encode_up_unchanged.csv")))
  if(!is.null(out)){
    for(nm in c("meta","sig","heatmap","external","extsig","residual","dumbbell","mars","mars_summary","mars3","hallmark","hallmark_top","xcell","xcell_selected","random","random_summary","unadjusted","e3","roc","roc_summary"))write_source(z[[nm]],out,nm)
    for(nm in names(z$ora_all))write_source(z$ora_all[[nm]],out,paste0("ORA_",nm,"_all_tested"))
    for(nm in names(z$pca))write_source(z$pca[[nm]],out,paste0("PCA_",nm))
    for(nm in names(z$tf))write_source(z$tf[[nm]],out,paste0("TF_",nm,"_unchanged"))
  }
  z
}


