COL <- c(Up="#E15759",Down="#4E79A7","Not significant"="#D2D2D2")
COHORT_COL <- c(GSE272769="#4E79A7",GSE95233="#E15759",GSE65682="#B07AA1")
MODULE_COL <- c("Neutrophil degranulation"="#E15759","Cell cycle / proliferation"="#B07AA1","Inflammatory / Down"="#4E79A7",Other="#B6992D",Unclassified="grey50")
MARS_COL <- c(Mars1="#66C2A5",Mars2="#FC8D62",Mars3="#8DA0CB",Mars4="#E78AC3")
base_theme <- function(size=9) ggplot2::theme_bw(base_size=size,base_family="sans") + ggplot2::theme(plot.title=ggplot2::element_text(face="bold",size=size+1),plot.subtitle=ggplot2::element_text(size=size-1),legend.position="bottom",plot.margin=ggplot2::margin(6,8,6,6))
