discovery_display <- function(selected,estimate) ifelse(selected,ifelse(estimate>0,"Up","Down"),"Not retained")
external_effect_group <- function(x) ifelse(abs(x)>.5,"> 0.5","<= 0.5")
XCELL_DISPLAY_ORDER <- c("GSE272769","GSE65682","GSE95233")
module_row_gaps <- function(x) which(head(as.character(x),-1L)!=tail(as.character(x),-1L))
heat_panel <- function(m,title="",annotation=NULL,ann_colors=NULL,numbers=TRUE,number_format="%.2f",limit=NULL,gaps_row=NULL) {
  if(any(!is.finite(m)))stop("Heatmap nonfinite values")
  if(is.null(limit))limit<-max(abs(m)); if(limit<=0)limit<-1
  extra<-list()
  if(!is.null(annotation)){
    stopifnot(identical(rownames(m),rownames(annotation)))
    extra<-list(annotation_row=annotation,annotation_colors=ann_colors,annotation_names_row=FALSE)
    title<-paste0(title,"\nRow annotations (left to right):\n",paste(rev(names(annotation)),collapse=" | "))
  }
  h<-do.call(pheatmap::pheatmap,c(list(mat=m,color=grDevices::colorRampPalette(c("#4E79A7","white","#E15759"))(100),
    breaks=seq(-limit,limit,length.out=101),cluster_rows=FALSE,cluster_cols=FALSE,border_color=NA,
    display_numbers=numbers,number_format=number_format,fontsize=9,fontsize_row=8,fontsize_number=7,
    angle_col=0,main=title,gaps_row=gaps_row,silent=TRUE),extra))
  gt<-h$gtable
  if(!identical(numbers,FALSE)){
    mg<-gt$grobs[[which(gt$layout$name=="matrix")]]
    nt<-sum(vapply(mg$children,function(g)if(inherits(g,"text"))length(g$label)else 0L,integer(1)))
    stopifnot(nt==length(m))
  }
  if(!is.null(annotation))stopifnot(!"row_annotation_names"%in%gt$layout$name)
  gt<-gtable::gtable_add_cols(gt,grid::unit(3,"mm"),0)
  gt<-gtable::gtable_add_cols(gt,grid::unit(3,"mm"),-1)
  gt<-gtable::gtable_add_rows(gt,grid::unit(3,"mm"),0)
  gtable::gtable_add_rows(gt,grid::unit(3,"mm"),-1)
}
plot_volcano <- function(d,title,labels=FALSE){
  d$sig<-factor(de_class(d$logFC,d$adj.P.Val),levels=names(COL))
  d$neglogFDR <- -log10(pmax(d$adj.P.Val,.Machine$double.xmin))
  p<-ggplot2::ggplot(d,ggplot2::aes(logFC,neglogFDR,color=sig))+ggplot2::geom_point(size=.6,alpha=.55)+ggplot2::geom_vline(xintercept=c(-.5,.5),linetype=2,linewidth=.3,color="grey50")+ggplot2::geom_hline(yintercept=-log10(.05),linetype=2,linewidth=.3,color="grey50")+ggplot2::scale_color_manual(values=COL,drop=FALSE)+ggplot2::labs(title=title,subtitle=sprintf("FDR < 0.05 and |log2FC| > 0.5\nUp: %d | Down: %d | Tested: %s",sum(d$sig=="Up"),sum(d$sig=="Down"),format(nrow(d),big.mark=",")),x="log2 fold change (NS vs S)",y="-log10(BH FDR)",color=NULL)+base_theme()
  if(labels){dd<-d[d$sig!="Not significant",]; dd<-dd[order(dd$adj.P.Val,dd$gene_id),];dd<-do.call(rbind,lapply(c("Up","Down"),function(s)head(dd[dd$sig==s,],15)));p<-p+ggrepel::geom_text_repel(data=dd,ggplot2::aes(label=symbol),seed=31,size=2.3,max.overlaps=Inf,min.segment.length=0,box.padding=.3,segment.color="grey65",show.legend=FALSE)}
  p
}
plot_pca <- function(d,title,color_by="outcome"){
  d$group <- if(color_by=="MARS") factor(d$MARS,levels=names(MARS_COL)) else factor(d$outcome,levels=c("Survivor","NonSurvivor"))
  if(anyNA(d$group))stop("Missing PCA grouping")
  cols<-if(color_by=="MARS")MARS_COL else c(Survivor="#4E79A7",NonSurvivor="#E15759")
  ggplot2::ggplot(d,ggplot2::aes(PC1,PC2,color=group))+ggplot2::geom_point(size=1.6,alpha=.8)+ggplot2::stat_ellipse(level=.95,type="t",linewidth=.45)+ggplot2::scale_color_manual(values=cols,drop=FALSE)+ggplot2::labs(title=title,subtitle=sprintf("%s genes | %d samples",format(d$feature_count[1],big.mark=","),nrow(d)),x=sprintf("PC1 (%.1f%%)",d$PC1_pct[1]),y=sprintf("PC2 (%.1f%%)",d$PC2_pct[1]),color=NULL)+base_theme()
}
tf_data <- function(d){
  # These frozen libraries put the TF in the FIRST whitespace-delimited field.
  # Preserve slash-containing complex names; remove only the explicit eGFP tag.
  # Never search later fields: they describe assays, cell lines and species.
  d$TF<-sub("^eGFP-","",sub("[[:space:]].*$","",trimws(d$Term)))
  stopifnot(!anyNA(d$TF),all(grepl("^[A-Za-z0-9][A-Za-z0-9./_-]*$",d$TF)),
    !any(d$TF%in%c("Chip-Seq","ChIP-Seq","ChIP-ChIP","K562")),
    all(is.finite(d$Combined.Score)))
  d<-do.call(rbind,lapply(split(d,d$TF),function(x)x[which.max(x$Combined.Score),,drop=FALSE]))
  d<-head(d[order(-d$Combined.Score,d$TF),],15);d$TF<-factor(d$TF,levels=rev(d$TF));d$Overlap_n<-as.numeric(sub("/.*","",d$Overlap));d
}
plot_external_scatter <- function(d,residual=FALSE){
  d$external_fdr_group<-ifelse(d$external_FDR<.05,"FDR < 0.05","FDR >= 0.05")
  p<-ggplot2::ggplot(d,ggplot2::aes(re_estimate,external_logFC))+ggplot2::geom_hline(yintercept=0,color="grey75",linewidth=.3)+ggplot2::geom_vline(xintercept=0,color="grey75",linewidth=.3)+ggplot2::geom_abline(slope=1,intercept=0,linetype=2,color="grey60",linewidth=.3)
  if(residual){
    p<-p+ggplot2::geom_point(ggplot2::aes(fill=module,shape=external_fdr_group),size=3,color="black",stroke=.3)+ggplot2::scale_fill_manual(values=MODULE_COL)+ggplot2::scale_shape_manual(values=c("FDR < 0.05"=23,"FDR >= 0.05"=21))+ggplot2::geom_segment(ggplot2::aes(xend=label_x,yend=label_y),linewidth=.25,color="grey65")+ggplot2::geom_text(ggplot2::aes(x=label_x,y=label_y,label=gene,hjust=label_hjust),size=2.4)
  }else{
    d$effect_group<-factor(external_effect_group(d$external_logFC),levels=c("> 0.5","<= 0.5"))
    labels<-setNames(sprintf("%s (n = %d)",levels(d$effect_group),as.integer(table(d$effect_group))),levels(d$effect_group))
    p<-p+ggplot2::geom_smooth(data=d,method="lm",formula=y~x,se=TRUE,color="black",fill="grey75",linetype=2,linewidth=.5)+
      ggplot2::geom_point(data=d,ggplot2::aes(color=effect_group),size=2.6)+
      ggplot2::scale_color_manual(values=c("> 0.5"="#E15759","<= 0.5"="#4E79A7"),labels=labels,name="Cohort-adjusted external |log2FC|")+
      ggplot2::geom_hline(yintercept=c(-.5,.5),linetype=3,color="grey65",linewidth=.3)+
      ggrepel::geom_text_repel(data=d[abs(d$external_logFC)>.5,,drop=FALSE],ggplot2::aes(label=gene),seed=32,size=2.2,max.overlaps=Inf,segment.color="grey70")

  }
  st<-sprintf("%d/%d evaluable; %d/%d directionally concordant\nPearson r = %.3f (P = %s); external FDR < 0.05: %d/%d",nrow(d),if(residual) 17L else 32L,sum(d$direction_concordant),nrow(d),cor(d$re_estimate,d$external_logFC),p_text(cor.test(d$re_estimate,d$external_logFC,method="pearson")$p.value),sum(d$external_FDR<.05),nrow(d))
  if(!residual){
    slope<-unname(stats::coef(stats::lm(external_logFC~re_estimate,data=d))[2])
    st<-sprintf("%d/%d evaluable genes retained direction\nDescriptive cross-gene Pearson r = %.3f; external-on-discovery slope = %.3f",sum(d$direction_concordant),nrow(d),cor(d$re_estimate,d$external_logFC),slope)
  }else{
    p<-p+ggplot2::guides(fill=ggplot2::guide_legend(override.aes=list(shape=21),nrow=2),shape=ggplot2::guide_legend(override.aes=list(fill="white")))
  }
  p+ggplot2::labs(title=if(residual)"External assessment of the E3-residual signature" else "External assessment of effect directions and magnitudes",subtitle=st,x="Discovery random-effects log2FC",y="GSE65682 cohort-adjusted log2FC",fill=NULL,shape=NULL)+base_theme(8)+ggplot2::coord_cartesian(clip="off")

}
plot_venn <- function(a,b,title){
  theta<-seq(0,2*pi,length.out=241)
  circ<-rbind(data.frame(x=-.42+cos(theta),y=sin(theta),cohort="GSE272769"),data.frame(x=.42+cos(theta),y=sin(theta),cohort="GSE95233"))
  d<-data.frame(x=c(-.87,0,.87),y=0,n=c(length(setdiff(a,b)),length(intersect(a,b)),length(setdiff(b,a))))
  ggplot2::ggplot(circ,ggplot2::aes(x,y,group=cohort,fill=cohort))+ggplot2::geom_polygon(alpha=.45,color="grey30",linewidth=.5)+ggplot2::geom_text(data=d,ggplot2::aes(x,y,label=n),inherit.aes=FALSE,size=5)+ggplot2::annotate("text",x=c(-.65,.65),y=1.18,label=c("GSE272769","GSE95233"),size=3)+ggplot2::scale_fill_manual(values=c(GSE272769=if(title=="Upregulated")"#F3B6B7"else"#ACC7DF",GSE95233=if(title=="Upregulated")"#E15759"else"#4E79A7"))+ggplot2::coord_equal(xlim=c(-1.5,1.5),ylim=c(-1.1,1.5))+ggplot2::labs(title=paste("Cohort-level DE overlap:",title),subtitle="BH FDR < 0.05 and |log2FC| > 0.5")+ggplot2::theme_void()+ggplot2::theme(legend.position="none",plot.title=ggplot2::element_text(hjust=.5,face="bold"))
}
plot_forest <- function(s,title){
  s<-s[order(-s$mean_abs_logFC,s$gene),]
  d<-do.call(rbind,lapply(c("GSE272769","GSE95233","Random effects"),function(c){fc<-if(c=="GSE272769")s$logFC_272769 else if(c=="GSE95233")s$logFC_95233 else s$re_estimate;se<-if(c=="GSE272769")s$se_272769 else if(c=="GSE95233")s$se_95233 else s$re_se;data.frame(gene=s$gene,cohort=c,estimate=fc,lo=fc-1.96*se,hi=fc+1.96*se)}))
  d$gene<-factor(d$gene,levels=s$gene)
  ggplot2::ggplot(d,ggplot2::aes(estimate,gene,color=cohort,shape=cohort))+ggplot2::geom_vline(xintercept=0,linetype=2,color="grey60",linewidth=.3)+ggplot2::geom_errorbar(ggplot2::aes(xmin=lo,xmax=hi),orientation="y",width=.2,position=ggplot2::position_dodge(width=.55),linewidth=.35)+ggplot2::geom_point(position=ggplot2::position_dodge(width=.55),size=1.5)+ggplot2::scale_color_manual(values=c(GSE272769="#E15759",GSE95233="#4E79A7","Random effects"="black"))+ggplot2::scale_shape_manual(values=c(GSE272769=16,GSE95233=17,"Random effects"=15))+ggplot2::labs(title=title,subtitle=sprintf("%d genes | GSE272769 (n = 161) and GSE95233 D01 (n = 51)",nrow(s)),x="log2FC (95% CI)",y=NULL,color=NULL,shape=NULL)+base_theme(8)
}
