}
render_figures <- function(z,out){
  style <- z$style
  stopifnot(!is.null(style))
  panels<-list(); outputs<-list()
  save<-function(p,stem,category,w=183,h=140,margin_mm=0){
    force(p)
    export_complete_panel(p,out,stem,category,w,h,margin_mm)
    outputs[[stem]]<<-data.frame(figure=stem,category=category,width_mm=w,height_mm=h)
    invisible(NULL)
  }
  # Figure 1: discovery scatter, heterogeneity and fixed-signature heatmap.
  d<-z$meta;d$display<-discovery_display(d$selected,d$re_estimate)
  p1a<-ggplot2::ggplot(d,ggplot2::aes(logFC_272769,logFC_95233,color=display))+ggplot2::geom_point(size=.55,alpha=.55)+ggplot2::geom_hline(yintercept=0,linetype=2,color="grey60",linewidth=.3)+ggplot2::geom_vline(xintercept=0,linetype=2,color="grey60",linewidth=.3)+ggplot2::geom_abline(slope=1,intercept=0,color="grey65",linewidth=.3)+ggplot2::scale_color_manual(values=c(Up=COL[["Up"]],Down=COL[["Down"]],"Not retained"=COL[["Not significant"]]))+ggplot2::labs(title="Cross-cohort discovery",subtitle=sprintf("%s shared genes | %.1f%% same direction",format(nrow(d),big.mark=","),100*mean(d$sign_agree)),x="GSE272769 log2FC",y="GSE95233 log2FC",color=NULL)+base_theme()
  i2levels<-c("<25%","25-50%","50-75%",">=75%","Not estimable")
  p1b<-plot_i2_original(style)
  h<-z$heatmap;m<-as.matrix(h[c("logFC_272769","logFC_95233")]);rownames(m)<-h$gene;colnames(m)<-c("GSE272769","GSE95233")
  ann<-data.frame(Module=h$module,Support=h$individual_cohort_support,I2=h$I2_group,row.names=h$gene)
  ac<-list(Module=MODULE_COL,Support=c("Both cohorts"="#4E79A7","GSE272769 only"="#E15759","GSE95233 only"="#B07AA1","Neither cohort"="grey80"),I2=setNames(c("#4E79A7","#B07AA1","#E15759","#B6992D","grey70"),i2levels))
  p1c<-heat_panel(m,"32-gene mortality-associated signature",ann,ac,TRUE,gaps_row=module_row_gaps(h$module))
  save(p1a,"Figure_1A_Discovery_logFC_scatter","main_figures",130,110);save(p1b,"Figure_1B_Heterogeneity","main_figures",182.88,87.63);save(p1c,"Figure_1C_Signature_heatmap","main_figures",150,190)
  # Figure 2: update frozen-resource ORA, preserve TF analysis and its original rules.
  p2ad<-plot_ora(z$ora$GO_down,"GO BP - Down-regulated");p2au<-plot_ora(z$ora$GO_up,"GO BP - Up-regulated")
  p2b<-plot_ora(z$ora$KEGG_up,"KEGG - Up-regulated",n=Inf)
  p2cu<-plot_tf(z$tf$up,"ChEA_2022: Up-regulated Genes (29 genes)")
  p2cd<-plot_tf_down_original(z,style)
  p2d<-plot_tf(z$tf$encode,"ENCODE TF ChIP-seq 2015: Up-regulated Genes")
  save(p2ad,"Figure_2A_left_GO_BP_Down","main_figures",254,152.4)
  save(p2au,"Figure_2A_right_GO_BP_Up","main_figures",254,152.4)
  save(p2b,"Figure_2B_KEGG","main_figures",254,91.44)
  save(p2cu,"Figure_2C_left_TF_ChEA_Up_unchanged","main_figures",203.2,152.4)
  save(p2cd,"Figure_2C_right_TF_ChEA_Down_unchanged","main_figures",203.2,152.4)
  save(p2d,"Figure_2D_TF_ENCODE_unchanged","main_figures",203.2,152.4)
  # Figure 3: all analysis inputs read from the audited new run.
  p3a<-plot_volcano(z$external,"External cohort: cohort-adjusted DE",TRUE);p3b<-plot_external_scatter(z$extsig)
  p3c<-plot_roc_original(z,style)
  for(k in c("A","B","C"))save(get(paste0("p3",tolower(k))),paste0("Figure_3",k,"_",c(A="Adjusted_volcano",B="External_logFC",C="PC1_ROC_unchanged")[[k]]),"main_figures",if(k=="C")203.2 else 150,if(k=="C")177.8 else 130)
  save(plot_reference_original(z,style),"Figure_3D_PC1_random_reference","main_figures",254,152.4)
  # Figure 4: E3 composition and residual assessment.
  e<-z$e3;e$Layer<-factor(e$Layer,levels=c("Full signature","E3-overlap","E3-residual"))
  ecol<-c("M1 cell cycle/proliferation"="#B07AA1","M2 neutrophil degranulation"="#E15759","Inflammatory/downregulated"="#4E79A7",Other="#B6992D")
  e$Module<-factor(e$Module,levels=names(ecol));e<-e[order(e$Layer,e$Module),]
  e$xend<-ave(e$Genes,e$Layer,FUN=cumsum);e$xstart<-e$xend-e$Genes;e$y<-4-as.numeric(e$Layer)
  p4a<-ggplot2::ggplot(e)+ggplot2::geom_rect(ggplot2::aes(xmin=xstart,xmax=xend,ymin=y-.27,ymax=y+.27,fill=Module),color="white",linewidth=.3)+ggplot2::geom_text(ggplot2::aes(x=(xstart+xend)/2,y=y,label=Genes),size=3)+ggplot2::scale_fill_manual(values=ecol)+ggplot2::scale_y_continuous(breaks=1:3,labels=c("E3-residual\n(n = 17)","E3-overlap\n(n = 15)","Full signature\n(n = 32)"))+ggplot2::scale_x_continuous(breaks=seq(0,32,8),expand=ggplot2::expansion(mult=c(0,.02)))+ggplot2::labs(title="E3 stratification and module composition",x="Number of genes",y=NULL,fill=NULL)+base_theme(8)
  totals<-tapply(e$Genes,e$Layer,sum)
  stopifnot(identical(as.numeric(totals[c("Full signature","E3-overlap","E3-residual")]),c(32,15,17)))
  p4a<-p4a+ggplot2::labs(subtitle=sprintf("E3 overlap: %d/%d (%.1f%%) | Residual: %d/%d (%.1f%%)",totals[2],totals[1],100*totals[2]/totals[1],totals[3],totals[1],100*totals[3]/totals[1]))+
    ggplot2::guides(fill=ggplot2::guide_legend(nrow=2,byrow=TRUE))
  ov<-z$extsig[!z$extsig$gene%in%z$residual$gene,,drop=FALSE]
  stopifnot(nrow(ov)==15L)
  ovlab<-sprintf("E3-overlap direction concordance: discovery cohorts %d/%d; GSE65682 %d/%d",sum(ov$sign_agree),nrow(ov),sum(ov$direction_concordant),nrow(ov))
  p4a<-p4a+ggplot2::annotate("label",x=16,y=0,label=ovlab,size=2.4,linewidth=.2)+ggplot2::expand_limits(y=-.3)
  p4b<-plot_external_scatter(z$residual,TRUE)
  p4c<-plot_dumbbell_original(style)
  for(k in c("A","B","C"))save(get(paste0("p4",tolower(k))),paste0("Figure_4",k,"_",c(A="E3_composition",B="Residual_external",C="Residual_ORA")[[k]]),"main_figures",if(k=="C")170 else 180,if(k=="C")92 else 115)
  # Figure 5: same fixed-gene logFC, refreshed model statistics and provenance.
  ms<-z$mars_summary;ms$label<-sprintf("%d/%d\n(%.1f%%)",ms$agree,ms$total,ms$pct)
  p5a<-ggplot2::ggplot(ms,ggplot2::aes(MARS,pct,fill=MARS))+ggplot2::geom_col(width=.65,alpha=.85)+ggplot2::geom_text(ggplot2::aes(label=label),vjust=-.3,size=3)+ggplot2::geom_hline(yintercept=50,linetype=3,color="grey50")+ggplot2::scale_fill_manual(values=MARS_COL)+ggplot2::scale_y_continuous(limits=c(0,113),breaks=c(0,30,60,90))+ggplot2::labs(title="Discovery-signature concordance by MARS class",subtitle="30 evaluable genes; cohort-adjusted within-class estimates",x=NULL,y="Direction concordance (%)")+base_theme()+ggplot2::theme(legend.position="none")
  mb<-z$mars3;mb$gene<-factor(mb$gene,levels=mb$gene)
  p5b<-ggplot2::ggplot(mb,ggplot2::aes(gene,logFC,fill=display_group))+ggplot2::geom_col(width=.8)+ggplot2::geom_hline(yintercept=0,color="grey30")+ggplot2::geom_hline(yintercept=c(-.2,.2),linetype=2,linewidth=.3)+ggplot2::scale_fill_manual(values=c("Near-zero, discordant"="#8C8C8C","Near-zero, concordant"="#D0D0D0","Direction-concordant"="#4E79A7","Direction-reversed"="#E15759"))+ggplot2::labs(title="Mars3 gene-level log2FC",subtitle=sprintf("Near-zero (|log2FC| <= 0.2): %d\n|log2FC| > 0.2: concordant = %d; reversed = %d",sum(abs(mb$logFC)<=.2),sum(abs(mb$logFC)>.2 & mb$directionally_concordant),sum(abs(mb$logFC)>.2 & !mb$directionally_concordant)),x=NULL,y="log2FC in Mars3")+base_theme(8)+ggplot2::theme(axis.text.x=ggplot2::element_text(angle=55,hjust=1,face="italic"),legend.position="none")
  mh<-sapply(paste0("Mars",1:4),function(c)strict_match(z$extsig$gene,z$mars[z$mars$MARS==c,],"gene")$logFC);rownames(mh)<-z$extsig$gene
  ma<-data.frame(Module=z$extsig$module,row.names=z$extsig$gene);mc<-list(Module=c("Neutrophil degranulation"="#E15759","Cell cycle / proliferation"="#4E79A7","Inflammatory / Down"="#59A14F",Other="#B07AA1"))
  p5c<-heat_panel(mh,"Cohort-adjusted log2FC across MARS classes",ma,mc)
  for(k in c("A","B","C"))save(get(paste0("p5",tolower(k))),paste0("Figure_5",k,"_",c(A="MARS_concordance",B="Mars3_effects",C="MARS_heatmap")[[k]]),"main_figures",170,if(k=="C")210 else 120)
  # Supplementary S1-S4.
  for(i in 1:2){
    c<-c("GSE272769","GSE95233")[i];s<-c("Up","Down")[i]
    save(make_pca_plot(pca_style_data(z$pca[[c]],c)),paste0("Figure_S1",LETTERS[i],"_PCA_",c),"supplementary_figures",177.8,152.4)
    stopifnot(nrow(z$pca[[c]])==c(161L,51L)[i]); ns<-sum(z$pca[[c]]$outcome=="NonSurvivor"); ss<-sum(z$pca[[c]]$outcome=="Survivor"); stopifnot(ns+ss==nrow(z$pca[[c]]));
    save(plot_volcano(z$de[[c]],sprintf("%s: n = %d (%d NS, %d S)",cohort_display(c),ns+ss,ns,ss)),paste0("Figure_S2",LETTERS[i],"_Volcano_",c),"supplementary_figures",140,120)
    a<-z$de$GSE272769;b<-z$de$GSE95233
    p<-plot_venn(a$gene_id[de_class(a$logFC,a$adj.P.Val)==s],b$gene_id[de_class(b$logFC,b$adj.P.Val)==s],if(s=="Up")"Upregulated"else"Downregulated")
    save(p,paste0("Figure_S3",LETTERS[i],"_DE_overlap_",s),"supplementary_figures",130,110)
    save(plot_forest(z$sig[z$sig$direction==s,],paste(s,"signature genes")),paste0("Figure_S4",LETTERS[i],"_Meta_forest_",s),"supplementary_figures",160,if(s=="Up")255 else 80)
  }
  # Supplementary S5 keeps the original nine xCell categories; it does not falsely call all nine concordant.
  cohorts<-names(COHORT_COL);ht<-z$hallmark_top;hm<-as.matrix(ht[paste0("NES_",cohorts)]);rownames(hm)<-gsub("_"," ",sub("^HALLMARK_","",ht$pathway));colnames(hm)<-c("GSE272769","GSE95233 D01","GSE65682\n(cohort-adjusted)")
  pn<-matrix("",nrow=15,ncol=3);for(j in 1:3)pn[,j]<-sprintf("%.2f",hm[,j])
  ph<-heat_panel(hm,"Hallmark pathways: top 15 by mean absolute NES",numbers=pn)
  pairs<-list(c(cohorts[1],cohorts[2]),c(cohorts[1],cohorts[3]),c(cohorts[2],cohorts[3]))
  xc<-do.call(rbind,lapply(cohorts,function(c)data.frame(cell_type=z$xcell_selected$cell_type,cohort=c,delta=z$xcell_selected[[paste0("delta_",c)]])));xc$cell_type<-factor(xc$cell_type,levels=z$xcell_selected$cell_type);xc$cohort<-factor(xc$cohort,levels=XCELL_DISPLAY_ORDER)
  px<-ggplot2::ggplot(xc,ggplot2::aes(cell_type,delta,fill=cohort))+ggplot2::geom_col(position=ggplot2::position_dodge(.8),width=.7,color="white",linewidth=.2)+ggplot2::geom_hline(yintercept=0,color="grey40",linewidth=.4)+ggplot2::scale_fill_manual(values=COHORT_COL)+ggplot2::labs(title="xCell: nine prespecified display categories",subtitle=sprintf("Same direction in all cohorts: %d/9 displayed; %d/%d overall",sum(z$xcell_selected$all_same_dir),sum(z$xcell$all_same_dir),nrow(z$xcell)),x=NULL,y="Delta xCell score (NS - S)",fill=NULL)+base_theme(8)
  save(ph,"Figure_S5A_Hallmark_heatmap","supplementary_figures",190,155)
  for(pair in pairs)save(plot_hallmark_pair(z$hallmark,pair[1],pair[2]),paste0("Figure_S5B_Hallmark_",pair[1],"_vs_",pair[2]),"supplementary_figures",140,120)
  save(px,"Figure_S5C_xCell_selected_categories","supplementary_figures",210,100)
  # Additional, unnumbered analyses. The obsolete workflow Figure 1 is explicitly excluded.
  xx<-z$xcell[order(-z$xcell$mean_abs_delta,z$xcell$cell_type),];xm<-as.matrix(xx[paste0("delta_",cohorts)]);rownames(xm)<-xx$cell_type;colnames(xm)<-cohorts
  xa<-data.frame(Concordance=ifelse(xx$all_same_dir,"All 3 same direction","Discordant"),row.names=xx$cell_type)
  save(full_xcell_gtable(xm,xa),"Additional_xCell_all_types_delta_heatmap","additional_figures",245,390,margin_mm=8)
  save(plot_pca(z$pca$GSE65682,"Common genes: outcome"),"Additional_GSE65682_PCA_A_common_outcome","additional_figures",140,120)
  save(plot_pca(z$pca$GSE65682,"Common genes: MARS","MARS"),"Additional_GSE65682_PCA_B_common_MARS","additional_figures",140,120)
  save(plot_pca(z$pca$GSE65682_signature,"Fixed signature: outcome"),"Additional_GSE65682_PCA_C_signature_outcome","additional_figures",140,120)
  save(plot_pca(z$pca$GSE65682_signature,"Fixed signature: MARS","MARS"),"Additional_GSE65682_PCA_D_signature_MARS","additional_figures",140,120)
  for(m in paste0("Mars",1:4))save(plot_pca(z$pca[[m]],m),paste0("Additional_MARS_common_gene_PCA_",m),"additional_figures",140,120)
  save(plot_volcano(z$unadjusted,"External cohort: unadjusted model",TRUE),"Additional_GSE65682_unadjusted_volcano","additional_figures",160,140)
  manifest<-do.call(rbind,outputs);write.csv(manifest,file.path(out,"logs","figure_export_manifest.csv"),row.names=FALSE)
  invisible(manifest)
}


# ==========================================================================
# Plotting: original_style
# ==========================================================================
# Data adapters and original Count/TF/histogram encodings.
# Other panels deliberately keep version-2 behavior pending their own visual review.
prepare_style_data <- function(z,bundle){
  rd<-function(p)read_table_checked(file.path(bundle,"frozen",p))
  old<-rd("i2_original_layout.csv")
  d<-strict_match(old$gene,z$sig,"gene")
  d$source_order<-old$source_order
  d<-d[order(d$I2,d$source_order),]
  d$gene<-factor(d$gene,levels=d$gene)
  d$I2_category<-cut(d$I2,c(-Inf,25,50,75,Inf),right=FALSE,
    labels=c("I\u00b2 < 25%","25 \u2264 I\u00b2 < 50%","50 \u2264 I\u00b2 < 75%","I\u00b2 \u2265 75%"))
  if(anyNA(d$I2_category))stop("Nonfinite I2 cannot be silently omitted")
  tf<-lapply(z$tf,tf_data)
  for(nm in names(tf)){
    tf[[nm]]$x_value<-if(nm=="down")log10(tf[[nm]]$Combined.Score+1)else tf[[nm]]$Combined.Score
    tf[[nm]]$colour_value<-if(nm=="down")NA_real_ else -log10(tf[[nm]]$P.value)
  }
  assoc<-rd("roc_association_unchanged.csv");rs<-z$roc_summary[z$roc_summary$analysis=="Combined",]
  stopifnot(nrow(assoc)==1,nrow(rs)==1,assoc$analyzed_samples==rs$n)
  annotation<-sprintf("Descriptive AUC = %.3f (95%% CI %.3f-%.3f)\nCohort-adjusted OR per 1-SD PC1 = %.2f (95%% CI %.2f-%.2f)\nP = %.6f",rs$AUC,rs$AUC_CI95_lower,rs$AUC_CI95_upper,assoc$OR_per_1SD,assoc$CI95_lower,assoc$CI95_upper,assoc$Wald_P)
  # Independent panels share one explicit 60-bin grid and identical axes.
  # Edges are based on both corrected distributions and the observed statistic.
  xr<-range(c(z$random$original_statistic_pct,z$random_summary$observed_PC1_variance_pct))
  edges<-seq(xr[1],xr[2],length.out=61L)
  counts<-lapply(c("common","full"),function(p)hist(z$random$original_statistic_pct[z$random$pool==p],breaks=edges,plot=FALSE,include.lowest=TRUE,right=TRUE)$counts)
  ref<-list(bins=60L,breaks=edges,xlim=xr,ylim=c(0,ceiling(max(unlist(counts))*1.1/100)*100),counts_common=counts[[1]],counts_full=counts[[2]])
  db<-z$dumbbell
  labels<-c("GO:0000280"="Nuclear division","GO:0048285"="Organelle fission","GO:0140014"="Mitotic nuclear division","hsa05322"="Systemic lupus erythematosus*","hsa04613"="Neutrophil extracellular\ntrap formation")
  db<-strict_match(names(labels),db,"ID")
  db$Term_display<-factor(unname(labels[db$ID]),levels=rev(unname(labels)))
  db$Full_minus_log10_FDR<- -log10(db$Full_FDR);db$Residual_minus_log10_FDR<- -log10(db$Residual_FDR)
  db$gene_count_change<-paste(db$Full_gene_count,"->",db$Residual_gene_count)
  # The original headline is allowed only if the updated data still support it.
  cc<-db[startsWith(db$ID,"GO:"),];net<-db[db$ID=="hsa04613",]
  stopifnot(all(cc$Residual_FDR<.05),net$Residual_FDR>net$Full_FDR)
  list(i2=d,tf_up=tf$up,tf_down=tf$down,tf_encode=tf$encode,roc_association=assoc,roc_summary=rs,
    roc_annotation=annotation,pc1_pct=z$random_summary$observed_unrounded_pct[1],reference=ref,dumbbell=db)
}
ora_display_original <- function(d,n=10L){
  # Legacy enrichResult tables are ranked by enrichment significance, then
  # selected rows are displayed using reorder(Description, Count).
  d<-d[order(d$pvalue,d$ID),,drop=FALSE]
  if(is.finite(n))d<-head(d,n)
  d
}
plot_ora <- function(d,title,n=10L){
  d<-ora_display_original(d,n)
  if(!nrow(d))return(ggplot2::ggplot()+ggplot2::annotate("text",0,0,label="No terms with BH FDR < 0.05")+ggplot2::labs(title=title)+ggplot2::theme_void())
  ggplot2::ggplot(d,ggplot2::aes(Count,reorder(Description,Count),size=Count,color=p.adjust))+
    ggplot2::geom_point() +
    ggplot2::scale_color_gradient(
      low = "#E15759",
      high = "#4E79A7",
      trans = "log10",
      guide = ggplot2::guide_colourbar(display = "rectangles")
    ) +
    ggplot2::scale_size_continuous(range=c(3,7))+
    ggplot2::labs(title=title,x="Gene count",y="")+ggplot2::theme_bw(11)
}
plot_tf <- function(d,title,down=FALSE){
  if(down)stop("Use the original dedicated downregulated TF function")
  shown<-tf_data(d);shown$neg_log10_p<- -log10(shown$P.value)
  ggplot2::ggplot(shown,ggplot2::aes(x=Combined.Score,y=TF))+
    ggplot2::geom_point(ggplot2::aes(size=Overlap_n,color=neg_log10_p),alpha=.85)+
    ggplot2::scale_color_gradient(
      low = "#B07AA1",
      high = "#E15759",
      name = "-log10(P)",
      guide = ggplot2::guide_colourbar(display = "rectangles")
    ) +
    ggplot2::scale_size_continuous(range=c(3,10),name="n Genes")+
    ggplot2::labs(title=title,x="Combined Score",y=NULL)+
    ggplot2::theme_bw(11)+ggplot2::theme(plot.title=ggplot2::element_text(face="bold",size=12))
}
plot_reference_original <- function(z,s,pool=NULL){
  d<-z$random;q<-z$random_summary
  stopifnot(all(table(d$pool)==10000L),nrow(q)==2L,setequal(q$pool,c("common","full")))
  labels<-c(common="Three-cohort common-gene pool",full="Full GPL13667 gene pool")
  d$Pool<-factor(unname(labels[d$pool]),levels=unname(labels))
  q$Pool<-factor(unname(labels[q$pool]),levels=unname(labels))
  q$label<-sprintf("Observed PC1 = %.1f%%\nUpper-tail proportion = %.4f",q$observed_PC1_variance_pct,q$adjusted_upper_tail_proportion)
  ggplot2::ggplot(d,ggplot2::aes(original_statistic_pct))+
    ggplot2::geom_histogram(breaks=s$reference$breaks,closed="right",fill="grey80",color="white",linewidth=.2)+
    ggplot2::geom_vline(data=q,ggplot2::aes(xintercept=observed_PC1_variance_pct),color="#E15759",linewidth=1)+
    ggplot2::geom_label(data=q,ggplot2::aes(x=Inf,y=Inf,label=label),inherit.aes=FALSE,hjust=1.05,vjust=1.2,size=3,color="#E15759",fill="white",linewidth=.25)+
    ggplot2::facet_wrap(~Pool,nrow=1,scales="fixed")+
    ggplot2::scale_x_continuous(limits=s$reference$xlim,expand=ggplot2::expansion(mult=.05))+
    ggplot2::scale_y_continuous(limits=s$reference$ylim,expand=ggplot2::expansion(mult=c(.025,.025)))+
    ggplot2::labs(title="PC1 coherence relative to random-gene reference sets",
      subtitle=sprintf("Observed PCA: %d evaluable genes from the %d-gene signature; 10,000 random sets per reference pool.",q$evaluable[1],q$signature_total[1]),
      x="PC1 variance explained (%)",y="Number of random gene sets")+
    ggplot2::theme_bw(11)+ggplot2::theme(plot.title=ggplot2::element_text(face="bold",size=12),strip.text=ggplot2::element_text(face="bold"))
}



