  tested_term_n_step12g <- nrow(z$tf$down)
  minimum_fdr_step12g <- min(z$tf$down$Adjusted.P.value)
  stopifnot(all(z$tf$down$Adjusted.P.value >= 0.05))
maximum_x_step12g <- max(
  tf_plot_data_step12g$log10_combined_score
)

