pca_style_data<-function(d,cohort){
  sizes<-c(GSE272769=161L,GSE95233=51L)
  stopifnot(length(cohort)==1L,cohort%in%names(sizes),nrow(d)==sizes[[cohort]],
    all(c("sample","outcome","PC1","PC2","feature_count","PC1_pct","PC2_pct")%in%names(d)),
    !anyNA(d$sample),!anyDuplicated(d$sample),all(nzchar(d$sample)),
    all(vapply(d[c("PC1","PC2","feature_count","PC1_pct","PC2_pct")],is.numeric,logical(1))),
    all(is.finite(as.matrix(d[c("PC1","PC2","feature_count","PC1_pct","PC2_pct")]))),
    all(d$feature_count==19136),length(unique(d$PC1_pct))==1L,length(unique(d$PC2_pct))==1L,
    d$PC1_pct[1]>0,d$PC2_pct[1]>0,d$PC1_pct[1]+d$PC2_pct[1]<100,
    !anyNA(d$outcome),setequal(d$outcome,c("Survivor","NonSurvivor")))
  d$Outcome<-factor(d$outcome,levels=c("Survivor","NonSurvivor"))
  stopifnot(all(table(d$Outcome)>3L))
  list(data=d,n=nrow(d),genes=as.integer(d$feature_count[1]),
    title=if(cohort=="GSE95233")"GSE95233 D01 - PCA by Outcome"else"GSE272769 - PCA by Outcome",
    subtitle=sprintf("%d genes, %d samples | PC1=%.1f%% PC2=%.1f%%",d$feature_count[1],nrow(d),d$PC1_pct[1],d$PC2_pct[1]),
    palette=c(Survivor="#4E79A7",NonSurvivor="#E15759"),point_size=1,point_alpha=.5,base_size=11)
}
make_pca_plot<-function(s){
  ggplot2::ggplot(s$data,ggplot2::aes(PC1,PC2,color=Outcome))+
    ggplot2::geom_point(alpha=s$point_alpha,size=s$point_size)+
    ggplot2::stat_ellipse(level=.95,linewidth=.5)+
    ggplot2::scale_color_manual(values=s$palette)+
    ggplot2::labs(title=s$title,subtitle=s$subtitle,x="PC1",y="PC2",color="Outcome")+
    ggplot2::theme_bw(s$base_size)+ggplot2::theme(legend.position="bottom")
}
validate_native_pca<-function(p,s){
  built<-ggplot2::ggplot_build(p);d<-built$data[[1]]
  same<-function(a,b)isTRUE(all.equal(as.numeric(a),as.numeric(b),tolerance=1e-12))
  stopifnot(nrow(d)==s$n,same(d$x,s$data$PC1),same(d$y,s$data$PC2),
    all(d$size==1),all(d$alpha==.5),all(d$colour==unname(s$palette[as.character(s$data$Outcome)])),
    nrow(built$data[[2]])>0,all(built$data[[2]]$linewidth==.5),
    identical(p$labels$subtitle,s$subtitle),identical(p$labels$colour,"Outcome"))
  TRUE # Plot construction and data encoding only, not a visual acceptance.
}


