check_heatmap_pdf<-function(path){
  stopifnot(file.exists(path),file.info(path)$size>1000)
  x<-readBin(path,"raw",n=file.info(path)$size)
  # PDF streams contain arbitrary binary bytes, not locale-encoded character text.
  # Never pass the whole PDF through rawToChar()/grepl() in a UTF-8 locale.
  has<-function(token)length(grepRaw(charToRaw(token),x,fixed=TRUE))>0L
  stopifnot(identical(head(x,5L),charToRaw("%PDF-")),has("/Font"),has("%%EOF"),has("BT"),(has(" Tj")||has(" TJ")),!has("/Subtype /Image"))
  TRUE # Structural/text-resource check only, not visual approval.
}
full_xcell_gtable<-function(m,ann){
  stopifnot(identical(dim(m),c(67L,3L)),all(is.finite(m)),identical(rownames(m),rownames(ann)))
  limit<-max(abs(m));stopifnot(limit>0)
  h<-pheatmap::pheatmap(m,color=grDevices::colorRampPalette(c("#4E79A7","white","#E15759"))(100),
    breaks=seq(-limit,limit,length.out=101),cluster_rows=FALSE,cluster_cols=FALSE,border_color=NA,
    display_numbers=TRUE,number_format="%.2f",fontsize=9,fontsize_row=8,fontsize_number=7,angle_col=0,
    main="Full xCell landscape\nMean difference (NS - S)",annotation_row=ann,
    annotation_colors=list(Concordance=c("All 3 same direction"="#4E79A7",Discordant="grey80")),
    annotation_names_row=FALSE,silent=TRUE)
  gt<-h$gtable;stopifnot(inherits(gt,"gtable"),"matrix"%in%gt$layout$name)
  mg<-gt$grobs[[which(gt$layout$name=="matrix")]]
  nr<-sum(vapply(mg$children,function(g)if(inherits(g,"rect"))length(g$gp$fill)else 0L,integer(1)))
  nt<-sum(vapply(mg$children,function(g)if(inherits(g,"text"))length(g$label)else 0L,integer(1)))
  stopifnot(nr==201L,nt==201L)
  gt
}
export_complete_panel<-function(p,out,stem,category,w,h,margin_mm=0){
  force(p)
  g<-if(inherits(p,"ggplot"))ggplot2::ggplotGrob(p)else p
  stopifnot(inherits(g,"grob"))
  emit<-function(ext){
    path<-file.path(out,category,paste0(stem,"_v20260910_7.",ext))
    stopifnot(!file.exists(path));cat("[DRAW PANEL] ",stem," [",ext,"]\n",sep="")
    wi<-w/25.4;hi<-h/25.4
    switch(ext,
      pdf=grDevices::pdf(file=path,width=wi,height=hi,bg="white",
        family=CFG$pdf_family,version="1.4",useDingbats=FALSE,onefile=FALSE,compress=CFG$pdf_compress),
      svg=svglite::svglite(filename=path,width=wi,height=hi,bg="white",
        standalone=TRUE,fix_text_size=CFG$svg_fix_text_size),
      png=grDevices::png(path,width=wi,height=hi,units="in",res=CFG$png_dpi,type="cairo",bg="white"),
      tiff=grDevices::tiff(path,width=wi,height=hi,units="in",res=CFG$tiff_dpi,type="cairo",compression="lzw",bg="white"))
    id<-grDevices::dev.cur()
    on.exit(if(id%in%grDevices::dev.list())grDevices::dev.off(id),add=TRUE)
    grid::grid.newpage()
    if(margin_mm>0)grid::pushViewport(grid::viewport(width=grid::unit(1,"npc")-grid::unit(2*margin_mm,"mm"),
      height=grid::unit(1,"npc")-grid::unit(2*margin_mm,"mm"),clip="off"))
    grid::grid.draw(if(ext=="pdf")pdf_math_text(g)else g)
    if(margin_mm>0)grid::popViewport()
    stopifnot(grDevices::dev.cur()==id);grDevices::dev.off(id)
    stopifnot(file.exists(path),file.info(path)$size>1000)
    if(ext=="pdf")check_heatmap_pdf(path)
    if(ext=="svg") {
      txt<-paste(readLines(path,warn=FALSE),collapse="\n")
      if(!grepl("<text[ >]",txt))stop("SVG has no editable text: ",path)
      if(grepl("<image[ >]",txt))stop("Unexpected raster image in SVG: ",path)
    }
  }
  for(ext in c("pdf","svg","png","tiff"))emit(ext)
  invisible(NULL)
}


