export_figure_sources <- function(z,out){
  sources<-list()
  put<-function(stem,...)sources[[stem]]<<-list(...)
  ora_source<-function(d,n=10L){d$displayed_in_panel<-d$ID%in%ora_display_original(d,n)$ID;d}
  dd<-z$meta;dd$display_group<-discovery_display(dd$selected,dd$re_estimate)
  put("Figure_1A_Discovery_logFC_scatter",all_genes=dd)
  put("Figure_1B_Heterogeneity",signature=z$style$i2)
  put("Figure_1C_Signature_heatmap",signature=z$heatmap)
  put("Figure_2A_left_GO_BP_Down",terms=ora_source(z$ora$GO_down))
  put("Figure_2A_right_GO_BP_Up",terms=ora_source(z$ora$GO_up))
  put("Figure_2B_KEGG",terms=ora_source(z$ora$KEGG_up,Inf))
  put("Figure_2C_left_TF_ChEA_Up_unchanged",terms=z$style$tf_up)
  put("Figure_2C_right_TF_ChEA_Down_unchanged",terms=z$style$tf_down)
  put("Figure_2D_TF_ENCODE_unchanged",terms=z$style$tf_encode)
  put("Figure_3A_Adjusted_volcano",all_genes=z$external)
  dd<-z$extsig;dd$display_group<-external_effect_group(dd$external_logFC)
  fit<-stats::lm(external_logFC~re_estimate,data=dd)
  put("Figure_3B_External_logFC",signature=dd,display_summary=data.frame(n=nrow(dd),Pearson_r=cor(dd$re_estimate,dd$external_logFC),intercept=unname(coef(fit)[1]),slope=unname(coef(fit)[2]),abs_logFC_threshold=.5))
  put("Figure_3C_PC1_ROC_unchanged",coordinates=z$roc,summary=z$style$roc_summary,association=z$style$roc_association,annotation=data.frame(annotation=z$style$roc_annotation,PC1_variance_pct=z$style$pc1_pct))
  for(pool in c("common","full")){
    ref<-z$style$reference
    bin_table<-data.frame(left=head(ref$breaks,-1),right=tail(ref$breaks,-1),count=ref[[paste0("counts_",pool)]])
    axes<-data.frame(x_min=ref$xlim[1],x_max=ref$xlim[2],y_min=ref$ylim[1],y_max=ref$ylim[2],bins=ref$bins)
    sources[["Figure_3D_PC1_random_reference"]][[paste0(pool,"_draws")]]<-z$random[z$random$pool==pool,]
    sources[["Figure_3D_PC1_random_reference"]][[paste0(pool,"_summary")]]<-z$random_summary[z$random_summary$pool==pool,]
    sources[["Figure_3D_PC1_random_reference"]][[paste0(pool,"_histogram_bins")]]<-bin_table
    sources[["Figure_3D_PC1_random_reference"]][[paste0(pool,"_shared_axes")]]<-axes
  }
  put("Figure_4A_E3_composition",composition=z$e3,overlap_direction=z$extsig[!z$extsig$gene%in%z$residual$gene,,drop=FALSE])
  put("Figure_4B_Residual_external",signature=z$residual)
  put("Figure_4C_Residual_ORA",terms=z$style$dumbbell)
  put("Figure_5A_MARS_concordance",summary=z$mars_summary,gene_statistics=z$mars)
  put("Figure_5B_Mars3_effects",gene_statistics=z$mars3)
  put("Figure_5C_MARS_heatmap",gene_statistics=z$mars)
  for(i in 1:2){
    cohort<-c("GSE272769","GSE95233")[i];direction<-c("Up","Down")[i]
    put(paste0("Figure_S1",LETTERS[i],"_PCA_",cohort),coordinates=z$pca[[cohort]])
    put(paste0("Figure_S2",LETTERS[i],"_Volcano_",cohort),DE=z$de[[cohort]])
    a<-z$de$GSE272769;b<-z$de$GSE95233
    a<-a[de_class(a$logFC,a$adj.P.Val)==direction,];b<-b[de_class(b$logFC,b$adj.P.Val)==direction,]
    counts<-data.frame(left_only=length(setdiff(a$gene_id,b$gene_id)),shared=length(intersect(a$gene_id,b$gene_id)),right_only=length(setdiff(b$gene_id,a$gene_id)))
    put(paste0("Figure_S3",LETTERS[i],"_DE_overlap_",direction),GSE272769_selected=a,GSE95233_selected=b,counts=counts)
    put(paste0("Figure_S4",LETTERS[i],"_Meta_forest_",direction),signature=z$sig[z$sig$direction==direction,])
  }
  put("Figure_S5A_Hallmark_heatmap",displayed=z$hallmark_top)
  cs<-c("GSE272769","GSE95233","GSE65682")
  for(pair in list(cs[c(1,2)],cs[c(1,3)],cs[c(2,3)])){
    d<-z$hallmark[,c("pathway",paste0("NES_",pair),paste0("padj_",pair))]
    put(paste0("Figure_S5B_Hallmark_",pair[1],"_vs_",pair[2]),all50=d)
  }
  put("Figure_S5C_xCell_selected_categories",displayed=z$xcell_selected,all67=z$xcell,cohort_order=data.frame(display_order=1:3,cohort=XCELL_DISPLAY_ORDER,color=unname(COHORT_COL[XCELL_DISPLAY_ORDER])))
  put("Additional_xCell_all_types_delta_heatmap",all67=z$xcell)
  put("Additional_GSE65682_PCA_A_common_outcome",coordinates=z$pca$GSE65682)
  put("Additional_GSE65682_PCA_B_common_MARS",coordinates=z$pca$GSE65682)
  put("Additional_GSE65682_PCA_C_signature_outcome",coordinates=z$pca$GSE65682_signature)
  put("Additional_GSE65682_PCA_D_signature_MARS",coordinates=z$pca$GSE65682_signature)
  for(m in paste0("Mars",1:4))put(paste0("Additional_MARS_common_gene_PCA_",m),coordinates=z$pca[[m]])
  put("Additional_GSE65682_unadjusted_volcano",all_genes=z$unadjusted)
  index<-list()
  for(stem in names(sources))for(component in names(sources[[stem]])){
    d<-sources[[stem]][[component]];if(!is.data.frame(d)||!nrow(d))stop("Missing panel source: ",stem," / ",component)
    name<-paste0(stem,"_",component);write_source(d,out,name)
    index[[length(index)+1]]<-data.frame(figure=stem,component=component,source_file=paste0("source_data/",name,"_source_data_v20260910_7.csv"),rows=nrow(d))
  }
  index<-do.call(rbind,index)
  write.csv(index,file.path(out,"figure_to_source_data_index.csv"),row.names=FALSE)
  index
}


