verify_manifest <- function(root,m) {
  if(!all(c("path","bytes","md5") %in% names(m))||!nrow(m)||anyNA(m)||anyDuplicated(m$path))stop("Invalid manifest")
  root<-normalizePath(root,winslash="/",mustWork=TRUE)
  for(i in seq_len(nrow(m))){
    rel<-m$path[i]
    if(grepl("^[\\\\/]|^[A-Za-z]:|\\\\",rel)||any(strsplit(rel,"/",fixed=TRUE)[[1]]%in%c("",".","..")))stop("Unsafe manifest path")
    path<-normalizePath(file.path(root,rel),winslash="/",mustWork=TRUE)
    if(!startsWith(path,paste0(root,"/"))||dir.exists(path))stop("Manifest outside expected directory")
    if(file.info(path)$size!=m$bytes[i]||unname(tools::md5sum(path))!=m$md5[i])stop("Input checksum mismatch: ",rel)
  }
  TRUE
}
