run_figure_worker <- function(bundle,analysis_dir,output_root,out_dir=NULL){
  if(!dir.exists(output_root))stopifnot(dir.create(output_root,recursive=TRUE))
  out<-if(is.null(out_dir))file.path(output_root,paste0("run_",format(Sys.time(),"%Y%m%d_%H%M%S"),"_",Sys.getpid()))else out_dir
  stopifnot(!file.exists(out),dir.create(out))
  for(d in c("main_figures","supplementary_figures","additional_figures","source_data","logs"))stopifnot(dir.create(file.path(out,d)))
  log<-file(file.path(out,"logs","run.log"),"wt");sink(log,split=TRUE);sink(log,type="message")
  closed<-FALSE;close_log<-function(){if(!closed){sink(type="message");sink();close(log);closed<<-TRUE}}
  on.exit(close_log(),add=TRUE);err<-NULL;warn<-character();ok<-FALSE
  writeLines("STARTED_NOT_COMPLETE",file.path(out,"STATUS.txt"))
  cat("Bulk complete figure stage v2026-09-10.7\nInput analysis: ",analysis_dir,"\nNew figure output: ",out,"\n",sep="")
  tryCatch(withCallingHandlers({
    if(!identical(as.character(getRversion()),"4.5.1"))stop("Use the audited server R 4.5.1 runtime")
    req<-c("ggplot2","cowplot","ggrepel","pheatmap","svglite","systemfonts")
    missing<-req[!vapply(req,requireNamespace,logical(1),quietly=TRUE)]
    if(length(missing))stop("Missing plotting packages (no automatic installation): ",paste(missing,collapse=", "))
    if(!capabilities("cairo"))stop("R Cairo capability is required for PNG/TIFF export")
    versions<-data.frame(package=req,version=vapply(req,function(p)as.character(utils::packageVersion(p)),character(1)))
    write.csv(versions,file.path(out,"logs","plot_package_versions.csv"),row.names=FALSE)
    writeLines(capture.output(sessionInfo()),file.path(out,"logs","sessionInfo.txt"))
    options(device=function(...)grDevices::pdf(file=NULL))
    cat("[VERIFY] Analysis success gate and checksums of every consumed analysis file...\n")
    status<-readLines(file.path(analysis_dir,"STATUS.txt"),warn=FALSE)
    if(!identical(status,"MATCHES_SCIENTIFIC_FINGERPRINTS"))stop("Input run is not an audited match")
    comparison<-readRDS(file.path(analysis_dir,"final_comparison.rds"));if(!isTRUE(comparison$passed))stop("Audited comparison did not pass")
    m<-read_table_checked(file.path(analysis_dir,"output_manifest.csv"))
    consumed<-strict_match(figure_input_paths(),m,"path")
    verify_manifest(analysis_dir,consumed)
    write.csv(consumed,file.path(out,"logs","input_files_verified.csv"),row.names=FALSE)
    stopifnot(test_helpers(),test_manifest(),test_panel_only(bundle),test_tf_repairs(bundle),test_repair_source_contract())
    cat("[DATA] Reading corrected outputs; no DE, meta-analysis, ORA, GSEA or xCell rerun.\n")
    z<-prepare_figure_data(file.path(analysis_dir,"main"),file.path(analysis_dir,"downstream"),bundle,out)
    z$style<-prepare_style_data(z,bundle)
    stopifnot(test_data(z),test_original_style(z,bundle))
    stopifnot(test_native_style(z,out),test_pca_style(z$pca),test_repaired_native(z,out))
    for(c in c("GSE272769","GSE95233")){
      ps<-pca_style_data(z$pca[[c]],c);stopifnot(validate_native_pca(make_pca_plot(ps),ps))
    }
    source_index<-export_figure_sources(z,out)
    plots<-render_figures(z,out)
    stopifnot(nrow(plots)==42L,setequal(plots$figure,unique(source_index$figure)))
    catalog<-read_table_checked(file.path(bundle,"panel_catalog.csv"))
    planned<-strict_match(plots$figure,catalog,"figure")
    stopifnot(nrow(catalog)==42L,identical(plots$category,planned$category),
      all(plots$width_mm==planned$width_mm),all(plots$height_mm==planned$height_mm))
    paths<-unlist(lapply(seq_len(nrow(plots)),function(i)file.path(out,plots$category[i],paste0(plots$figure[i],"_v20260910_7.",c("pdf","svg","png","tiff")))))
    stopifnot(length(paths)==168L,all(file.exists(paths)),all(file.info(paths)$size>1000))
    for(p in paths[endsWith(paths,".pdf")])stopifnot(check_heatmap_pdf(p))
    cat("[VERIFY] Confirming analysis inputs were not modified...\n")
    verify_manifest(analysis_dir,consumed)
    stopifnot(file.copy(file.path(bundle,"figure_scope.csv"),file.path(out,"logs","figure_scope.csv")))
    writeLines(c("Visual review is mandatory before publication.","Check every independent panel against the originals; assemble manually after review.","Check labels, clipping, fonts, color keys, line breaks, and scale limits.","No local/server visual approval is inferred from successful rendering.","The obsolete workflow Figure 1 is excluded by user instruction."),file.path(out,"logs","VISUAL_REVIEW_REQUIRED.txt"))
    ok<-TRUE
  },warning=function(w){warn<<-c(warn,conditionMessage(w));cat("WARNING: ",conditionMessage(w),"\n",sep="");invokeRestart("muffleWarning")}),error=function(e){err<<-conditionMessage(e);cat("ERROR: ",err,"\n",sep="");writeLines(err,file.path(out,"logs","ERROR.txt"))})
  status<-figure_status(ok,ok,FALSE)
  writeLines(status,file.path(out,"STATUS.txt"));writeLines(warn,file.path(out,"logs","warnings.txt"))
  cat("\nFINAL_STATUS: ",status,"\n",sep="")
  if(ok)cat("42 independent panels, 168 graphical files exported. No assembled figures. Scientific data gates passed.\nFigures still require visual review; this is not publication approval.\n")
  cat("Warnings: ",length(warn),"\nOutput: ",out,"\n",sep="")
  close_log()
  all<-list.files(out,recursive=TRUE,full.names=TRUE);all<-all[!dir.exists(all)]
  write.csv(data.frame(path=substring(all,nchar(out)+2),bytes=file.info(all)$size,md5=unname(tools::md5sum(all))),file.path(out,"output_manifest.csv"),row.names=FALSE)
  if(!ok)stop("Figure child stopped. See its logs/ERROR.txt; original analysis was not overwritten.",call.=FALSE)
  invisible(out)
}


# ==========================================================================
# Plot checks: helpers
# ==========================================================================
test_helpers <- function() {
  fail <- function(expr) stopifnot(inherits(tryCatch(force(expr), error=identity), "error"))
  x <- data.frame(id=c("b","a"), value=c(2,1))
  stopifnot(identical(strict_match(c("a","b"), x, "id")$value,c(1,2)))
  fail(strict_match(c("a","c"),x,"id"))
  fail(strict_match("a",rbind(x,x),"id"))
  stopifnot(identical(de_class(c(.8,-.8,.8,.5),c(.01,.02,.5,.01)), c("Up","Down","Not significant","Not significant")))
  fail(de_class(NA_real_,.1))
  fail(de_class(.8,1.1))
  stopifnot(identical(same_direction(cbind(c(1,-1,0),c(2,-2,1),c(3,-3,1))), c(TRUE,TRUE,FALSE)))
  z <- data.frame(ID=c("a","b"),p.adjust=c(.01,.02))
  stopifnot(identical(strict_match(c("b","a"),z,"ID")$ID,c("b","a")))
  set.seed(27); m <- matrix(rnorm(48),8,6,dimnames=list(paste0("g",1:8),paste0("s",1:6)))
  p <- pca_coordinates(m,rownames(m),setNames(rep(c("Survivor","NonSurvivor"),3),colnames(m)))
  stopifnot(nrow(p)==6,all(is.finite(p$PC1)),length(unique(p$PC1_pct))==1)
  fail(pca_coordinates(m,rownames(m),setNames(rep("Survivor",6),rev(colnames(m)))))
  m[1,] <- 1
  fail(pca_coordinates(m,rownames(m),setNames(rep("Survivor",6),colnames(m))))
  stopifnot(identical(figure_status(TRUE,TRUE,FALSE),"PLOTS_RENDERED_AWAITING_VISUAL_REVIEW"))
  stopifnot(identical(figure_status(FALSE,TRUE,FALSE),"STOPPED_NOT_COMPLETE"))
  cat("PASS: strict identity joins, thresholds, direction, PCA alignment/variance and status gates\n")
  TRUE
}


# ==========================================================================
# Plot checks: manifest
# ==========================================================================
test_manifest <- function() {
  bad <- function(e)stopifnot(inherits(tryCatch(force(e),error=identity),"error"))
  d<-tempfile();dir.create(d);writeLines("original",file.path(d,"data.csv"))
  m<-data.frame(path="data.csv",bytes=file.info(file.path(d,"data.csv"))$size,md5=unname(tools::md5sum(file.path(d,"data.csv"))))
  stopifnot(isTRUE(verify_manifest(d,m)))
  writeLines("mutated",file.path(d,"data.csv"));bad(verify_manifest(d,m))
  m$path<-"../data.csv";bad(verify_manifest(d,m));m$path<-"/data.csv";bad(verify_manifest(d,m))
  m$path<-"data.csv";bad(verify_manifest(d,rbind(m,m)))
  cat("PASS: manifest checksum, traversal, absolute-path and duplicate gates\n")
  TRUE
}


