    sum(de_class(z$de$GSE95233$logFC,z$de$GSE95233$adj.P.Val)=="Up")==45L,
    sum(de_class(z$de$GSE95233$logFC,z$de$GSE95233$adj.P.Val)=="Down")==6L,
    sum(de_class(z$external$logFC,z$external$adj.P.Val)=="Up")==36L,
    sum(de_class(z$external$logFC,z$external$adj.P.Val)=="Down")==9L,
