test_original_style <- function(z,bundle) {
  s<-prepare_style_data(z,bundle)
  stopifnot(nrow(s$i2)==32L,length(unique(s$i2$gene))==32L,
    sum(s$i2$I2<25)==31L,as.character(tail(s$i2$gene,1))=="ABCA13",
    identical(sort(as.character(s$i2$gene)),sort(z$sig$gene)))
  stopifnot(identical(s$tf_up$x_value,s$tf_up$Combined.Score),
    identical(s$tf_encode$x_value,s$tf_encode$Combined.Score),
    all(s$tf_up$colour_value== -log10(s$tf_up$P.value)),
    all(s$tf_down$x_value==log10(s$tf_down$Combined.Score+1)))
  stopifnot(abs(s$roc_association$OR_per_1SD-1.45241562140867)<1e-12,
    abs(s$roc_association$Wald_P-0.000384166659131079)<1e-15,
    grepl("OR",s$roc_annotation),grepl("0.000384",s$roc_annotation),
    s$reference$bins==60L,length(s$reference$breaks)==61L,
    sum(s$reference$counts_common)==10000L,sum(s$reference$counts_full)==10000L)
  stopifnot(identical(s$reference$xlim,range(s$reference$breaks)),
    all(diff(s$reference$breaks)>0),
    min(z$random$original_statistic_pct)>=s$reference$xlim[1],
    max(z$random$original_statistic_pct)<=s$reference$xlim[2],
    max(s$reference$counts_common,s$reference$counts_full)<s$reference$ylim[2])
  for(nm in c("plot_ora","plot_tf","plot_i2_original","plot_roc_original","plot_reference_original","plot_dumbbell_original"))stopifnot(exists(nm,mode="function"))
  stopifnot(!grepl("Gene ratio",paste(deparse(body(plot_ora)),collapse=" ")))
  stopifnot(all(s$dumbbell$Residual_FDR==z$dumbbell$Residual_FDR))
  cat("PASS: original-style data contract: per-gene I2, Count, raw TF score/P, complete ROC statistics, shared 60-bin reference axes\n")
  TRUE
}


# ==========================================================================
# Plot checks: native_style
# ==========================================================================
# Runs only in the server's native R/ggplot2 environment.
# Plot construction checks are not a visual approval or a clipping inspection.
test_native_style <- function(z,out){
  s<-z$style
  plots<-list(
    I2=plot_i2_original(s),
    GO_down=plot_ora(z$ora$GO_down,"GO BP - Down-regulated"),
    GO_up=plot_ora(z$ora$GO_up,"GO BP - Up-regulated"),
    KEGG=plot_ora(z$ora$KEGG_up,"KEGG - Up-regulated",Inf),
    TF_up=plot_tf(z$tf$up,"ChEA_2022: Up-regulated Genes (29 genes)"),
    TF_down=plot_tf_down_original(z,s),
    TF_encode=plot_tf(z$tf$encode,"ENCODE TF ChIP-seq 2015: Up-regulated Genes"),
    ROC=plot_roc_original(z,s),
    Reference=plot_reference_original(z,s),
    Residual_ORA=plot_dumbbell_original(s))
  built<-lapply(plots,ggplot2::ggplot_build)
  same<-function(a,b)isTRUE(all.equal(as.numeric(a),as.numeric(b),tolerance=1e-10))
  stopifnot(nrow(built$I2$data[[1]])==32L,same(built$I2$data[[1]]$y,s$i2$I2))
  for(nm in c("GO_down","GO_up","KEGG")){
    d<-ora_display_original(z$ora[[if(nm=="KEGG")"KEGG_up" else nm]],if(nm=="KEGG")Inf else 10L)
    stopifnot(nrow(d)>0L,same(built[[nm]]$data[[1]]$x,d$Count))
  }
  stopifnot(same(built$TF_up$data[[1]]$x,s$tf_up$Combined.Score),
    same(built$TF_encode$data[[1]]$x,s$tf_encode$Combined.Score),
    same(built$TF_down$data[[1]]$x,s$tf_down$x_value),
    same(plots$TF_up$data$neg_log10_p,s$tf_up$colour_value),
    same(plots$TF_encode$data$neg_log10_p,s$tf_encode$colour_value))
  stopifnot(inherits(plots$ROC$layers[[1]]$geom,"GeomStep"),
    !any(vapply(plots$ROC$layers,function(l)inherits(l$geom,"GeomAbline"),logical(1))),
    same(built$ROC$data[[1]]$y,z$roc$sensitivity),
    identical(as.character(built$ROC$data[[2]]$label),s$roc_annotation))
  for(pool in c("common","full")){
    all_bins<-built$Reference$data[[1]]
    stopifnot(nrow(all_bins)==120L,length(unique(all_bins$PANEL))==2L)
    p<-all_bins[as.integer(all_bins$PANEL)==match(pool,c("common","full")),,drop=FALSE]
    stopifnot(nrow(p)==60L,sum(p$count)==10000L,
      same(p$count,s$reference[[paste0("counts_",pool)]]))
  }
  stopifnot(same(built$Residual_ORA$data[[2]]$x,s$dumbbell$Full_minus_log10_FDR),
    same(built$Residual_ORA$data[[2]]$xend,s$dumbbell$Residual_minus_log10_FDR))
  # This catches construction failures but cannot detect every overlap or clipped glyph.
  for(p in plots)stopifnot(inherits(ggplot2::ggplotGrob(p),"gtable"))
  write.csv(data.frame(panel=names(plots),construction_passed=TRUE,visually_approved=FALSE),
    file.path(out,"logs","native_style_contract.csv"),row.names=FALSE)
  cat("PASS: native ggplot construction and encodings for 11 corrected panels; visual review remains required.\n")
  TRUE
}


