# Plot checks: pca_style
# ==========================================================================
test_pca_style<-function(pca){
  rejects<-function(x)inherits(tryCatch({force(x);NULL},error=function(e)e),"error")
  for(c in c("GSE272769","GSE95233")){
    d<-pca[[c]];s<-pca_style_data(d,c)
    stopifnot(identical(s$data$PC1,d$PC1),identical(s$data$PC2,d$PC2),
      identical(as.character(s$data$Outcome),as.character(d$outcome)),s$genes==19136L,
      identical(s$palette,c(Survivor="#4E79A7",NonSurvivor="#E15759")),
      identical(s$point_size,1),identical(s$point_alpha,.5),s$base_size==11,
      grepl("PC1=",s$subtitle,fixed=TRUE),grepl("PC2=",s$subtitle,fixed=TRUE))
    a<-d;a$sample[2]<-a$sample[1];stopifnot(rejects(pca_style_data(a,c)))
    a<-d;a$outcome<-as.character(a$outcome);a$outcome[1]<-"unknown";stopifnot(rejects(pca_style_data(a,c)))
    a<-d;a$PC1[1]<-NA_real_;stopifnot(rejects(pca_style_data(a,c)))
    a<-d;a$feature_count[1]<-18230;stopifnot(rejects(pca_style_data(a,c)))
  }
  a<-pca_style_data(pca$GSE272769,"GSE272769");b<-pca_style_data(pca$GSE95233,"GSE95233")
  stopifnot(a$n==161L,b$n==51L,
    identical(a$subtitle,"19136 genes, 161 samples | PC1=15.2% PC2=8.7%"),
    identical(b$subtitle,"19136 genes, 51 samples | PC1=15.2% PC2=12.3%"),
    identical(b$title,"GSE95233 D01 - PCA by Outcome"))
  cat("PASS: real PCA coordinates unchanged, restored style specification, exact new labels, invalid inputs rejected\n")
  TRUE
}


# ==========================================================================
# Plot checks: panel_only
# ==========================================================================
test_panel_only <- function(bundle, z=NULL, out=NULL) {
  calls <- character()
  walk <- function(x) {
    if(missing(x))return(invisible(NULL))
    if(is.call(x)) {
      calls <<- c(calls,paste(deparse(x[[1]]),collapse=""))
      for(y in as.list(x)[-1]) walk(y)
    } else if(is.expression(x)||is.pairlist(x)||is.list(x)) for(y in x) walk(y)
  }
  for(n in ls(envir=environment(test_panel_only),all.names=TRUE)) {
    # Figure 3D legitimately preserves the two original within-panel facets.
    if(n=="plot_reference_original")next
    obj<-get(n,envir=environment(test_panel_only));if(is.function(obj))walk(body(obj))
  }
  banned <- c("plot_grid","facet_wrap","facet_grid","wrap_plots","plot_layout","grid.arrange","arrangeGrob","ggarrange")
  used <- sub(".*::","",calls)
  if(any(used%in%banned))stop("Assembly/facet call remains: ",paste(unique(used[used%in%banned]),collapse=", "))
  if(!is.null(z)) {
    ix <- export_figure_sources(z,out)
    stopifnot(length(unique(ix$figure))==42L,all(file.exists(file.path(out,ix$source_file))))
    stopifnot(sum(grepl("^Figure_2A_",unique(ix$figure)))==2L,
      sum(grepl("^Figure_2C_",unique(ix$figure)))==2L,
      sum(grepl("^Figure_3D_",unique(ix$figure)))==1L,
      sum(grepl("^Figure_S5B_",unique(ix$figure)))==3L,
      sum(grepl("^Additional_GSE65682_PCA_",unique(ix$figure)))==4L,
      sum(grepl("^Additional_MARS_common_gene_PCA_",unique(ix$figure)))==4L)
    for(pool in c("common","full")) {
      rows <- ix$figure=="Figure_3D_PC1_random_reference" & ix$component==paste0(pool,"_draws")
      d <- read.csv(file.path(out,ix$source_file[rows]));stopifnot(nrow(d)==10000L,all(d$pool==pool))
    }
    for(i in 1:4){
      rows <- ix$figure==paste0("Additional_MARS_common_gene_PCA_Mars",i)
      d <- read.csv(file.path(out,ix$source_file[rows]));stopifnot(nrow(d)==nrow(z$pca[[paste0("Mars",i)]]))
    }
  }
  cat("PASS: independent panels; only Figure 3D retains its original internal facets\n")
  TRUE
}


