# ==========================================================================
test_tf_repairs <- function(bundle) {
  d<-read.csv(file.path(bundle,'frozen/tf_chea_down_unchanged.csv'),stringsAsFactors=FALSE)
  shown<-tf_data(d)
  stopifnot('UBF1/2'%in%as.character(shown$TF),
    !any(as.character(shown$TF)%in%c('Chip-Seq','ChIP-Seq','K562')))
  r<-shown[as.character(shown$TF)=='UBF1/2',]
  stopifnot(nrow(r)==1L,abs(r$Combined.Score-93.8608893036147)<1e-10,r$Overlap_n==2)
  fixture<-data.frame(Term=c('SMAD2/3 21741376 ChIP-Seq EPCs Human',
    'TCF12/HEB 22897851 ChIP-Seq JUKARTE6-1 Human','eGFP-GATA2 K562 hg19',
    'GATA2 K562 hg19'),Combined.Score=c(5,4,3,2),Overlap='2/100')
  ans<-tf_data(fixture)
  stopifnot(setequal(as.character(ans$TF),c('SMAD2/3','TCF12/HEB','GATA2')),
    ans$Combined.Score[as.character(ans$TF)=='GATA2']==3)
  TRUE
}
test_repaired_native <- function(z,out) {
  # This tests actual ggplot/gtable objects on the server, not publication readiness.
  p<-plot_external_scatter(z$extsig)
  # Train scales through ggplot_build, then test ACTUAL rendered point aesthetics.
  # Calling a fresh manual scale's map() before build can return na.value colours.
  built<-ggplot2::ggplot_build(p)
  point_layer<-which(vapply(p$layers,function(l)inherits(l$geom,'GeomPoint'),logical(1)))
  stopifnot(length(point_layer)==1L)
  pts<-built$data[[point_layer]]
  stopifnot(nrow(pts)==nrow(z$extsig),
    isTRUE(all.equal(as.numeric(pts$x),as.numeric(z$extsig$re_estimate),tolerance=1e-12)),
    isTRUE(all.equal(as.numeric(pts$y),as.numeric(z$extsig$external_logFC),tolerance=1e-12)))
  expected<-ifelse(abs(z$extsig$external_logFC)>.5,'#E15759','#4E79A7')
  stopifnot(identical(toupper(substr(as.character(pts$colour),1,7)),expected),
    any(vapply(p$layers,function(l)inherits(l$geom,'GeomSmooth'),logical(1))),
    grepl('slope',p$labels$subtitle,fixed=TRUE))
  q<-plot_external_scatter(z$residual,TRUE)
  gt<-ggplot2::ggplotGrob(q)
  fills<-character()
  visit<-function(g){
    if(inherits(g,'points'))fills<<-c(fills,as.character(g$gp$fill))
    if(!is.null(g$grobs))for(x in g$grobs)visit(x)
    if(!is.null(g$children))for(x in g$children)visit(x)
  }
  guides<-which(grepl('guide-box',gt$layout$name))
  for(i in guides)visit(gt$grobs[[i]])
  wanted<-unname(MODULE_COL[unique(z$residual$module)])
  stopifnot(all(toupper(wanted)%in%toupper(substr(fills,1,7))))
  h<-z$heatmap;m<-as.matrix(h[c('logFC_272769','logFC_95233')]);rownames(m)<-h$gene
  ann<-data.frame(Module=h$module,Support=h$individual_cohort_support,I2=h$I2_group,row.names=h$gene)
  ac<-list(Module=MODULE_COL,Support=c('Both cohorts'='#4E79A7','GSE272769 only'='#E15759','GSE95233 only'='#B07AA1','Neither cohort'='grey80'),
    I2=setNames(c('#4E79A7','#B07AA1','#E15759','#B6992D','grey70'),c('<25%','25-50%','50-75%','>=75%','Not estimable')))
  hg<-heat_panel(m,'Signature',ann,ac,TRUE,gaps_row=module_row_gaps(h$module))
  stopifnot(inherits(hg,'gtable'),!any(hg$layout$name=='row_annotation_names'))
  mg<-hg$grobs[[which(hg$layout$name=='matrix')]]
  labels<-unlist(lapply(mg$children,function(g)if(inherits(g,'text'))as.character(g$label)else character()))
  stopifnot(length(labels)==64L,identical(sort(unname(labels)),sort(as.vector(sprintf('%.2f',m)))))
  # All three TF displays must retain their raw enrichment statistics.
  for(nm in names(z$tf)){
    shown<-tf_data(z$tf[[nm]]);k<-match(shown$Term,z$tf[[nm]]$Term)
    stopifnot(!anyNA(k),all(shown$Combined.Score==z$tf[[nm]]$Combined.Score[k]),
      all(shown$P.value==z$tf[[nm]]$P.value[k]),all(shown$Adjusted.P.value==z$tf[[nm]]$Adjusted.P.value[k]))
  }
  write.csv(data.frame(check=c('Original external color encoding and lm layer','Actual module legend fill colors','64 heatmap numbers and no overlapping annotation names','TF display statistics unchanged'),passed=TRUE,visually_approved=FALSE),
    file.path(out,'logs','repaired_native_contract.csv'),row.names=FALSE)
  cat('PASS: repaired native plot encodings, module legend colors, heatmap numbers and TF source statistics.\n')
  TRUE
}
test_repair_source_contract <- function() {
  stopifnot(identical(discovery_display(c(TRUE,FALSE,TRUE),c(1,2,-1)),c('Up','Not retained','Down')))
  stopifnot(identical(external_effect_group(c(-.6,-.5,0,.5,.6)),c('> 0.5','<= 0.5','<= 0.5','<= 0.5','> 0.5')))
  stopifnot(identical(module_row_gaps(c('a','a','b','b','c')),c(2L,4L)))
  stopifnot(identical(XCELL_DISPLAY_ORDER,c('GSE272769','GSE65682','GSE95233')))
  TRUE
}


 environment()
}

