safe_input_path <- function(root,rel) {
  if(length(rel)!=1L||is.na(rel)||!nzchar(rel)||grepl('^[\\/]|^[A-Za-z]:|\\\\',rel)||
     any(strsplit(rel,'/',fixed=TRUE)[[1L]]%in%c('','.','..')))stop('Unsafe original input path: ',rel)
  file.path(root,rel)
}
check_original_files <- function(project) {
  m<-ORIGINAL_FILE_PINS;paths<-vapply(m$path,function(p)safe_input_path(project,p),character(1))
  present<-file.exists(paths)
  if(!all(present))stop('Pre-audit project files missing; no additional pack/download is used:\n',
    paste(paths[!present],collapse='\n'))
  hashes<-unname(tools::md5sum(paths))
  if(anyNA(hashes)||any(hashes!=m$md5))stop('Original project file content differs:\n',
    paste(m$path[is.na(hashes)|hashes!=m$md5],collapse='\n'))
  data.frame(scope='project',path=m$path,bytes=file.info(paths)$size,md5=hashes,stringsAsFactors=FALSE)
}
prepare_run_inputs <- function(project,out,env=.GlobalEnv) {
  original<-check_original_files(project)
  root<-file.path(out,'input_snapshot')
  if(file.exists(root))stop('New run input snapshot already exists')
  stopifnot(dir.create(root))
  cache<-capture_original_caches(file.path(root,'analysis/frozen_ora/cache'),env)
  write.csv(cache,file.path(out,'original_environment_resource_check.csv'),row.names=FALSE)
  write.csv(original,file.path(out,'original_files_checked_before.csv'),row.names=FALSE)
  cat('PASS: original project files and original parent GO/KEGG caches checked. No extra input folder or download.\n')
  root
}
materialize_original_inputs <- function(project,out) {
  # Executed in a clean child. Everything written below is generated by THIS run.
  root<-file.path(out,'input_snapshot');stopifnot(dir.exists(root))
  write_new<-function(d,rel,full_precision=FALSE) {
    p<-safe_input_path(root,rel)
    if(file.exists(p))stop('Generated input already exists: ',rel)
    dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
    if(full_precision)write_original_csv_exact(d,p) else
      write.csv(d,p,row.names=FALSE,na='',fileEncoding='UTF-8')
    invisible(p)
  }
  save_new<-function(d,rel) {
    p<-safe_input_path(root,rel);if(file.exists(p))stop('Generated input already exists: ',rel)
    dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE);saveRDS(d,p,version=3)
  }
  original<-check_original_files(project)
  for(i in seq_len(nrow(ORIGINAL_STYLE_INPUTS))) {
    row<-ORIGINAL_STYLE_INPUTS[i,,drop=FALSE]
    candidates<-vapply(strsplit(row$original,'|',fixed=TRUE)[[1L]],function(p)safe_input_path(project,p),character(1))
    present<-candidates[file.exists(candidates)]
    matching<-present[unname(tools::md5sum(present))==row$md5]
    if(!length(matching))stop('Original style/reference input missing or changed: ',row$original)
    dst<-safe_input_path(root,row$target)
    if(file.exists(dst))stop('Generated input already exists: ',row$target)
    dir.create(dirname(dst),recursive=TRUE,showWarnings=FALSE)
    stopifnot(file.copy(matching[1],dst,overwrite=FALSE))
  }
  lookup<-identity_lookup_installed()
  oldmeta<-readRDS(file.path(project,'results_meta/02_meta_analysis/checkpoint_s2.rds'))
  symbols<-sort(unique(as.character(oldmeta$fisher_out$gene)))
  smap<-data.frame(row_id=paste('old_signature',symbols,sep='::'),scope='old_signature',
    source_symbol=symbols,original_eligible='TRUE',stringsAsFactors=FALSE)
  smap<-identity_apply(smap,lookup,'old_signature')
  write_new(smap,'plotting/frozen/signature_identity.csv')
  save_new(original_xcell_resource(),'analysis/main/frozen/xcell_server_reference.rds')
  legacy<-original_ora_inputs(project,lookup,smap)
  files<-c(membership='ora_signature_membership.csv',queries='ora_legacy_queries.csv',
    reference='ora_legacy_reference.csv',geneSets='ora_legacy_geneSets.csv.gz',
    effective='ora_legacy_effective_universe.csv',universe='old_submitted_universe_eg.csv',
    categories='ora_verified_legacy_KEGG_categories.csv')
  for(n in names(files)) {
    rel<-paste0('analysis/downstream/frozen/',files[[n]])
    if(n=='geneSets') {
      p<-safe_input_path(root,rel);dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
      con<-gzfile(p,'wt');tryCatch(write.csv(legacy[[n]],con,row.names=FALSE,na=''),finally=close(con))
    }else write_new(legacy[[n]],rel,full_precision=identical(n,'reference'))
  }
  write_new(ORA_FUNCTION_PINS,'analysis/frozen_ora/ora_function_fingerprints.csv')
  write_new(ANALYSIS_PACKAGE_LOCK,'analysis/package_lock.csv')
  write_new(MAIN_PACKAGE_LOCK,'analysis/main/frozen/package_lock.csv')
  write_new(MAIN_BASELINE_PINS,'analysis/main/baseline_manifest.csv')
  write_new(original,'analysis/external_inputs_manifest.csv')
  write_new(PANEL_CATALOG,'plotting/panel_catalog.csv');write_new(FIGURE_SCOPE,'plotting/figure_scope.csv')
  main<-file.path(root,'analysis/main')
  paths<-list.files(file.path(main,'frozen'),full.names=TRUE)
  write_new(data.frame(path=substring(paths,nchar(main)+2L),md5=unname(tools::md5sum(paths))),
    'analysis/main/frozen_manifest.csv')
  fr<-file.path(root,'analysis/downstream');pr<-file.path(root,'analysis/frozen_ora')
  a<-list.files(file.path(fr,'frozen'),full.names=TRUE)
  b<-c(list.files(file.path(pr,'cache'),full.names=TRUE),file.path(pr,'ora_function_fingerprints.csv'))
  manifest<-rbind(data.frame(scope='bundle',path=substring(a,nchar(fr)+2L),bytes=file.info(a)$size,md5=unname(tools::md5sum(a))),
    data.frame(scope='probe',path=substring(b,nchar(pr)+2L),bytes=file.info(b)$size,md5=unname(tools::md5sum(b))),
    data.frame(scope='analysis',path=c('01_identity/discovery_common_universe.csv','02_DE_Meta/new_selected_signature.csv',
      '02_DE_Meta/GSE65682_DE.csv','approved_decisions/old_signature_decisions.csv'),bytes=0,md5='PENDING_FRESH_ANALYSIS'))
  write_new(manifest,'analysis/downstream/frozen/ora_input_manifest.csv')
  paths<-list.files(root,recursive=TRUE,full.names=TRUE);paths<-paths[!dir.exists(paths)]
  write.csv(data.frame(path=substring(paths,nchar(root)+2L),bytes=file.info(paths)$size,
    md5=unname(tools::md5sum(paths))),file.path(out,'input_snapshot_manifest.csv'),row.names=FALSE)
  cat('PASS: current-run resources derived from original files/packages; original ORA validation inputs reconstructed.\n')
  invisible(root)
}
verify_snapshot <- function(out) {
  m<-read.csv(file.path(out,'input_snapshot_manifest.csv'),stringsAsFactors=FALSE)
  make_plotting_engine()$verify_manifest(file.path(out,'input_snapshot'),m)
}

args <- commandArgs(trailingOnly=TRUE)
child <- length(args)>=1L && identical(args[1L],"--bulk-stage")
if(child){
  stopifnot(length(args)==4L,args[2L]%in%c("check","analysis","figures"))
  CFG<-readRDS(args[3L]);self<-normalizePath(sub("^--file=","",grep("^--file=",commandArgs(FALSE),value=TRUE)),mustWork=TRUE)
  out<-args[4L]
}else{
  of<-vapply(sys.frames(),function(f)if(is.null(f$ofile))""else as.character(f$ofile)[1L],character(1))
  of<-of[nzchar(of)]
  self<-if(length(of))normalizePath(tail(of,1L),mustWork=TRUE) else {
    a<-grep("^--file=",commandArgs(FALSE),value=TRUE)
    if(length(a)!=1L)stop("Save this script and run it with source() or Rscript.")
    normalizePath(sub("^--file=","",a),mustWork=TRUE)
  }
}
if(is.null(CFG$project))CFG$project<-dirname(self)
CFG$project<-normalizePath(CFG$project,winslash="/",mustWork=TRUE)
if(child)CFG$resources<-file.path(out,"input_snapshot")
options(bulk.plain.self=self)
if(isTRUE(getOption("bulk.plain.definitions_only",FALSE))){
  target<-getOption("bulk.plain.definition_target",.GlobalEnv)
  assign("make_analysis_engine",make_analysis_engine,envir=target)
  assign("make_plotting_engine",make_plotting_engine,envir=target)
  assign("pdf_math_label",pdf_math_label,envir=target)
  assign("capture_original_caches",capture_original_caches,envir=target)
  assign("materialize_original_inputs",materialize_original_inputs,envir=target)
  assign("prepare_run_inputs",prepare_run_inputs,envir=target)
  assign("safe_input_path",safe_input_path,envir=target)
  assign("identity_apply",identity_apply,envir=target)
  return(invisible(NULL))
}
if(!CFG$mode%in%c("full","figures","check"))stop("mode must be full, figures, or check")
if(CFG$mode=="figures" && (is.null(CFG$previous_analysis)||!dir.exists(CFG$previous_analysis)))
  stop("figures mode requires an explicit existing CFG$previous_analysis; full mode does not reuse old analysis outputs")
if(!child){
  if(!dir.exists(CFG$project))stop("Project directory missing: ",CFG$project)

  CFG$library_paths<-.libPaths()
  root<-file.path(CFG$project,CFG$output_folder)
  if(!dir.exists(root))stopifnot(dir.create(root))
  out<-file.path(root,paste0("run_",format(Sys.time(),"%Y%m%d_%H%M%S"),"_",Sys.getpid()))
  stopifnot(!file.exists(out),dir.create(out))
  success<-FALSE
  on.exit(if(!success)writeLines("FAILED_NOT_COMPLETE",file.path(out,"STATUS.txt")),add=TRUE)
  CFG$resources<-prepare_run_inputs(CFG$project,out)
  config_file<-file.path(out,"run_config.rds");saveRDS(CFG,config_file)
  stopifnot(file.copy(self,file.path(out,basename(self)),overwrite=FALSE))
  script_hash<-unname(tools::md5sum(self))
  writeLines(c(paste0("SCRIPT_MD5=",script_hash),paste0("SCRIPT=",self),paste0("RESOURCES=",CFG$resources)),file.path(out,"RUN_INPUTS.txt"))
  rs<-file.path(R.home("bin"),if(.Platform$OS.type=="windows")"Rscript.exe"else"Rscript")
  run<-function(stage){
    if(!identical(unname(tools::md5sum(self)),script_hash))stop("Script changed during execution; restart with a new run")
    rc<-system2(rs,c("--vanilla",shQuote(self),"--bulk-stage",stage,shQuote(config_file),shQuote(out)),stdout="",stderr="",wait=TRUE)
    if(rc!=0L)stop("Stage failed: ",stage,". Inspect stage log in ",out)
    receipt<-switch(stage,check=file.path(out,"PREFLIGHT_PASSED.txt"),
      analysis=file.path(out,"analysis","STATUS.txt"),figures=file.path(out,"figures","STATUS.txt"))
    expected<-switch(stage,check="INPUTS_AND_DEPENDENCIES_PASSED",
      analysis="MATCHES_SCIENTIFIC_FINGERPRINTS",figures="PLOTS_RENDERED_AWAITING_VISUAL_REVIEW")
    if(!file.exists(receipt)||!identical(readLines(receipt,warn=FALSE),expected))
      stop("Stage exited without its verified completion receipt: ",stage)
  }
  cat("BULK ANALYSIS AND FIGURES v2026-09-10.7\nMode: ",CFG$mode,"\nOutput: ",out,"\n",sep="")
  run("check")
  if(CFG$mode=="check"){
    writeLines("INPUTS_AND_DEPENDENCIES_CHECKED_NO_ANALYSIS",file.path(out,"STATUS.txt"));success<-TRUE
    cat("Checks passed. No study statistics or figures were produced.\n");return(invisible(out))
  }
  if(CFG$mode=="full")run("analysis")
  run("figures")
  writeLines("ANALYSIS_MATCHED_FIGURES_EXPORTED_ILLUSTRATOR_REVIEW_REQUIRED",file.path(out,"STATUS.txt"))
  success<-TRUE
  cat("\nANALYSIS: ALL 215 SCIENTIFIC OUTPUT CHECKS PASSED\nFIGURES: 42 panels / 168 files exported\nSVG: text-element checks passed\nILLUSTRATOR: manual import/edit verification still required\nOriginal parent BULK objects preserved.\nOutput: ",out,"\n",sep="")
  return(invisible(out))
}

# Each child evaluates this same plain file. No analysis or plotting code is read from resource files.
.libPaths(CFG$library_paths)
Sys.setenv(BULK_LIBS=paste(CFG$library_paths,collapse=.Platform$path.sep))
analysis_dir<-if(CFG$mode=="figures")CFG$previous_analysis else file.path(out,"analysis")
stage<-args[2L]
tryCatch({
  if(stage=="check"){
    log<-file(file.path(out,"preflight.log"),"wt");sink(log,split=TRUE)
    stopifnot(identical(as.character(getRversion()),"4.5.1"),dir.exists(CFG$resources))
    materialize_original_inputs(CFG$project,out)
    e<-make_analysis_engine()
    ctx<-list(project=CFG$project,bundle_dir=file.path(CFG$resources,"analysis"))
    lock<-read.csv(file.path(ctx$bundle_dir,"package_lock.csv"),stringsAsFactors=FALSE)
    for(i in seq_len(nrow(lock)))if(!requireNamespace(lock$package[i],quietly=TRUE)||as.character(utils::packageVersion(lock$package[i]))!=lock$version[i])stop("Frozen package missing/different: ",lock$package[i])
    for(p in c("ggplot2","cowplot","ggrepel","pheatmap","gtable","svglite","systemfonts"))if(!requireNamespace(p,quietly=TRUE))stop("Missing package; install separately before running: ",p)
    stopifnot(capabilities("cairo"),CFG$pdf_family %in% names(grDevices::pdfFonts()))
    if("showtext"%in%loadedNamespaces())stop("showtext is active; use a clean BULK R library/session")
    if(CFG$mode!="figures"){
      m<-read.csv(file.path(ctx$bundle_dir,"external_inputs_manifest.csv"),stringsAsFactors=FALSE)
      checked<-e$bulk_np_manifest(m,ctx)
      write.csv(checked,file.path(out,"original_inputs_preflight.csv"),row.names=FALSE)
    }else{
      pe<-make_plotting_engine()
      stopifnot(dir.exists(analysis_dir),isTRUE(readRDS(file.path(analysis_dir,"final_comparison.rds"))$passed))
      pe$verify_manifest(analysis_dir,read.csv(file.path(analysis_dir,"output_manifest.csv"),stringsAsFactors=FALSE))
    }
    verify_snapshot(out)
    stopifnot(length(SCIENCE_EXPECTED)==215L)
    if(!all(c("filename","standalone","fix_text_size")%in%names(formals(svglite::svglite))))
      stop("Installed svglite lacks the required editable-export interface")
    stopifnot(CFG$png_dpi>0,CFG$tiff_dpi>0)
    fonts<-systemfonts::match_fonts(c("sans","serif","mono"))
    write_font_match_report(fonts,out,c("sans","serif","mono"))
    cat("PASS: font lookup metadata saved; nested fields retained in current-run RDS.\n")
    writeLines(capture.output(sessionInfo()),file.path(out,"preflight_sessionInfo.txt"))
    cat("PASS: original inputs/packages and generated current-run snapshots checked. No extra input directory or download.\n")
    sink();close(log)
    writeLines("INPUTS_AND_DEPENDENCIES_PASSED",file.path(out,"PREFLIGHT_PASSED.txt"))
  }else if(stage=="analysis"){
    verify_snapshot(out)
    e<-make_analysis_engine()
    status<-e$bulk_np_run(list(project=CFG$project,bundle_dir=file.path(CFG$resources,"analysis"),out_dir=analysis_dir))
    if(!identical(status,"MATCHES_SCIENTIFIC_FINGERPRINTS"))stop("Analysis differs from the audited reference; plotting was not started")
  }else{
    Sys.setenv(http_proxy="http://127.0.0.1:9",https_proxy="http://127.0.0.1:9",HTTP_PROXY="http://127.0.0.1:9",HTTPS_PROXY="http://127.0.0.1:9",NO_PROXY="",no_proxy="")
    for(pair in list(c("base","url"),c("utils","download.file"),c("utils","install.packages")))trace(pair[2L],where=asNamespace(pair[1L]),tracer=quote(stop("Offline plotting: network/install blocked")),print=FALSE)
    e<-make_plotting_engine()
    verify_snapshot(out)
    e$run_figure_worker(file.path(CFG$resources,"plotting"),analysis_dir,out,out_dir=file.path(out,"figures"))
    verify_snapshot(out)
  }
},error=function(err){
  writeLines(conditionMessage(err),file.path(out,paste0(stage,"_ERROR.txt")))
  cat("ERROR: ",conditionMessage(err),"\n",sep="")
  quit(save="no",status=2L)
})


})
